// ── js/skill-core.js ──
// === 书斋 V65 技能包系统 ===
// 类似灵蟹创作的插件市场，用户可安装/创建/管理技能包
// 四种类型：rules(规则约束) / skill(技能流程) / prompt(提示词模板) / workflow(工作流)


// === 技能包核心逻辑（从 skills.js 拆分） ===
// 依赖 skill-data.js 提供的 SkillData.BUILTIN_SKILLS
var SkillPack = (function() {
  var STORAGE_KEY = 'shuzhai_skills';
  var ENABLED_KEY = 'shuzhai_skills_enabled';

  // 从 skill-data.js 读取内置技能包数据
  var BUILTIN_SKILLS = (typeof SkillData !== 'undefined' && SkillData.BUILTIN_SKILLS) ? SkillData.BUILTIN_SKILLS : [];

  // === 存储 ===
  function _getAll() {
    var raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    try { return JSON.parse(raw); } catch(e) { return []; }
  }

  function _saveAll(skills) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(skills));
  }

  function _getEnabled() {
    var raw = localStorage.getItem(ENABLED_KEY);
    if (!raw) return {};
    try { return JSON.parse(raw); } catch(e) { return {}; }
  }

  function _saveEnabled(map) {
    localStorage.setItem(ENABLED_KEY, JSON.stringify(map));
  }

  // === 后端导入的技能包缓存 ===
  // 从后端 /api/skills/list 加载的导入技能包（保存在项目 skills/ 目录）
  var _importedCache = [];

  // 从后端加载导入的技能包到内存缓存
  async function loadImported() {
    try {
      var r = await api('/api/skills/list');
      if (r && r.ok && Array.isArray(r.skills)) {
        _importedCache = r.skills.map(function(s) {
          s.imported = true;
          s.builtin = false;
          return s;
        });
      } else {
        _importedCache = [];
      }
    } catch(e) {
      console.error('[SkillPack] 加载导入技能包失败:', e);
      _importedCache = [];
    }
    return _importedCache;
  }

  // 上传技能包到后端（支持 File 对象或 JSON 字符串）
  async function importToBackend(fileOrText, filename) {
    var formData = new FormData();
    if (typeof fileOrText === 'string') {
      // 粘贴的 JSON 文本，构造为 File 对象
      var blob = new Blob([fileOrText], {type: 'application/json'});
      formData.append('file', blob, filename || ('skill_' + Date.now() + '.json'));
    } else if (fileOrText instanceof File || fileOrText instanceof Blob) {
      formData.append('file', fileOrText, filename || fileOrText.name || 'skill.json');
    } else {
      throw new Error('参数必须是 File 对象或 JSON 字符串');
    }
    // 注意：FormData 不能手动设置 Content-Type，浏览器会自动添加 boundary
    var headers = {};
    var token = (typeof _getToken === 'function') ? _getToken() : (localStorage.getItem('shuzhai_token') || '');
    if (token) headers['Authorization'] = 'Bearer ' + token;
    var serverBase = (typeof _getServerBase === 'function') ? _getServerBase() : '';
    var resp = await fetch(serverBase + '/api/skills/import', {
      method: 'POST',
      headers: headers,
      body: formData
    });
    var data = await resp.json();
    if (!data.ok) {
      throw new Error(data.error || '导入失败');
    }
    // 导入成功后刷新缓存
    await loadImported();
    return data;
  }

  // 从后端删除导入的技能包
  async function removeImported(id) {
    var serverBase = (typeof _getServerBase === 'function') ? _getServerBase() : '';
    var headers = {};
    var token = (typeof _getToken === 'function') ? _getToken() : (localStorage.getItem('shuzhai_token') || '');
    if (token) headers['Authorization'] = 'Bearer ' + token;
    var resp = await fetch(serverBase + '/api/skills/' + encodeURIComponent(id), {
      method: 'DELETE',
      headers: headers
    });
    var data = await resp.json();
    if (!data.ok) {
      throw new Error(data.error || '删除失败');
    }
    // 删除成功后刷新缓存
    await loadImported();
    // 清除启用状态
    var enabled = _getEnabled();
    delete enabled[id];
    _saveEnabled(enabled);
    return data;
  }

  // === API ===
  function listAll() {
    var custom = _getAll();
    // 合并内置、自定义和后端导入的技能包
    var all = BUILTIN_SKILLS.map(function(s) {
      return Object.assign({}, s);
    });
    custom.forEach(function(s) {
      if (!all.find(function(a) { return a.id === s.id; })) {
        all.push(s);
      }
    });
    // 合并后端导入的技能包
    _importedCache.forEach(function(s) {
      if (!all.find(function(a) { return a.id === s.id; })) {
        all.push(Object.assign({}, s));
      }
    });
    // 标记启用状态
    var enabled = _getEnabled();
    all.forEach(function(s) {
      // 优先使用用户设置；未设置过时用 defaultEnabled（默认true）
      if (enabled[s.id] !== undefined && enabled[s.id] !== null) {
        s.enabled = enabled[s.id];
      } else {
        s.enabled = s.defaultEnabled !== false;
      }
    });
    return all;
  }

  function listByType(type) {
    return listAll().filter(function(s) { return s.type === type; });
  }

  function listByScope(scope) {
    return listAll().filter(function(s) {
      return s.scope === scope || s.scope === 'all';
    });
  }

  function getEnabledByScope(scope) {
    return listAll().filter(function(s) {
      return s.enabled && (s.scope === scope || s.scope === 'all');
    });
  }

  function getSkill(id) {
    return listAll().find(function(s) { return s.id === id; });
  }

  function enable(id) {
    var enabled = _getEnabled();
    enabled[id] = true;
    _saveEnabled(enabled);
  }

  function disable(id) {
    var enabled = _getEnabled();
    enabled[id] = false;
    _saveEnabled(enabled);
  }

  function toggle(id) {
    var skill = getSkill(id);
    if (!skill) return;
    if (skill.enabled) disable(id);
    else enable(id);
  }

  function add(skill) {
    if (!skill.id) skill.id = 'custom_' + Date.now();
    if (!skill.version) skill.version = '1.0.0';
    if (!skill.author) skill.author = '用户';
    if (!skill.type) skill.type = 'rules';
    if (!skill.scope) skill.scope = 'generate';
    skill.builtin = false;
    skill.created = new Date().toISOString();
    var skills = _getAll();
    skills.push(skill);
    _saveAll(skills);
    return skill;
  }

  function update(id, data) {
    var skills = _getAll();
    var idx = skills.findIndex(function(s) { return s.id === id; });
    if (idx >= 0) {
      skills[idx] = Object.assign(skills[idx], data);
      _saveAll(skills);
    }
  }

  function remove(id) {
    var skills = _getAll();
    var idx = skills.findIndex(function(s) { return s.id === id; });
    if (idx >= 0) {
      skills.splice(idx, 1);
      _saveAll(skills);
    }
    // 清除启用状态
    var enabled = _getEnabled();
    delete enabled[id];
    _saveEnabled(enabled);
  }

  // === 导入/导出 ===
  function exportSkill(id) {
    var skill = getSkill(id);
    if (!skill) return null;
    return JSON.stringify(skill, null, 2);
  }

  function importSkill(jsonStr) {
    try {
      var skill = JSON.parse(jsonStr);
      if (!skill.name || !skill.content) throw new Error('格式错误：缺少name或content');
      // 重新生成ID避免冲突
      skill.id = 'imported_' + Date.now();
      skill.builtin = false;
      skill.imported = new Date().toISOString();
      return add(skill);
    } catch(e) {
      throw new Error('导入失败：' + e.message);
    }
  }

  // === 获取生效的规则文本（用于生成时注入） ===
  function getActiveRules(scope) {
    var rules = getEnabledByScope(scope);
    var texts = [];
    rules.forEach(function(r) {
      if (r.type === 'rules' && r.content) {
        texts.push(r.content);
      }
    });
    return texts.length > 0 ? texts.join('\n\n---\n\n') : '';
  }

  // 获取指定scope下所有启用技能包的内容（用于生成时注入）
  function getEnabledSkillsContent(scope) {
    var skills = getEnabledByScope(scope);
    var texts = [];
    skills.forEach(function(s) {
      if (s.content) {
        texts.push(s.content);
      }
    });
    return texts.length > 0 ? texts.join('\n\n---\n\n') : '';
  }

  // === 匹配触发词 ===
  function matchTrigger(text) {
    var skills = listAll().filter(function(s) {
      return s.type === 'skill' && s.enabled && s.trigger;
    });
    for (var i = 0; i < skills.length; i++) {
      var triggers = skills[i].trigger.split('|');
      for (var j = 0; j < triggers.length; j++) {
        if (text.indexOf(triggers[j].trim()) >= 0) {
          return skills[i];
        }
      }
    }
    return null;
  }

  // === 获取技能prompt ===
  function getSkillPrompt(id) {
    var skill = getSkill(id);
    if (!skill) return '';
    return skill.content || '';
  }

  return {
    BUILTIN_SKILLS: BUILTIN_SKILLS,
    listAll: listAll,
    listByType: listByType,
    listByScope: listByScope,
    getEnabledByScope: getEnabledByScope,
    getSkill: getSkill,
    enable: enable,
    disable: disable,
    toggle: toggle,
    add: add,
    update: update,
    remove: remove,
    exportSkill: exportSkill,
    importSkill: importSkill,
    getActiveRules: getActiveRules,
    getEnabledSkillsContent: getEnabledSkillsContent,
    matchTrigger: matchTrigger,
    getSkillPrompt: getSkillPrompt,
    // 后端导入技能包相关
    loadImported: loadImported,
    importToBackend: importToBackend,
    removeImported: removeImported
  };
})();


// ── js/api.js ──
// ══════════════════════════════════════════
// Service Worker 版本协调
// ══════════════════════════════════════════
const SW_CACHE_VERSION = 'shuzhai-v1';

// 检测 SW 更新并提示用户
function checkServiceWorkerUpdate() {
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.getRegistration().then(function(reg) {
      if (reg && reg.waiting) {
        console.log('[API] SW 更新就绪，刷新页面以应用新版本');
      }
    });
  }
}

// === 书斋 V65 后端 API 桥接 ===
// 优先使用用户配置的服务器地址（APK模式），否则用当前页面地址
function _getServerBase() {
  var saved = localStorage.getItem('shuzhai_server');
  if (saved) return saved.replace(/\/+$/, '');
  // Capacitor/Android环境：从本地assets加载，API调用本地服务器
  if (window.location.protocol === 'file:' ||
      (typeof Capacitor !== 'undefined' && Capacitor.isNative) ||
      window.location.hostname === 'localhost' && window.location.port === '') {
    return 'http://127.0.0.1:8888';
  }
  return window.location.origin;
}

const API_BASE = _getServerBase();

// 单用户模式 — 无认证，直接返回请求头
function _authHeaders(extra) {
  return extra || {};
}

// 工具函数：智能分段（中文语义）
function smartParagraphSplit(text) {
  if (!text || text.includes('\n\n')) return text;
  var sentences = text.split(/([。！？…]+(?:」|』|"|')?)/);
  var result = '';
  var para = '';
  var count = 0;
  for (var i = 0; i < sentences.length; i += 2) {
    var s = (sentences[i] || '') + (sentences[i + 1] || '');
    if (!s.trim()) continue;
    para += s;
    count++;
    var isDialogueEnd = /[。！？…][」'"']$/.test(s.trim());
    var isSceneShift = false;
    var next = sentences[i + 2] || '';
    if (next && /^\s*(此时|忽然|突然|就在这时|与此同时|另一边|远处|翌日|次日|数日后|当晚|夜深|清晨|午后|傍晚|那|这|只见|但|然而|不过|可是|原来)/.test(next)) {
      isSceneShift = true;
    }
    if (isDialogueEnd || isSceneShift || count >= 5) {
      result += para.trim() + '\n\n';
      para = '';
      count = 0;
    }
  }
  if (para.trim()) result += para.trim();
  return result;
}

// 工具函数：将纯文本转换为HTML段落
function textToHTML(text) {
  if (!text) return '<p></p>';
  // 清除AI编辑批注，防止混入正文
  if (typeof _stripEditAnnotations === 'function') text = _stripEditAnnotations(text);
  // 如果文本已经是HTML（包含<p>标签），直接返回，避免二次包裹
  if (/<p[\s>]/i.test(text) || /<h[1-6][\s>]/i.test(text) || /<br[\s\/>]/i.test(text)) {
    return text;
  }
  // 如果文本没有段落分隔，自动按中文语义分段
  text = smartParagraphSplit(text);
  const paragraphs = text.split(/\n\s*\n/);
  return paragraphs.map(p => {
    const trimmed = p.trim();
    if (!trimmed) return '';
    // 处理markdown标题 (# → h2, ## → h3)
    if (/^#{1,3}\s/.test(trimmed)) {
      var level = (trimmed.match(/^#+/) || [''])[0].length;
      var titleText = trimmed.replace(/^#+\s/, '');
      return '<h' + (level + 1) + ' class="md-heading">' + titleText + '</h' + (level + 1) + '>';
    }
    const withBr = trimmed.replace(/\n/g, '<br>');
    return '<p>' + withBr + '</p>';
  }).filter(p => p).join('\n');
}

// 把 error 字段统一转为可读字符串
function _flattenError(obj) {
  if (!obj) return '';
  if (typeof obj === 'string') return obj;
  if (typeof obj === 'object') {
    if (obj.message) return obj.message;
    if (obj.error) return _flattenError(obj.error);
    try { return JSON.stringify(obj); } catch(_) { return String(obj); }
  }
  return String(obj);
}

// === 超时与重试配置 ===
var _API_DEFAULT_TIMEOUT = 30000; // 30秒超时
var _API_MAX_RETRIES = 2;         // 最多重试2次（首次+2次重试=共3次请求）
var _API_RETRY_DELAY_BASE = 1000; // 指数退避基数（毫秒）

// 判断是否应该重试
function _apiShouldRetry(error, attempt, status, maxRetries) {
  var limit = (typeof maxRetries === 'number') ? maxRetries : _API_MAX_RETRIES;
  if (attempt >= limit) return false;
  if (!status) return true; // 网络错误（无 status）重试
  if (status >= 500 && status < 600) return true; // 5xx 服务端错误重试
  if (status === 429) return true; // 429 限流重试
  return false; // 4xx 客户端错误不重试
}

// 指数退避等待
function _apiWait(attempt) {
  var delay = _API_RETRY_DELAY_BASE * Math.pow(2, attempt - 1);
  return new Promise(function(resolve) {
    setTimeout(resolve, delay);
  });
}

async function api(path, opts={}) {
  // 离线模式：APK环境且配置了离线模式
  if (window._isOfflineMode && window.OfflineAPI) {
    try {
      return await OfflineAPI.handle(path, opts || {});
    } catch(e) {
      console.error('[OfflineAPI]', path, e);
      return {ok: false, error: e.message};
    }
  }

  var timeout = opts.timeout || _API_DEFAULT_TIMEOUT;
  var maxRetries = opts.retries !== undefined ? opts.retries : _API_MAX_RETRIES;
  var attempt = 0;
  var lastError = null;

  function doRequest() {
    attempt++;
    return new Promise(function(resolve) {
      var controller = new AbortController();
      var timeoutId = setTimeout(function() {
        controller.abort();
      }, timeout);

      try {
        var headers = _authHeaders({'Content-Type': 'application/json'});
        if (opts.headers) Object.assign(headers, opts.headers);
        var fetchOpts = Object.assign({}, opts, {
          headers: headers,
          signal: controller.signal
        });

        fetch(API_BASE + path, fetchOpts)
          .then(function(res) {
            clearTimeout(timeoutId);

            if (res.status === 401) {
              // 单用户模式不再有401，如果出现说明服务异常
              resolve({ok:false, error:'服务异常(status 401)'});
              return;
            }

            if (!res.ok) {
              // 判断是否重试
              if (_apiShouldRetry(null, attempt, res.status, maxRetries)) {
                _apiWait(attempt).then(function() {
                  doRequest().then(resolve);
                });
                return;
              }

              var errBody = '';
              try {
                res.json().then(function(errData) {
                  try { errBody = JSON.stringify(errData); } catch(_) {}
                  var errMsg = res.status + ' ' + res.statusText + (errBody ? ' ' + errBody.substring(0, 200) : '');
                  resolve({ok: false, error: errMsg});
                }).catch(function() {
                  resolve({ok: false, error: res.status + ' ' + res.statusText});
                });
              } catch(_) {
                resolve({ok: false, error: res.status + ' ' + res.statusText});
              }
              return;
            }

            res.json().then(function(data) {
              // 统一处理：把 error 字段转为字符串，避免 [object Object]
              if (data && data.ok === false && data.error) {
                data.error = _flattenError(data.error);
              }
              resolve(data);
            }).catch(function(e) {
              // JSON 解析失败
              if (_apiShouldRetry(e, attempt, res.status, maxRetries)) {
                _apiWait(attempt).then(function() {
                  doRequest().then(resolve);
                });
                return;
              }
              resolve({ok: false, error: '响应解析失败: ' + e.message});
            });
          })
          .catch(function(e) {
            clearTimeout(timeoutId);
            var isTimeout = e.name === 'AbortError';
            var errorMsg = isTimeout ? '请求超时（' + (timeout/1000) + '秒）' : (e.message || '网络错误');
            lastError = errorMsg;

            // 判断是否重试
            if (_apiShouldRetry(e, attempt, isTimeout ? 0 : null, maxRetries)) {
              console.warn('[API] 第' + attempt + '次失败，重试中...', path, errorMsg);
              _apiWait(attempt).then(function() {
                doRequest().then(resolve);
              });
              return;
            }

            console.error('[API]', path, errorMsg);
            resolve({ok: false, error: errorMsg});
          });
      } catch(e) {
        clearTimeout(timeoutId);
        console.error('[API]', path, e);
        resolve({ok: false, error: e.message});
      }
    });
  }

  return doRequest();
}

