// 单用户模式 — 无需认证检查

// === === === 双模式：电脑端走后端，手机端走本地 === === ===
// 检测是否在Capacitor(APK)环境中运行
// 有Python后端时(Chaquopy)禁用本地模式，使用API
var _HAS_PY_BACKEND = (typeof window.Capacitor !== 'undefined') ||
                      (window.location.protocol === 'https:' && window.location.hostname === 'localhost' && !window.location.port);
var _IS_MOBILE = _HAS_PY_BACKEND ? false :
                 (typeof window.Capacitor !== 'undefined') ||
                 (window.location.protocol === 'file:') ||
                 (navigator.userAgent.indexOf('Android') >= 0 && window.location.hostname === 'localhost' && !window.location.port);
if (_HAS_PY_BACKEND) {
  console.log('[双模式] 检测到内嵌Python后端，使用API模式+重试');
  var _apiRetry = api;
  window.api = async function(path, opts) {
    for (var i = 0; i < 60; i++) {
      try { return await _apiRetry(path, opts); }
      catch(e) { if (i < 59) { await new Promise(r => setTimeout(r, 1000)); } else throw e; }
    }
  };
}

// 如果是手机端模式，且本地模块已加载，覆盖api()函数为本地路由
if (_IS_MOBILE && typeof LocalDB !== 'undefined' && typeof AIEngine !== 'undefined') {
  console.log('[双模式] 检测到手机端环境，切换到本地模式');
  
  // 保存原始api函数（用于fallback）
  var _origApi = api;

  // 覆盖api函数：路由到LocalDB/AIEngine
  window.api = async function(path, opts) {
    opts = opts || {};
    var method = (opts.method || 'GET').toUpperCase();
    var body = opts.body ? JSON.parse(opts.body) : {};

    // ── 认证 ──
    if (path === '/api/auth/status') return { auth_required: false, username: 'local' };
    if (path === '/api/auth/login') return { ok: true, token: 'local', username: body.username || 'local' };
    if (path === '/api/auth/register') return { ok: true, token: 'local', username: body.username || 'local' };
    if (path === '/api/auth/logout') return { ok: true };

    // ── 项目管理 ──
    if (path === '/api/project/status') return LocalDB.getStatus();
    if (path === '/api/project/new' && method === 'POST') return LocalDB.newProject(body.title, body.genre, body.length);
    if (path === '/api/project/info') return LocalDB.getProjectInfo();
    if (path === '/api/project/save' && method === 'POST') return { ok: true };
    if (path === '/api/project/list') return { ok: true, projects: LocalDB.listProjects() };
    if (path === '/api/project/settings') {
      if (method === 'GET') return LocalDB.getSettings();
      return LocalDB.updateSettings(body);
    }
    if (path === '/api/project/outline') {
      if (method === 'GET') return LocalDB.getOutline();
      return LocalDB.saveOutline(body.outline || body.text || '');
    }
    if (path === '/api/project/novel-outline') {
      if (method === 'GET') return LocalDB.getNovelOutlineStructured();
      return LocalDB.saveNovelOutlineStructured(body);
    }
    if (path === '/api/project/volumes') {
      if (method === 'GET') return LocalDB.getVolumes();
      return LocalDB.saveVolumes(body);
    }
    if (path === '/api/project/volume/add' && method === 'POST') {
      var meta = LocalDB.getProjectMeta();
      if (!meta) return { ok: false, error: '没有项目' };
      if (!meta.volumes) meta.volumes = [];
      meta.volumes.push({index: meta.volumes.length + 1, title: body.title || '新卷', outline: '', chapters: []});
      LocalDB.saveProjectMeta(meta);
      return { ok: true, volumes: meta.volumes };
    }
    if (path === '/api/project/volume/delete' && method === 'POST') {
      var meta = LocalDB.getProjectMeta();
      if (!meta) return { ok: false, error: '没有项目' };
      var vi = body.vol_index || body.index || 0;
      if (meta.volumes && meta.volumes[vi]) {
        var moveChs = meta.volumes[vi].chapters || [];
        if (vi > 0 && meta.volumes[vi-1]) {
          meta.volumes[vi-1].chapters = (meta.volumes[vi-1].chapters || []).concat(moveChs);
        }
        meta.volumes.splice(vi, 1);
        meta.volumes.forEach(function(v, i) { v.index = i + 1; });
        LocalDB.saveProjectMeta(meta);
      }
      return { ok: true, volumes: meta ? meta.volumes : [] };
    }
    if (path === '/api/project/volume/rename' && method === 'POST') {
      var meta = LocalDB.getProjectMeta();
      if (!meta) return { ok: false, error: '没有项目' };
      var vi = body.vol_index || body.index || 0;
      if (meta.volumes && meta.volumes[vi]) {
        meta.volumes[vi].title = body.title || '未命名';
        LocalDB.saveProjectMeta(meta);
      }
      return { ok: true, volumes: meta ? meta.volumes : [] };
    }
    if (path === '/api/project/auto-volumes' && method === 'POST') {
      var meta = LocalDB.getProjectMeta();
      if (!meta) return { ok: false, error: '没有项目' };
      var ol = LocalDB.getOutline();
      var lines = (ol.outline || '').split('\n');
      var volumes = [];
      var currVol = null;
      lines.forEach(function(line) {
        var m = line.match(/第[一二三四五六七八九十百\d]+[卷幕部]/);
        if (m) {
          currVol = {index: volumes.length + 1, title: line.trim(), outline: '', chapters: []};
          volumes.push(currVol);
        } else if (currVol && line.trim()) {
          currVol.outline += line.trim() + '\n';
        }
      });
      if (volumes.length === 0) volumes = [{index: 1, title: '第一卷', outline: ol.outline || '', chapters: []}];
      meta.volumes = volumes;
      LocalDB.saveProjectMeta(meta);
      return { ok: true, volumes: volumes };
    }
    if (path === '/api/project/hooks' && method === 'GET') return LocalDB.getProjectHooks();
    if (path === '/api/project/hooks/add' && method === 'POST') return LocalDB.addHook(body);
    if (path === '/api/project/hooks/recover') return LocalDB.recoverHook(body.hook_id || body.id);
    if (path === '/api/project/hooks/abandon') return LocalDB.abandonHook(body.hook_id || body.id);

    // ── 章节 ──
    if (path === '/api/chapter/list') return LocalDB.getChapterList();
    if (path === '/api/chapter/add' && method === 'POST') return LocalDB.addChapter(body.title, body.vol_index);
    if (path === '/api/chapter/delete' && method === 'POST') return LocalDB.deleteChapter(body.index);
    if (path.indexOf('/api/chapter/load') === 0) {
      var idx = new URLSearchParams(path.split('?')[1] || '').get('index');
      return LocalDB.loadChapter(parseInt(idx));
    }
    if (path === '/api/chapter/save' && method === 'POST') return LocalDB.saveChapter(body.index, body.content);
    if (path.indexOf('/api/chapter/') >= 0 && path.indexOf('/blueprint') >= 0 && method === 'POST') {
      var bi = parseInt(path.match(/\d+/)[0]);
      return LocalDB.saveChapterBlueprint(bi, body);
    }
    if (path === '/api/chapter/outline' && method === 'POST') return LocalDB.saveChapterOutline(body.index, body.outline, body.blueprint);
    if (path.indexOf('/api/chapter/snapshots') === 0) {
      var si = new URLSearchParams(path.split('?')[1] || '').get('index');
      return LocalDB.getSnapshots(parseInt(si));
    }
    if (path === '/api/chapter/snapshot/restore' && method === 'POST') return LocalDB.restoreSnapshot(body.index, body.snapshot);
    if (path === '/api/chapter/snapshot/diff' && method === 'POST') return LocalDB.diffSnapshots(body.index, body.snapshot_a, body.snapshot_b);

    // ── AI配置 ──
    if (path === '/api/ai/config') {
      if (method === 'GET') return { ok: true, config: LocalDB.getAIConfig() };
      return LocalDB.saveAIConfig(body);
    }
    if (path.indexOf('/api/ai/test') === 0) {
      try {
        var r = await AIEngine.callAI('你好');
        return { ok: r.ok, message: r.ok ? '连接成功' : (r.error || '连接失败') };
      } catch(e) { return { ok: false, error: e.message }; }
    }

    // ── AI功能 ──
    if (path === '/api/ai/chat' && method === 'POST') return await AIEngine.chat(body.messages, { temperature: body.temperature });
    if (path === '/api/ai/brainstorm' && method === 'POST') return await AIEngine.brainstorm(body.topic, body.context, body.mode, body);
    if (path === '/api/ai/expand-idea' && method === 'POST') return await AIEngine.expandIdea(body.title, body.desc, body.mode, body.context);
    if (path === '/api/ai/sensory' && method === 'POST') return await AIEngine.sensory(body.scene, body.sense_type, body.style);
    if (path === '/api/ai/analyze-content' && method === 'POST') return await AIEngine.chat([{role:'user', content:'分析以下文本的世界观设定：\n' + body.content}]);
    if (path === '/api/ai/extract-settings' && method === 'POST') return await AIEngine.chat([{role:'user', content:'从大纲提取结构化世界观：\n' + body.outline}]);
    if (path === '/api/ai/generate-characters' && method === 'POST') return await AIEngine.generateCharacters(body.novel_outline || '');

    // ── 生成 ──
    if (path === '/api/generate/outline' && method === 'POST') return await AIEngine.generateOutline(body.title, body.genre, body.length);
    if (path === '/api/generate/chapter-outline' && method === 'POST') return await AIEngine.generateChapterOutline(body.title, body.context, body.chapter_index || 0);
    if (path === '/api/generate/chapter' && method === 'POST') return await AIEngine.generateChapter(body.title, body.outline, body.context, body.chapter_index || 0);
    if (path === '/api/generate/gate' && method === 'POST') return await AIEngine.generateChapter(body.title, body.outline, body.context, body.chapter_index || 0);
    if (path === '/api/generate/extract-state' && method === 'POST') return await AIEngine.extractState(body.content, body.chapter_idx);
    if (path === '/api/generate/next-chapter-outline' && method === 'POST') return await AIEngine.generateChapterOutline(body.title, body.context, body.chapter_index || 0);

    // ── 校验 ──
    if (path === '/api/validate/ai-flavor') return AuditJS.detectAiFlavor(body.content);
    if (path === '/api/validate/power-collapse') return AuditJS.detectPowerCollapse(body.content, body.chapter_index || 0, body.characters);
    if (path === '/api/validate/extended-audit') return AuditJS.runExtendedAudit(body.content, body.chapter_index || 0, body.characters, body.overdue_hooks);
    if (path === '/api/validate/all') return await AIEngine.validateAll(body.content, body.index, body.memory, body.context);
    if (path === '/api/validate/batch') return { ok: true, results: {} };
    if (path.indexOf('/api/validate/') === 0) return await AIEngine.validateAll(body.content, body.index, body.memory, body.context);

    // ── Ledger ──
    if (path === '/api/ledger/stats') return LocalDB.getLedgerStats();
    if (path === '/api/ledger/characters') return LocalDB.getCharacters();
    if (path === '/api/ledger/character/update' && method === 'POST') return LocalDB.updateCharacter(body.name, body);
    if (path.indexOf('/api/ledger/timeline') === 0) {
      var tch = new URLSearchParams(path.split('?')[1] || '').get('chapter');
      return LocalDB.getTimeline(tch ? parseInt(tch) : null);
    }
    if (path === '/api/ledger/hooks') return LocalDB.getHooks();
    if (path === '/api/ledger/hook/add' && method === 'POST') return LocalDB.addHook(body);
    if (path === '/api/ledger/hook/recover' && method === 'POST') return LocalDB.recoverHook(body.id || body.hook_id);
    if (path === '/api/ledger/hook/abandon' && method === 'POST') return LocalDB.abandonHook(body.id || body.hook_id);

    // ── 世界观 ──
    if (path === '/api/world/' || path === '/api/world') return LocalDB.getWorldMeta();
    if (path === '/api/world/stats') {
      var w = LocalDB.getWorldMeta();
      return { ok: true, stats: { forces: (w.world.forces||[]).length, locations: (w.world.locations||[]).length, items: (w.world.items||[]).length, constraints: (w.world.hard_constraints||[]).length } };
    }

    // ── 工作流 ──
    if (path === '/api/workflow') {
      if (method === 'GET') return LocalDB.getWorkflow();
      return LocalDB.saveWorkflow(body);
    }

    // ── 记忆 ──
    if (path === '/api/memory/stats') return LocalDB.getMemoryStats();
    if (path === '/api/memory/add' && method === 'POST') return LocalDB.addMemory(body);
    if (path === '/api/memory/search' && method === 'POST') return LocalDB.searchMemory(body.query, body.k);
    if (path === '/api/memory/search-for-generation' && method === 'POST') return LocalDB.searchMemoryForGeneration(body.query, body.chapter, body.k);
    if (path === '/api/memory/import-chapter' && method === 'POST') return LocalDB.importChapterMemory(body.index, body.paragraphs);
    if (path.indexOf('/api/memory/') === 0 && method === 'DELETE') return LocalDB.deleteMemory(path.split('/').pop());

    // ── 知识库 ──
    if (path === '/api/kb/templates') return LocalDB.getKBTemplates();
    if (path === '/api/kb/import-template' && method === 'POST') return LocalDB.importKBTemplate(body.template_id);
    if (path === '/api/kb/list') return LocalDB.listKB();
    if (path.indexOf('/api/kb/search') === 0) return LocalDB.searchKB(new URLSearchParams(path.split('?')[1]||'').get('q')||'');

    // ── 完整性/连贯性检查 ──
    if (path === '/api/check/completeness' && method === 'POST') return await AIEngine.checkCompleteness(body.content, body.title);
    if (path === '/api/check/continuity' && method === 'POST') return await AIEngine.checkContinuity(body.chapter_a, body.chapter_b, body.title_a, body.title_b);

    // ── 统计 ──
    if (path.indexOf('/api/stats/daily') === 0) return LocalDB.getStatsDaily(parseInt(new URLSearchParams(path.split('?')[1]||'').get('range')||30));
    if (path === '/api/stats/weekly') return LocalDB.getStatsWeekly();
    if (path === '/api/stats/monthly') return LocalDB.getStatsMonthly();
    if (path === '/api/stats/summary') return LocalDB.getStatsSummary();

    // ── 模板 ──
    if (path === '/api/templates/list') return LocalDB.getOutlineTemplates();
    if (path === '/api/templates/apply' && method === 'POST') return LocalDB.applyOutlineTemplate(body.template_id);

    // ── 角色对话 ──
    if (path === '/api/chat/characters') return LocalDB.getChatCharacters();
    if (path === '/api/chat/talk' && method === 'POST') return await AIEngine.chatTalk(body.character, body.message, body.history);

    // ── 阅读器 ──
    if (path === '/api/reader/bookshelf') return LocalDB.getBookshelf();
    if (path.indexOf('/api/reader/chapter') === 0) {
      var rp = new URLSearchParams(path.split('?')[1] || '');
      return LocalDB.getReaderChapter(rp.get('project'), parseInt(rp.get('chapter')));
    }
    if (path === '/api/reader/progress' && method === 'POST') return LocalDB.saveReaderProgress(body.project, body.chapter, body.scroll);
    if (path === '/api/reader/progress') return LocalDB.getReaderProgress(new URLSearchParams(path.split('?')[1]||'').get('project'));
    if (path === '/api/reader/bookshelf/toggle') return LocalDB.toggleBookshelf(body.project);

    // ── 同步 ──
    if (path === '/api/sync/config') {
      if (method === 'GET') return LocalDB.getSyncConfig();
      return LocalDB.saveSyncConfig(body);
    }
    if (path.indexOf('/api/sync/') === 0) return { ok: false, error: '单机模式不支持WebDAV同步' };

    // ── 导出 ──
    if (path.indexOf('/api/export/txt') === 0) return LocalDB.exportTXT();
    if (path.indexOf('/api/export/') === 0) return { ok: false, error: '单机模式仅支持TXT导出' };

    // ── 不支持的接口 ──
    if (path === '/api/file/parse') return { ok: false, error: '单机模式不支持文件上传解析' };
    if (path.indexOf('/api/deconstruct/') === 0) return { ok: false, error: '单机模式暂不支持拆书' };
    if (path.indexOf('/api/storyboard/') === 0) return { ok: false, error: '单机模式暂不支持分镜' };
    if (path === '/api/agent/chat' && method === 'POST') {
      var ar = await AIEngine.chat(body.messages || [{role:'user', content: body.message || body.query || ''}]);
      return { ok: true, reply: ar, action: null };
    }

    console.warn('[本地模式] 未匹配路径:', path);
    return { ok: false, error: '未知API: ' + path };
  };

  // 覆盖callAI为本地调用
  window.callAI = async function(messages, opts) {
    opts = opts || {};
    var msgsText = messages.map(function(m) { return m.role + ': ' + m.content; }).join('\n');
    var r = await AIEngine.callAI(msgsText, { temperature: opts.temperature });
    if (r.ok) return { ok: true, content: r.content };
    return r;
  };

  // fetch拦截器：处理index.html/app.js中残留的fetch()调用
  var _origFetch = window.fetch;
  window.fetch = async function(input, init) {
    var url = typeof input === 'string' ? input : (input && input.url ? input.url : '');
    if (url && url.indexOf('/api/') >= 0) {
      var path = url.replace(/^https?:\/\/[^\/]+/, '');
      var idx = path.indexOf('/api/');
      if (idx >= 0) path = path.substring(idx);
      var method = (init && init.method) || 'GET';
      var body = null;
      if (init && init.body) {
        try {
          if (typeof init.body === 'string') body = JSON.parse(init.body);
          else if (init.body instanceof FormData) return new Response(JSON.stringify({ok:false,error:'单机模式不支持文件上传'}), {status:200,headers:{'Content-Type':'application/json'}});
          else body = {};
        } catch(e) { body = {}; }
      }
      try {
        var result = await window.api(path, {method: method, body: body ? JSON.stringify(body) : null});
        return new Response(JSON.stringify(result), {status: 200, headers: {'Content-Type': 'application/json'}});
      } catch(e) {
        return new Response(JSON.stringify({ok:false, error: e.message}), {status: 500, headers: {'Content-Type': 'application/json'}});
      }
    }
    return _origFetch.call(window, input, init);
  };

  // 跳过认证检查
  window._checkAuth = async function() { return true; };

  console.log('[双模式] 本地模式已激活');
} else {
  console.log('[双模式] 检测到电脑端环境，使用后端模式');
}


// ── js/utils/json-parser.js ──
// ═══════════════════════════════════════════
// JSON 解析工具函数
// 从 JSON/Markdown 代码块中提取字段，用于解析章节蓝图、大纲等
// 统一去重：替代 editor.js 中的 extractField / extField 等重复函数
// ═══════════════════════════════════════════
(function(global) {
  'use strict';

  /**
   * 从 JSON 文本中提取指定字段的所有值
   * 匹配 "field": "value" 格式，支持转义字符
   * @param {string} jsonText - JSON 文本（可以是不完整的或被 markdown 包裹的）
   * @param {string} field - 字段名
   * @returns {string[]} 匹配到的字段值数组
   */
  function extractField(jsonText, field) {
    if (!jsonText || !field) return [];
    // 匹配 "field": "value" 或 "field": "value",
    // 支持转义引号和转义换行
    var pattern = '"' + field.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '"\\s*:\\s*"([^"]*(?:\\\\.[^"]*)*)"';
    var matches = [];
    var re = new RegExp(pattern, 'g');
    var m;
    while ((m = re.exec(jsonText)) !== null) {
      // 处理转义字符：\" -> ", \n -> 空格
      var val = m[1].replace(/\\"/g, '"').replace(/\\n/g, ' ');
      matches.push(val);
    }
    return matches;
  }

  /**
   * 判断文本是否为 JSON 格式（可能被 markdown 代码块包裹）
   * @param {string} text
   * @returns {boolean}
   */
  function isJsonFormat(text) {
    if (!text) return false;
    var trimmed = text.trim();
    return trimmed.startsWith('```json') || trimmed.startsWith('{');
  }

  /**
   * 从 JSON 文本中提取章节大纲文本行
   * 提取 scene, atmosphere, trigger, event, conflict, twist, new_state, next_hook 等字段
   * 并格式化为章节大纲列表
   * @param {string} jsonText - JSON 格式的大纲文本
   * @returns {Array<{text: string, current: boolean, source: string}>} 大纲项数组
   */
  function extractOutlineFromJSON(jsonText) {
    if (!jsonText) return [];

    var textLines = [];
    var scenes = extractField(jsonText, 'scene');
    var atmospheres = extractField(jsonText, 'atmosphere');
    var triggers = extractField(jsonText, 'trigger');
    var events = extractField(jsonText, 'event');
    var conflicts = extractField(jsonText, 'conflict');
    var twists = extractField(jsonText, 'twist');
    var newStates = extractField(jsonText, 'new_state');
    var nextHooks = extractField(jsonText, 'next_hook');

    if (scenes.length > 0) textLines.push('【起】' + scenes[0]);
    if (atmospheres.length > 0) textLines.push('氛围：' + atmospheres[0]);
    if (triggers.length > 0) textLines.push('触发：' + triggers[0]);
    events.forEach(function(ev, i) {
      if (ev) textLines.push('【承' + (i+1) + '】' + ev);
    });
    if (conflicts.length > 0) textLines.push('【转】' + conflicts[0]);
    if (twists.length > 0) textLines.push('转折：' + twists[0]);
    if (newStates.length > 0) textLines.push('【合】' + newStates[0]);
    if (nextHooks.length > 0) textLines.push('钩子：' + nextHooks[0]);

    if (textLines.length > 0) {
      return textLines.map(function(l, i) {
        return { text: l.trim(), current: i === 0, source: 'parsed' };
      });
    }

    // 正则也提取不到，按行分割但过滤JSON语法行
    var rawLines = jsonText.split('\n').filter(function(l) {
      var t = l.trim();
      return t && !t.startsWith('"') && !t.startsWith('{') && !t.startsWith('}') &&
             !t.startsWith('[') && !t.startsWith(']') && !t.startsWith('```');
    });
    return rawLines.map(function(l, i) {
      return { text: l.trim(), current: i === 0, source: 'saved' };
    });
  }

  /**
   * 从 JSON 文本中解析结构化蓝图（blueprint）
   * 提取 intro, development, climax, ending 四个部分
   * @param {string} jsonText - JSON 格式的大纲/蓝图文本
   * @returns {Object|null} 蓝图对象，格式：
   *   {
   *     intro: { scene, trigger },
   *     development: [ { scene, event, characters: [] } ],
   *     climax: { conflict, twist },
   *     ending: { new_state, next_hook }
   *   }
   *   提取不到有效字段时返回 null
   */
  function parseBlueprintFromJSON(jsonText) {
    if (!jsonText) return null;

    var bpScenes = extractField(jsonText, 'scene');
    var bpEvents = extractField(jsonText, 'event');
    var bpChars = extractField(jsonText, 'characters');
    var bpConflicts = extractField(jsonText, 'conflict');
    var bpTwists = extractField(jsonText, 'twist');
    var bpTriggers = extractField(jsonText, 'trigger');
    var bpNewStates = extractField(jsonText, 'new_state');
    var bpNextHooks = extractField(jsonText, 'next_hook');

    // 至少要有一些有效字段才认为是蓝图
    if (bpScenes.length === 0 && bpEvents.length === 0 && bpChars.length === 0 &&
        bpConflicts.length === 0 && bpTwists.length === 0) {
      return null;
    }

    var devArr = [];
    var maxLen = Math.max(bpScenes.length, bpEvents.length, bpChars.length);
    for (var di = 0; di < maxLen; di++) {
      devArr.push({
        scene: bpScenes[di] || '',
        event: bpEvents[di] || '',
        characters: bpChars[di] ? [bpChars[di]] : []
      });
    }

    return {
      intro: {
        scene: bpScenes[0] || '',
        trigger: bpTriggers[0] || ''
      },
      development: devArr,
      climax: {
        conflict: bpConflicts[0] || '',
        twist: bpTwists[0] || ''
      },
      ending: {
        new_state: bpNewStates[0] || '',
        next_hook: bpNextHooks[0] || ''
      }
    };
  }

  // 暴露到全局
  global.JsonParser = {
    extractField: extractField,
    isJsonFormat: isJsonFormat,
    extractOutlineFromJSON: extractOutlineFromJSON,
    parseBlueprintFromJSON: parseBlueprintFromJSON
  };

  console.log('[JsonParser] loaded');

})(window);


// ── js/utils/virtual-list.js ──
/**
 * VirtualList — 虚拟滚动基类
 * 用于章节列表、大纲列表、时间线导航等大列表场景
 * 只渲染可视区域的 DOM 元素，大幅减少节点数量
 *
 * 使用方式:
 *   var vl = new VirtualList(containerEl, {
 *     itemHeight: 36,          // 每项固定高度(px)
 *     items: chapterData,       // 数据数组
 *     renderFn: function(item, index) {
 *       return '<div class="chapter-item">' + item.title + '</div>';
 *     },
 *     onSelect: function(item, index) { ... }
 *   });
 */

var VirtualList = (function() {

  function VirtualList(container, opts) {
    this.container = container;
    this.itemHeight = opts.itemHeight || 36;
    this.items = opts.items || [];
    this.renderFn = opts.renderFn || function(item, idx) { return '<div>' + (item.title || item) + '</div>'; };
    this.onSelect = opts.onSelect || null;
    this.selectedIdx = opts.selectedIdx || -1;
    this.bufferSize = opts.bufferSize || 5;  // 额外渲染的缓冲项数
    this.className = opts.className || '';

    // 创建内部结构
    this._setupDOM();
    this._bindEvents();
    this.render();
  }

  VirtualList.prototype._setupDOM = function() {
    // 容器需要 overflow-y: auto
    this.container.style.overflowY = 'auto';
    this.container.style.position = 'relative';

    // 总高度占位元素（撑开滚动区域）
    this.spacer = document.createElement('div');
    this.spacer.style.cssText = 'position:absolute;top:0;left:0;right:0;height:' +
      (this.items.length * this.itemHeight) + 'px;pointer-events:none';
    this.container.appendChild(this.spacer);

    // 可视区域渲染容器
    this.viewport = document.createElement('div');
    this.viewport.style.cssText = 'position:relative;z-index:1';
    this.container.appendChild(this.viewport);
  };

  VirtualList.prototype._bindEvents = function() {
    var self = this;
    this.container.addEventListener('scroll', function() {
      self.render();
    });
  };

  VirtualList.prototype.render = function() {
    var scrollTop = this.container.scrollTop;
    var containerHeight = this.container.clientHeight;
    var totalItems = this.items.length;

    // 计算可视范围
    var startIdx = Math.floor(scrollTop / this.itemHeight) - this.bufferSize;
    startIdx = Math.max(0, startIdx);

    var endIdx = Math.ceil((scrollTop + containerHeight) / this.itemHeight) + this.bufferSize;
    endIdx = Math.min(totalItems, endIdx);

    // 更新 spacer 高度
    this.spacer.style.height = (totalItems * this.itemHeight) + 'px';

    // 渲染可视项
    var html = '';
    for (var i = startIdx; i < endIdx; i++) {
      var item = this.items[i];
      var isSelected = (i === this.selectedIdx);
      var itemHtml = this.renderFn(item, i, isSelected);
      html += itemHtml;
    }

    // 设置偏移量
    this.viewport.style.transform = 'translateY(' + (startIdx * this.itemHeight) + 'px)';
    this.viewport.innerHTML = html;

    // 绑定选择事件
    if (this.onSelect) {
      var items = this.viewport.children;
      for (var j = 0; j < items.length; j++) {
        var idx = startIdx + j;
        (function(el, itemIdx) {
          el.addEventListener('click', function(e) {
            self.select(itemIdx, e);
          });
        })(items[j], idx);
      }
    }
  };

  VirtualList.prototype.select = function(idx, e) {
    this.selectedIdx = idx;
    if (this.onSelect) {
      this.onSelect(this.items[idx], idx, e);
    }
    this.render();  // 重新渲染以更新选中状态
  };

  VirtualList.prototype.setItems = function(newItems) {
    this.items = newItems;
    this.spacer.style.height = (newItems.length * this.itemHeight) + 'px';
    this.render();
  };

  VirtualList.prototype.scrollToIndex = function(idx) {
    var targetTop = idx * this.itemHeight;
    this.container.scrollTop = targetTop;
  };

  VirtualList.prototype.destroy = function() {
    this.container.innerHTML = '';
    this.container.style.overflowY = '';
    this.container.style.position = '';
  };

  return VirtualList;
})();

window.VirtualList = VirtualList;


// ── js/modules/init.js ──
// Extracted from app.js - 初始化逻辑 (extractOutlineFromNovelActs, handleProjectClick, reloadAllProjectData, injectFieldToolbar, renderValResult, AI修复)

// 安全HTML转义函数（避免依赖memory-panel.js加载顺序）
function esc(str) {
  if (str == null) return '';
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

// ── 全局章节列表渲染函数 ──
// 渲染所有4个卷导航容器（供 state.js Proxy 和各模块调用）
function renderChapterList() {
  var containers = ['vol-nav-writing', 'vol-nav-outline', 'vol-nav-timeline', 'vol-nav-content'];
  containers.forEach(function(cid) {
    if (typeof renderVolumeNav === 'function') {
      renderVolumeNav(cid, function(idx) {
        if (typeof syncChapterAcrossPanels === 'function') {
          syncChapterAcrossPanels(idx);
        } else if (typeof loadChapterContentAPI === 'function') {
          loadChapterContentAPI(idx);
        }
      });
    }
  });
}

// 全局迷你章节列表渲染函数（简化版，只渲染写作容器）
function renderChapterMiniList() {
  if (typeof renderVolumeNav === 'function') {
    renderVolumeNav('vol-nav-writing', function(idx) {
      if (typeof loadChapterContentAPI === 'function') loadChapterContentAPI(idx);
    });
  }
}

// ── 加载工作流状态 ──
// 从 localStorage 恢复工作流步骤和步骤状态
function loadWorkflowState() {
  try {
    var saved = localStorage.getItem('shuzhai_workflow_state');
    if (saved) {
      var data = JSON.parse(saved);
      if (data && data.currentStep) {
        workflowState.currentStep = data.currentStep;
        if (data.stepStatus) {
          Object.keys(data.stepStatus).forEach(function(key) {
            workflowState.stepStatus[key] = data.stepStatus[key];
          });
        }
      }
    }
  } catch( e) {
    console.warn('loadWorkflowState failed:', e);
  }
}

// ── 保存工作流状态 ──
function saveWorkflowState() {
  try {
    localStorage.setItem('shuzhai_workflow_state', JSON.stringify(workflowState));
  } catch( e) {
    console.warn('saveWorkflowState failed:', e);
  }
}

function extractOutlineFromNovelActs(chIndex) {
  var items = [];
  if (typeof novelActs !== 'undefined' && novelActs.length) {
    novelActs.forEach(function(act) {
      if (act.events) {
        act.events.forEach(function(ev) {
          // 匹配章节号，如 "Ch.1" 或 "第1章"
          var chMatch = (ev.ch || '').match(/(\d+)/);
          var evCh = chMatch ? parseInt(chMatch[1]) : -1;
          if (evCh === chIndex + 1) {
            items.push({text: ev.text, current: items.length === 0, source: 'novel-act'});
          }
        });
      }
    });
  }
  if (items.length === 0) {
    items.push({text: '【第' + (chIndex + 1) + '章大纲要点】', current: true, source: 'human'});
  }
  return items;
}

  // 全局项目点击处理函数（用于内联 onclick）
  window.handleProjectClick = async function(path) {
    const projectDropdown = document.getElementById('project-dropdown');
    projectDropdown.style.display = 'none';
    showToast('正在打开项目...');

    const r = await api('/api/project/open', {
      method: 'POST',
      body: JSON.stringify({path})
    });
    if (r.ok) {
      // 重新加载所有项目数据（不刷新页面）
      await reloadAllProjectData();
      showToast('项目已切换: ' + (r.title || ''));
    } else {
      showToast('打开失败: ' + (r.error || '未知错误'));
    }
  }

  // 重新加载所有项目数据（切换项目后调用）
  // isNewProject: 如果是新建项目，使用空数据而非默认值
  async function reloadAllProjectData(isNewProject) {
    try {
      // 0. 清空旧数据 —— 必须清空所有全局变量，否则旧项目内存数据会覆盖新项目
      worldSettings = [];
      novelActs = [];
      chOutline = [];
      chapters = [];
      currentChapterIndex = 0;
      // ★ 修步骤乱打勾：清空上一个项目残留的工作流步骤状态缓存（否则UI步骤圈会显示旧项目的✓）
      window._workflowStepCache = null;
      // 重置当前步骤，避免新项目时还停留在旧项目的步骤6/7/8
      currentWorkflowStep = 1;
      // 清空结构化设定面板和角色面板的内存残留（防止新项目显示旧项目数据）
      if (typeof worldMeta !== 'undefined') {
        worldMeta = { narrative_style: {}, era: {}, world_rules: [] };
        // ★ 必须同步清空UI输入框，否则旧DOM值会被saveWorldMeta写入新项目DB
        if (typeof renderWorldMeta === 'function') renderWorldMeta();
      }
      // 清除待执行的saveWorldMeta debounce定时器（防止旧项目保存请求覆盖新项目）
      if (typeof _debounceSaveTimer !== 'undefined' && _debounceSaveTimer) {
        clearTimeout(_debounceSaveTimer);
        _debounceSaveTimer = null;
      }
      if (typeof characters !== 'undefined') {
        characters = [];
      }
      
      // 1. 加载项目信息
      var info = await loadProjectInfo();
      if (info.ok) {
        var elP = document.getElementById('project-name');
        var elC = document.getElementById('current-chapter-label');
        if (elP) elP.textContent = info.title || '';
        if (elC) elC.textContent = info.genre || '';
      }
      // 2. 加载设定和大纲（从后端或默认值）
      if (isNewProject) {
        // 新项目：保持空数据，让用户自己填写
        worldSettings = [];
        novelActs = [];
        chOutline = [];
      } else {
        // 切换已有项目：从后端加载，无数据时使用默认值
        await loadProjectSettings();
        await loadProjectOutline();
      }
      // 3. 加载章节列表
      await loadChaptersFromAPI();
      // 4. 重新渲染所有UI
      if (typeof renderSettingsEditor === 'function') renderSettingsEditor();
      if (typeof renderNovelOutlineEditor === 'function') renderNovelOutlineEditor();
      if (typeof renderChapterList === 'function') renderChapterList();
      if (typeof renderChapterMiniList === 'function') renderChapterMiniList();
      if (chapters && chapters.length > 0) {
        await loadChapterContentAPI(0);
      }
      // 5. 刷新上下文面板
      loadContextPanel();
      // 6. 如果当前在步骤3，刷新章节大纲编辑器
      if (currentWorkflowStep === STEPS.章节大纲 && typeof renderChapterOutlineEditor === 'function') {
        renderChapterOutlineEditor();
      }
    } catch(e) { console.error('reloadAllProjectData error:', e); }
  }


  

  /* ---- REAL-TIME WORD COUNT ---- */
  function initEditorWordCount() {
    var editorContent = document.getElementById('editor-content');
    if (!editorContent) { setTimeout(initEditorWordCount, 200); return; }

    function updateWordCount(){
      var text=(editorContent.textContent||'').trim();
      var count=text?text.replace(/\s+/g,'').length:0;
      var wcEl = document.getElementById('word-count');
      if (wcEl) wcEl.textContent=count.toLocaleString('zh-CN');
      var currentCh=document.querySelector('.chapter-item.active');
      if(currentCh){var ch=currentCh.dataset.ch;chapters[ch].words=count;}
      if(typeof updateWritingToolbar==='function') updateWritingToolbar();
    }
    editorContent.addEventListener('input',updateWordCount);
    updateWordCount();
  }
  initEditorWordCount();

  function setFontScale(v){
    v=parseFloat(v);
    var app=document.getElementById('app')||document.body;
    app.style.transform='scale('+v+')';
    app.style.transformOrigin='top left';
    app.style.width=(100/v)+'%';
    app.style.height=(100/v)+'%';
    var fsVal = document.getElementById('fs-val');
    var fsSlider = document.getElementById('fs-slider');
    if (fsVal) fsVal.textContent=Math.round(v*100)+'%';
    if (fsSlider) fsSlider.value=v;
    localStorage.setItem('v24-font-scale',v);
  }
  function changeFontScale(delta){
    var fsSlider = document.getElementById('fs-slider');
    if (!fsSlider) return;
    var s=parseFloat(fsSlider.value);
    s=Math.max(0.8,Math.min(1.5,s+delta));
    setFontScale(s);
  }
  // restore saved font scale
  (function(){var saved=localStorage.getItem('v24-font-scale');if(saved){setTimeout(function(){setFontScale(parseFloat(saved));},100);}})();

  console.log('书斋 已就绪');

  // ── 项目切换按钮事件绑定 ──
  var btnOpen = document.getElementById('btn-open-project');
  if (btnOpen && typeof toggleProjectPicker === 'function') {
    btnOpen.addEventListener('click', toggleProjectPicker);
  }
  var btnNew = document.getElementById('btn-new-project');
  if (btnNew) {
    btnNew.addEventListener('click', function() {
      document.getElementById('new-project-overlay').classList.add('active');
      document.getElementById('new-project-title').value = '';
      document.getElementById('new-project-title').focus();
    });
  }

  // ── 新建项目对话框按钮 ──
  function closeNewProjectOverlay() {
    document.getElementById('new-project-overlay').classList.remove('active');
  }
  var btnClose = document.getElementById('new-project-close');
  if (btnClose) btnClose.addEventListener('click', closeNewProjectOverlay);
  var btnCancel = document.getElementById('new-project-cancel');
  if (btnCancel) btnCancel.addEventListener('click', closeNewProjectOverlay);
  var btnCreate = document.getElementById('new-project-create');
  if (btnCreate) {
    btnCreate.addEventListener('click', async function() {
      var title = document.getElementById('new-project-title').value.trim();
      if (!title) { document.getElementById('new-project-title').focus(); return; }
      var genre = document.getElementById('new-project-genre').value;
      var lenSel = document.getElementById('new-project-length').value;
      var length = lenSel === 'custom' ? parseInt(document.getElementById('new-project-custom-input').value) || 10 : parseInt(lenSel);
      btnCreate.disabled = true;
      btnCreate.textContent = '创建中...';
      try {
        var r = await newProject(title, genre, length);
        if (r && r.ok) {
          closeNewProjectOverlay();
          await reloadAllProjectData(true);
          if (typeof loadProjectList === 'function') loadProjectList();
          if (typeof showToast === 'function') showToast('项目已创建: ' + title);
        } else {
          if (typeof showToast === 'function') showToast('创建失败: ' + (r && r.error || '未知错误'));
        }
      } catch(e) {
        if (typeof showToast === 'function') showToast('创建出错: ' + e.message);
      }
      btnCreate.disabled = false;
      btnCreate.textContent = '创建';
    });
  }

// ── Model Popover toggle ──
function toggleModelPopover(e) {
  if (e) e.stopPropagation();
  const pop = document.getElementById('model-popover');
  pop.classList.toggle('visible');
  if (pop.classList.contains('visible') && typeof loadAIUsage === 'function') {
    loadAIUsage(false);
  }
}
async function loadProjectList() {
  try {
    var r = await api('/api/project/list');
    var inner = document.getElementById('project-list-inner');
    var projects = (r && r.data) || (r && r.items) || r || [];
    if (!Array.isArray(projects)) projects = [];
    // 持久化项目列表（书架首页/空库向导判断用）
    try { localStorage.setItem('shuzhai_project_list', JSON.stringify(projects)); } catch(_eS) {}
    if (!inner) return projects;
    inner.textContent = '';
    if (projects.length === 0) {
      inner.innerHTML = '<div style="color:#888;text-align:center;padding:12px">暂无项目</div>';
      return projects;
    }
    var currentDir = (typeof currentProjectDir !== 'undefined') ? currentProjectDir : '';
    projects.forEach(function(p) {
      var dir = p.project_dir || p.dir || '';
      var title = p.title || p.name || dir.split(/[/\\]/).pop();
      var isActive = dir === currentDir;
      var div = document.createElement('div');
      div.className = 'proj-item' + (isActive ? ' active' : '');
      div.style.cssText = 'padding:8px 12px;cursor:pointer;border-radius:6px;margin:4px 0;display:flex;justify-content:space-between;align-items:center;color:#222;' + (isActive ? 'background:var(--accent,#4a9eff);color:#fff;' : 'background:#f0f0f0;');
      var delBtn = '<button class="proj-del-btn" title="删除项目" style="background:none;border:none;cursor:pointer;font-size:14px;color:#999;padding:2px 6px;border-radius:4px;" >🗑</button>';
      div.innerHTML = '<span class="flex-1">' + esc(title) + '</span><span style="font-size:11px;opacity:0.7;margin-right:6px">' + esc(p.genre || '') + ' ' + (p.chapter_count || '') + '章</span>' + (isActive ? '' : delBtn);
      div.onclick = function(e) {
        if (e.target.classList.contains('proj-del-btn') || e.target.closest('.proj-del-btn')) return;
        if (!isActive && typeof switchProject === 'function') switchProject(dir);
      };
      // 删除按钮事件
      var delBtnEl = div.querySelector('.proj-del-btn');
      if (delBtnEl) {
        delBtnEl.addEventListener('click', function(e) {
          e.stopPropagation();
          if (confirm('确定删除项目「' + title + '」？\n此操作不可恢复！')) {
            api('/api/project/delete', {
              method: 'POST',
              headers: {'Content-Type':'application/json'},
              body: JSON.stringify({project_dir: dir})
            }).then(function(r) {
              if (r && r.ok) {
                showToast('已删除: ' + title, 'success', 2000);
                if (typeof loadProjectList === 'function') loadProjectList();
              } else {
                showToast('删除失败: ' + (r && r.error || '未知错误'), 'error', 3000);
              }
            }).catch(function(e) {
              showToast('删除失败: ' + e.message, 'error', 3000);
            });
          }
        });
      }
      inner.appendChild(div);
    });
    return projects;
  } catch(e) {
    console.warn('loadProjectList failed:', e);
    return [];
  }
}

async function switchProject(projectDir) {
  try {
    var r = await api('/api/project/open', {
      method: 'POST',
      body: JSON.stringify({path: projectDir})
    });
    if (r && r.ok) {
      showToast('已切换到: ' + (r.title || projectDir), 'success', 2000);
      // 重新加载页面以加载新项目数据
      setTimeout(function() { location.reload(); }, 500);
    } else {
      showToast('切换失败: ' + (r && r.error || '未知错误'), 'error', 3000);
    }
  } catch(e) {
    console.error('switchProject failed:', e);
    showToast('切换项目失败: ' + e.message, 'error', 3000);
  }
}

function toggleProjectPicker(e) {
  if (e) e.stopPropagation();
  const pop = document.getElementById('project-picker');
  pop.classList.toggle('visible');
  if (pop.classList.contains('visible') && typeof loadProjectList === 'function') loadProjectList();
}

// ── Load context panel ──
function loadContextPanel() {
  try {
    var charsEl = document.getElementById('context-chars');
    var sceneEl = document.getElementById('context-scene');
    var adviceEl = document.getElementById('context-advice');
    
    // 获取当前章节的blueprint（结构化蓝图）
    var bp = window._currentBlueprint || (chapters && chapters[currentChapterIndex] && chapters[currentChapterIndex].blueprint) || null;
    
    // 获取当前章节正文
    var editorEl = document.getElementById('editor-content');
    var chapterText = editorEl ? (editorEl.innerText || '') : '';
    
    // 收集所有角色名（从worldSettings）
    var allChars = [];
    if (typeof worldSettings !== 'undefined' && worldSettings.length) {
      worldSettings.forEach(function(s) {
        if (s.group === '角色' || s.group === '角色设定' || (s.key && (s.key.includes('男主') || s.key.includes('女主') || s.key.includes('反派') || s.key.includes('配角')))) {
          // 提取角色名（去掉描述部分）
          var name = s.key.split(/[：:（(]/)[0].replace(/男主|女主|反派|配角/g, '').trim();
          if (name) allChars.push({name: name, key: s.key, val: s.val || ''});
        }
      });
    }
    
    // ===== 本章角色：从正文中扫描出场角色 =====
    var charDetails = [];
    if (bp && bp.development) {
      // blueprint有角色信息时优先使用
      var charSet = {};
      bp.development.forEach(function(dev) {
        if (dev.characters && Array.isArray(dev.characters)) {
          dev.characters.forEach(function(c) {
            if (c && !charSet[c]) { charSet[c] = true; charDetails.push(c); }
          });
        }
      });
    }
    // blueprint没有角色信息时，从正文扫描
    if (charDetails.length === 0 && chapterText.length > 50) {
      allChars.forEach(function(ch) {
        // 在正文中查找角色名
        if (chapterText.indexOf(ch.name) >= 0) {
          var desc = ch.val ? ch.val.substring(0, 40) : '';
          charDetails.push(ch.name + (desc ? '：' + desc + '...' : ''));
        }
      });
    }
    // 如果正文也没匹配到，回退到全局角色列表（最多5个）
    if (charDetails.length === 0) {
      allChars.slice(0, 5).forEach(function(ch) {
        charDetails.push(ch.key + '：' + (ch.val ? ch.val.substring(0, 30) : '') + '...');
      });
    }
    
    if (charsEl) {
      charsEl.innerHTML = charDetails.length ? '<ul style="margin:0;padding-left:16px;font-size:12px">' + charDetails.map(function(c) { return '<li>' + c + '</li>'; }).join('') + '</ul>' : '<p class="text-md text-muted">暂无角色数据</p>';
    }
    
    // ===== 本章场景：从blueprint或正文提取 =====
    if (sceneEl) {
      var sceneParts = [];
      if (bp) {
        if (bp.intro && bp.intro.scene) {
          sceneParts.push('【开场】' + bp.intro.scene);
          if (bp.intro.atmosphere) sceneParts.push('氛围：' + bp.intro.atmosphere);
        }
        if (bp.development) {
          bp.development.forEach(function(dev, i) {
            if (dev.scene || dev.location) {
              sceneParts.push('【场景' + (i+1) + '】' + (dev.location || '') + (dev.scene ? ' - ' + dev.scene : ''));
            }
          });
        }
        if (bp.climax && bp.climax.conflict) {
          sceneParts.push('【高潮】' + bp.climax.conflict);
        }
      }
      // 回退：从章节大纲提取场景信息
      if (sceneParts.length === 0 && chOutline && chOutline.length > 0) {
        chOutline.forEach(function(item, i) {
          if (item.text) sceneParts.push('• ' + item.text.substring(0, 60));
        });
      }
      // 再回退：显示全局世界观
      if (sceneParts.length === 0 && typeof worldSettings !== 'undefined' && worldSettings.length) {
        var scene = worldSettings.find(function(s) { return s.key === '世界观'; });
        if (scene) sceneParts.push(scene.val);
      }
      sceneEl.innerHTML = sceneParts.length ? sceneParts.join('<br>') : '<span class="text-muted">暂无场景数据</span>';
    }
    
    // ===== 写作建议：从blueprint或章节大纲提取 =====
    if (adviceEl) {
      var adviceItems = [];
      if (bp) {
        if (bp.intro && bp.intro.trigger) adviceItems.push('触发事件：' + bp.intro.trigger);
        if (bp.development) {
          bp.development.forEach(function(dev) {
            if (dev.event) adviceItems.push(dev.event);
            if (dev.choice) adviceItems.push('选择：' + dev.choice);
          });
        }
        if (bp.climax) {
          if (bp.climax.conflict) adviceItems.push('核心冲突：' + bp.climax.conflict);
          if (bp.climax.twist) adviceItems.push('转折：' + bp.climax.twist);
        }
        if (bp.ending) {
          if (bp.ending.new_state) adviceItems.push('新状态：' + bp.ending.new_state);
          if (bp.ending.next_hook) adviceItems.push('下章钩子：' + bp.ending.next_hook);
        }
      }
      // 回退1：从章节大纲提取
      if (adviceItems.length === 0 && chOutline && chOutline.length > 0) {
        chOutline.forEach(function(item) {
          if (item.text) adviceItems.push(item.text);
        });
      }
      // 回退2：从全书大纲匹配当前章节
      if (adviceItems.length === 0 && typeof novelActs !== 'undefined' && novelActs.length > 0 && typeof chapters !== 'undefined' && chapters.length > 0) {
        var chIdx = currentChapterIndex || 0;
        var chTitle = chapters[chIdx] ? chapters[chIdx].title : '';
        var chNum = (chTitle.match(/(\d+)/) || [])[1];
        if (chNum) {
          novelActs.forEach(function(act) {
            if (act.range && act.range.indexOf(chNum) >= 0) {
              act.events.forEach(function(ev) { adviceItems.push(ev.text); });
            }
          });
        }
        // 如果没匹配到，取所有幕的事件作为参考（最多5个）
        if (adviceItems.length === 0) {
          novelActs.forEach(function(act) {
            act.events.forEach(function(ev) { adviceItems.push(ev.text); });
          });
        }
      }
      if (adviceItems.length > 0) {
        adviceEl.innerHTML = '<ul style="margin:0;padding-left:16px;font-size:12px">' + adviceItems.slice(0, 6).map(function(a) { return '<li>' + a + '</li>'; }).join('') + '</ul>';
      } else {
        adviceEl.innerHTML = '<p class="text-md text-muted">完成设定和大纲后，此处将显示本章写作建议</p>';
      }
    }
  } catch(e) { console.error('loadContext error:', e); }
}

// ── js/modules/wizard.js ──
// Extracted from app.js - 首次启动向导 + initApp
// ═══════════════════════════════════════════
// 首次启动向导
// ═══════════════════════════════════════════

async function checkFirstLaunch() {
  try {
    var r = await api('/api/ai/config');
    if (r.ok && r.config) {
      var cfg = r.config;
      var prov = cfg.provider || 'deepseek';
      // 检查当前 provider 或任意 provider 是否已配置密钥
      var hasKey = (cfg[prov] && (cfg[prov].has_key || cfg[prov].api_key)) || cfg.api_key || cfg.deepseek_api_key || (prov === 'ollama' && cfg.ollama_host);
      if (!hasKey) {
        // 再检查其他 provider 是否有密钥
        var provs = ['deepseek', 'openai', 'doubao', 'kimi', 'ollama'];
        for (var i = 0; i < provs.length && !hasKey; i++) {
          var p = provs[i];
          if (cfg[p] && (cfg[p].has_key || cfg[p].api_key)) hasKey = true;
          if (p === 'ollama' && cfg[p] && cfg[p].base_url) hasKey = true;
        }
      }
      // 已有项目也不显示向导
      if (!hasKey) {
        try {
          var projList = JSON.parse(localStorage.getItem('shuzhai_project_list') || '[]');
          if (projList.length > 0) hasKey = true;
        } catch(e) {}
      }
      if (!hasKey) {
        // AI未配置，显示向导
        var wizard = document.getElementById('wizard-overlay');
        if (wizard) { wizard.classList.remove('hidden'); wizard.style.display = 'flex'; }
      }
    }
  } catch(e) { console.error('checkFirstLaunch error:', e); }
}

function skipWizard() {
  var wizard = document.getElementById('wizard-overlay');
  if (wizard) { wizard.style.display = 'none'; wizard.classList.add('hidden'); }
}

async function completeWizard() {
  var wizard = document.getElementById('wizard-overlay');
  var selectedAI = document.querySelector('input[name="wizard-ai"]:checked');
  var provider = selectedAI ? selectedAI.value : 'deepseek';
  
  if (provider === 'deepseek') {
    var apiKey = document.getElementById('wizard-api-key');
    if (apiKey && apiKey.value.trim()) {
      await api('/api/ai/config', { method: 'POST', body: JSON.stringify({
        provider: 'deepseek',
        api_key: apiKey.value.trim(),
        endpoint: 'https://api.deepseek.com',
        model: 'deepseek-v4-flash'
      }) });
      showToast('✅ DeepSeek配置已保存');
    } else {
      showToast('⚠️ 请填写API密钥');
      return;
    }
  } else if (provider === 'ollama') {
    await api('/api/ai/config', { method: 'POST', body: JSON.stringify({
      provider: 'ollama',
      ollama_host: 'http://localhost:11434',
      ollama_model: 'qwen2.5:14b'
    }) });
    showToast('✅ Ollama配置已保存');
  } else if (provider === 'openai') {
    await api('/api/ai/config', { method: 'POST', body: JSON.stringify({
      provider: 'openai'
    }) });
    showToast('✅ OpenAI配置已保存，请在设置中填写密钥');
  }
  
  if (wizard) { wizard.style.display = 'none'; wizard.classList.add('hidden'); }
  if (typeof loadModelConfig === 'function') loadModelConfig();
  // 启动创作向导
  setTimeout(function() { startCreativeWizard(); }, 800);
}

function switchModelProvider(provider) {
  document.querySelectorAll('.mp-tab').forEach(function(t) { t.classList.remove('active'); });
  var tab = document.querySelector('[data-provider="' + provider + '"]');
  if (tab) tab.classList.add('active');
  var dp = document.getElementById('mp-deepseek-panel');
  var op = document.getElementById('mp-ollama-panel');
  var oap = document.getElementById('mp-openai-panel');
  if (dp) dp.style.display = provider === 'deepseek' ? 'block' : 'none';
  if (op) op.style.display = provider === 'ollama' ? 'block' : 'none';
  if (oap) oap.style.display = provider === 'openai' ? 'block' : 'none';
  if (typeof saveModelConfig === 'function') saveModelConfig();
}

