// 向导状态
window._wizardState = null; // {stage, genre, world_text, protagonist_info, char_text, oneliner, outline_text}

function startCreativeWizard(force) {
  // 非强制模式：已有项目则跳过
  if (!force) {
    try {
      var projList = JSON.parse(localStorage.getItem('shuzhai_project_list') || '[]');
      if (projList.length > 0) return;
    } catch(e) {}
  }
  
  window._wizardState = { stage: 'ask_genre', genre: '', world_text: '', protagonist_info: '', char_text: '', oneliner: '', outline_text: '', volumes_text: '', chapter_outline_text: '', append_stage: null, append_volume_index: null };
  
  // 打开 AI 助手面板
  var panel = document.getElementById('ai-assistant-panel');
  var fab = document.getElementById('ai-assistant-fab');
  if (panel && panel.style.display === 'none') {
    panel.style.display = 'flex';
    if (fab) fab.style.display = 'none';
  }
  
  // 注入向导欢迎消息
  var msgDiv = document.getElementById('assistant-messages');
  if (!msgDiv) return;
  msgDiv.innerHTML = '';
  
  var welcomeDiv = document.createElement('div');
  welcomeDiv.style.cssText = 'align-self:flex-start;max-width:90%;padding:10px 14px;background:var(--surface);border:1px solid var(--border-soft);border-radius:12px 12px 12px 4px;font-size:13px;line-height:1.6;word-break:break-word;color:var(--ink);white-space:pre-wrap';
  welcomeDiv.textContent = '🎉 欢迎使用书斋！我是你的创作向导，帮你一步步搭建小说的世界观、人物和大纲。\n\n首先：你想写什么题材？';
  msgDiv.appendChild(welcomeDiv);
  
  // 题材快捷按钮
  var btnDiv = document.createElement('div');
  btnDiv.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;margin:4px 0;padding:0 14px;align-self:flex-start;max-width:90%';
  btnDiv.id = 'wizard-genre-btns';
  var genres = ['仙侠', '都市', '玄幻', '科幻', '历史', '悬疑', '言情', '军事', '游戏', '末世', '重生', '穿越', '武侠', '灵异', '同人', '轻小说', '古言', '职场', '电竞', '无限流', '系统流', '快穿', '甜宠', '星际'];
  genres.forEach(function(g) {
    var b = document.createElement('button');
    b.textContent = g;
    b.style.cssText = 'padding:4px 12px;background:var(--bg);border:1px solid var(--border);border-radius:14px;font-size:12px;cursor:pointer;color:var(--ink)';
    b.onmouseover = function() { b.style.background = 'var(--accent)'; b.style.color = '#fff'; b.style.borderColor = 'var(--accent)'; };
    b.onmouseout = function() { b.style.background = 'var(--bg)'; b.style.color = 'var(--ink)'; b.style.borderColor = 'var(--border)'; };
    b.onclick = function() {
      document.getElementById('assistant-input').value = g;
      sendAssistantMessage();
    };
    btnDiv.appendChild(b);
  });
  msgDiv.appendChild(btnDiv);
  msgDiv.scrollTop = msgDiv.scrollHeight;
  
  setTimeout(function() {
    var input = document.getElementById('assistant-input');
    if (input) input.placeholder = '点击上面题材按钮，或直接输入...';
  }, 300);
}

function _clearWizardGenreBtns() {
  var btns = document.getElementById('wizard-genre-btns');
  if (btns) btns.remove();
}

// ═══════════════════════════════════════════
// 应用初始化
async function initApp() {
  try {
    // 安全迁移：从后端 API 获取 AI 配置（密钥不在 HTML 中）
    if (window.LocalDB && typeof LocalDB.initAIConfigFromBackend === 'function') {
      LocalDB.initAIConfigFromBackend();
    }
    // Capacitor/APK 模式：提示后端启动中
    if (typeof Capacitor !== 'undefined' && Capacitor.isNative) {
      if (typeof showToast === 'function') showToast('后端启动中，请稍候...', 'info');
      console.log('[initApp] Capacitor 模式，等待 Python 后端启动');
    }
    // 加载项目列表（返回值供书架首页进场判断用）
    var _loadedProjects = [];
    if (typeof loadProjectList === 'function') {
      try { _loadedProjects = (await loadProjectList()) || []; } catch(_eL) { _loadedProjects = []; }
    }
    // 加载工作流状态
    if (typeof loadWorkflowState === 'function') {
      await loadWorkflowState();
    }
    // 加载AI配置
    if (typeof loadModelConfig === 'function') {
      await loadModelConfig();
    }
    // 加载世界设定和叙事风格（确保下拉框回填）
    if (typeof loadProjectSettings === 'function') {
      try { await loadProjectSettings(); } catch(e) { console.warn('loadProjectSettings failed:', e); }
    }
    // 自动加载章节数据（确保按钮点击时chapters不为空）
    if (typeof loadChaptersFromAPI === 'function') {
      try { await loadChaptersFromAPI(); } catch(e) { console.warn('loadChaptersFromAPI failed:', e); }
    }
    // ── 书架首页：进场决策 ──
    // 1) 从书架"继续写"跳转过来（带恢复点）：直接跳到那一章，不再弹书架
    // 2) 书架非空：默认展示书架首页
    // 3) 空书架：保持原行为（加载第1章，下方定时器会弹创作向导）
    var _entryResume = null;
    try { _entryResume = JSON.parse(localStorage.getItem('shuzhai_resume') || 'null'); } catch(_eR) {}
    if (_entryResume) {
      localStorage.removeItem('shuzhai_resume');
      var _resumeCh = (typeof _entryResume.chapter === 'number' && _entryResume.chapter >= 0) ? _entryResume.chapter : 0;
      if (typeof loadChapterContentAPI === 'function') {
        try { await loadChapterContentAPI(_resumeCh); } catch(e) { console.warn('loadChapterContentAPI(resume) failed:', e); }
      }
    } else {
      var _entryPl = Array.isArray(_loadedProjects) ? _loadedProjects : [];
      if (_entryPl.length === 0) {
        try { _entryPl = JSON.parse(localStorage.getItem('shuzhai_project_list') || '[]'); } catch(_eP) {}
      }
      if (_entryPl.length > 0 && window.Reader && typeof Reader.openBookshelf === 'function') {
        // 等 UI 就绪后展示书架（避免与初始化竞态）
        setTimeout(function() { Reader.openBookshelf(); }, 400);
        if (typeof loadChapterContentAPI === 'function') {
          try { await loadChapterContentAPI(0); } catch(e) { console.warn('loadChapterContentAPI failed:', e); }
        }
      } else {
        // 加载第1章内容到编辑器
        if (typeof loadChapterContentAPI === 'function') {
          try { await loadChapterContentAPI(0); } catch(e) { console.warn('loadChapterContentAPI failed:', e); }
        }
      }
    }
    // 刷新上下文面板
    loadContextPanel();
    // 标记数据已加载完成，启动自动保存
    window._dataLoaded = true;
    // 空项目时自动弹出创作向导（延迟确保UI就绪，且向导非活跃时）
    setTimeout(function() {
      if (!window._wizardState) {
        try {
          var _pl = JSON.parse(localStorage.getItem('shuzhai_project_list') || '[]');
          if (_pl.length === 0) startCreativeWizard();
        } catch(_e) {}
      }
    }, 1200);
    // 恢复检查结果（页面刷新后）
    try {
      var restoreIdx = (typeof currentChapterIndex !== 'undefined' && currentChapterIndex >= 0) ? currentChapterIndex : 0;
      // 读取上次使用的scope（保存在localStorage中）
      var lastScope = localStorage.getItem('valResults_lastScope') || 'full';
      var scopes = [lastScope, 'full', 'chapter'];
      var restored = false;
      for (var si = 0; si < scopes.length && !restored; si++) {
        var rKey = 'valResults_' + (typeof currentProjectId !== 'undefined' ? currentProjectId : 'default') + '_ch' + restoreIdx + '_' + scopes[si];
        var rSaved = localStorage.getItem(rKey);
        if (rSaved) {
          var rData = JSON.parse(rSaved);
          var rDiv = document.getElementById('val-results');
          if (rDiv && rData.html) {
            rDiv.innerHTML = rData.html;
            // 不将 HTML 字符串赋值给 lastValResult（类型不兼容），保留 null 等待下次检查时赋值对象
            restored = true;
            // 恢复问题列表和"一键修复"按钮
            var rProbsKey = 'valProblems_' + (typeof currentProjectId !== 'undefined' ? currentProjectId : 'default') + '_ch' + restoreIdx + '_' + scopes[si];
            var rSavedProbs = localStorage.getItem(rProbsKey);
            if (rSavedProbs) {
              try {
                window._allValProblems = JSON.parse(rSavedProbs);
                // 重新绑定"一键修复"按钮事件
                var rFixBtn = rDiv.querySelector('#fix-all-bar button');
                if (rFixBtn) {
                  rFixBtn.onclick = function() { valAIFixAll(); };
                }
              } catch(e2) { /* ignore */ }
            }
            // 恢复scope单选按钮状态
            var scopeRadio = document.querySelector('input[name="check-scope"][value="' + scopes[si] + '"]');
            if (scopeRadio) scopeRadio.checked = true;
            console.log('Restored val results for ch' + restoreIdx + ' ' + scopes[si]);
          }
        }
      }
    } catch(e) { /* ignore */ }
  } catch(e) { console.error('Init error:', e); }
}

// ── Load model config on init ──
document.addEventListener('DOMContentLoaded', async function() {
  setTimeout(loadModelConfig, 500);
  // 检查是否首次启动（AI未配置）
  setTimeout(checkFirstLaunch, 800);
  // 加载项目列表和数据
  setTimeout(initApp, 300);
  // 初始化技能包检查按钮
  setTimeout(function() { if (typeof renderSkillCheckList === 'function') renderSkillCheckList(); }, 1000);

  // ── 撤销 / 重做 ──
  var btnUndo = document.getElementById('btn-undo');
  var btnRedo = document.getElementById('btn-redo');
  var editorEl = document.getElementById('editor-content');
  function doUndo() {
    if (editorEl) { editorEl.focus(); document.execCommand('undo', false, null); }
  }
  function doRedo() {
    if (editorEl) { editorEl.focus(); document.execCommand('redo', false, null); }
  }
  if (btnUndo) btnUndo.addEventListener('click', doUndo);
  if (btnRedo) btnRedo.addEventListener('click', doRedo);
  document.addEventListener('keydown', function(e) {
    if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey) { e.preventDefault(); doUndo(); }
    if ((e.ctrlKey || e.metaKey) && (e.key === 'y' || (e.key === 'z' && e.shiftKey))) { e.preventDefault(); doRedo(); }
  });

  // Load project info and chapters on startup
  try {
    var info = await loadProjectInfo();
    if (info.ok) {
      var elP = document.getElementById('project-name');
      var elC = document.getElementById('current-chapter-label');
      if (elP) elP.textContent = info.title || '';
      if (elC) elC.textContent = info.genre || '';
    }
    // Load project settings (world settings, characters, etc.) from backend
    await loadProjectSettings();
    // Load project outline (novelActs)
    await loadProjectOutline();
    await loadChaptersFromAPI();
    if (chapters && chapters.length > 0) {
      currentChapterIndex = 0;
      if (typeof renderChapterList === 'function') renderChapterList();
      if (typeof renderChapterMiniList === 'function') renderChapterMiniList();
      await loadChapterContentAPI(0);
    }
    // Load context panel after data is ready
    loadContextPanel();
    // 初始化设定编辑器（步骤1）
    setTimeout(function() {
      if (typeof renderSettingsEditor === 'function') renderSettingsEditor();
    }, 100);
    // 恢复上次工作步骤
    setTimeout(function() {
      var lastStep = parseInt(localStorage.getItem('shuzhai_last_step')) || 1;
      if (lastStep > 1 && typeof goToStep === 'function') {
        goToStep(lastStep);
      } else {
        // 步骤1时也调用一次，确保面板状态正确
        if (typeof goToStep === 'function') goToStep(STEPS.世界观);
      }
    }, 200);
    // 标记数据已加载完成，启动自动保存
    window._dataLoaded = true;
  } catch(e) { console.error('Init error:', e); }
});

// ── js/modules/editor.js ──
// Extracted from app.js - 章节编辑器 (loadChaptersFromAPI, autoSaveBeforeChapterSwitch, loadChapterContentAPI)
async function loadChaptersFromAPI() {
  try {
    const r = await getChapterList();
    if (r.ok && r.chapters) {
      if (typeof chapters === 'undefined') window.chapters = [];
      chapters = r.chapters;
      if (typeof renderChapterList === 'function') renderChapterList();
    }
  } catch(e) { console.warn('loadChapters', e); }
}

// P0-1: 切章前自动保存当前蓝图/正文/大纲
async function autoSaveBeforeChapterSwitch() {
  try {
    // 先 flush 防抖保存，确保待保存的数据落盘
    if (window.ShuZhai && ShuZhai.autoSave && typeof ShuZhai.autoSave.flushAutoSave === 'function') {
      try { await ShuZhai.autoSave.flushAutoSave(); } catch(e) { console.warn('flushAutoSave failed:', e); }
    }
    // 草稿模式下阻止自动保存成品，提示用户先处理草稿
    if (window.DraftManager && DraftManager.isActive()) {
      if (typeof showToast === 'function') showToast('⚠️ 有未确认草稿，请先采纳或丢弃');
      return false;
    }
    if (currentChapterIndex < 0 || !chapters || !chapters[currentChapterIndex]) return;
    var idx = currentChapterIndex;
    // 保存章节大纲和蓝图（必须传immediate=true，否则防抖回调会在currentChapterIndex更新后执行，导致大纲保存到错误的章节）
    if (typeof saveChapterOutline === 'function' && typeof chOutline !== 'undefined') {
      try { saveChapterOutline(true); } catch(e) { console.warn('autoSave outline failed:', e); }
    }
    // 保存正文（如果编辑器有内容且与已存不同）
    var editorEl = document.getElementById('editor-content');
    if (editorEl) {
      var content = editorEl.innerText || '';
      if (content.trim() && chapters[idx] && chapters[idx].content !== content) {
        try {
          await saveChapter(idx, content);
          chapters[idx].content = content;
        } catch(e) { console.warn('autoSave content failed:', e); }
      }
    }
    // P1-7: 清理切章时的临时建议
    window._aiSuggestions = null;
  } catch(e) {
    console.warn('autoSaveBeforeChapterSwitch error:', e);
  }
}

// Load chapter content on select
async function loadChapterContentAPI(index) {
  // 草稿模式下阻止切章
  if (window.DraftManager && DraftManager.isActive()) {
    var action = confirm('当前章节有未确认的草稿。\n\n点击"确定"丢弃草稿并切换章节\n点击"取消"留在当前章节');
    if (!action) return;
    DraftManager.forceExit();
  }
  // 借鉴既有冲突检测模式：OperationContext 冲突检测
  // 如果有活跃的异步AI操作正在进行（如AI修复、生成正文），阻止切章
  if (window.OperationContext && OperationContext.hasActiveWrite()) {
    var ctx = OperationContext.getActive();
    var action2 = confirm(
      '当前正在进行「' + ctx.operation + '」（第' + (ctx.chapterIndex + 1) + '章）。\n\n' +
      '切换章节可能导致AI操作结果保存到错误的章节！\n\n' +
      '点击"确定"强制切换（可能丢失AI结果）\n' +
      '点击"取消"等待操作完成'
    );
    if (!action2) return;
    // 用户选择强制切换，释放操作上下文
    OperationContext.release(ctx);
  }
  // P0-1: 切章前自动保存
  if (index !== currentChapterIndex) {
    await autoSaveBeforeChapterSwitch();
  }
  // 更新当前章节索引
  currentChapterIndex = index;
  // 书架首页：记住本书写到的章节（供"继续写"恢复）
  if (window.Reader && typeof Reader.rememberWriteChapter === 'function') {
    Reader.rememberWriteChapter(index);
  }
  // Fix 3: 跨章节上下文校验 — 清空旧检查结果对象和UI
  if (typeof lastValResult !== 'undefined' && lastValResult && lastValResult.chapterIndex !== index) {
    lastValResult = null;
    var vDiv3 = document.getElementById('val-results');
    if (vDiv3) vDiv3.innerHTML = '<div class="val-empty-hint" style="padding:12px;color:var(--muted);font-size:12px;text-align:center">点击上方检查按钮或AI责编按钮，结果将在这里显示并保留</div>';
  }
  try {
    const r = await selectChapter(index);
    if (r.ok) {
      document.getElementById('editor-title').textContent = r.title || ('第' + (index + 1) + '章');
      document.getElementById('editor-content').innerHTML = textToHTML(r.content || '');
      document.getElementById('word-count').textContent = (r.word_count || 0).toLocaleString('zh-CN');
      // 更新写作工具栏
      if (typeof updateWritingToolbar === 'function') updateWritingToolbar();
      // 更新定稿按钮状态
      var lockBtn = document.getElementById('btn-chapter-lock');
      if (lockBtn && typeof chapters !== 'undefined' && chapters[index]) {
        if (chapters[index].locked === true) {
          lockBtn.textContent = '🔓 解锁';
          lockBtn.style.background = 'rgba(231,76,60,0.1)';
        } else {
          lockBtn.textContent = '🔒 暂锁草稿';
          lockBtn.style.background = 'rgba(108,92,231,0.05)';
        }
      }
      
      // 加载章节大纲
      if (r.outline) {
        // 如果outline是JSON格式，用正则提取关键字段（避免JSON解析失败）
        var isJsonOutline = (window.JsonParser && JsonParser.isJsonFormat) ? JsonParser.isJsonFormat(r.outline)
          : (r.outline.trim().startsWith('```json') || r.outline.trim().startsWith('{'));
        if (isJsonOutline) {
          // 使用统一的 JSON 解析工具（任务4：去重）
          if (window.JsonParser && JsonParser.extractOutlineFromJSON) {
            chOutline = JsonParser.extractOutlineFromJSON(r.outline);
          } else {
            // fallback: 内联实现（兼容未加载 utils 的情况）
            var textLinesFb = [];
            function _ef(text, field) {
              var pat = '"' + field + '"\\s*:\\s*"([^"]*(?:\\\\.[^"]*)*)"';
              var ms = [], re = new RegExp(pat, 'g'), m;
              while ((m = re.exec(text)) !== null) ms.push(m[1].replace(/\\"/g, '"').replace(/\\n/g, ' '));
              return ms;
            }
            var sc = _ef(r.outline, 'scene'), at = _ef(r.outline, 'atmosphere');
            var tr = _ef(r.outline, 'trigger'), ev = _ef(r.outline, 'event');
            var cf = _ef(r.outline, 'conflict'), tw = _ef(r.outline, 'twist');
            var ns = _ef(r.outline, 'new_state'), nh = _ef(r.outline, 'next_hook');
            if (sc.length > 0) textLinesFb.push('【起】' + sc[0]);
            if (at.length > 0) textLinesFb.push('氛围：' + at[0]);
            if (tr.length > 0) textLinesFb.push('触发：' + tr[0]);
            ev.forEach(function(e, i) { if (e) textLinesFb.push('【承' + (i+1) + '】' + e); });
            if (cf.length > 0) textLinesFb.push('【转】' + cf[0]);
            if (tw.length > 0) textLinesFb.push('转折：' + tw[0]);
            if (ns.length > 0) textLinesFb.push('【合】' + ns[0]);
            if (nh.length > 0) textLinesFb.push('钩子：' + nh[0]);
            if (textLinesFb.length > 0) {
              chOutline = textLinesFb.map(function(l, i) { return {text: l.trim(), current: i === 0, source: 'parsed'}; });
            } else {
              var rawL = r.outline.split('\n').filter(function(l) {
                var t = l.trim();
                return t && !t.startsWith('"') && !t.startsWith('{') && !t.startsWith('}') && !t.startsWith('[') && !t.startsWith(']') && !t.startsWith('```');
              });
              chOutline = rawL.map(function(l, i) { return {text: l.trim(), current: i === 0, source: 'saved'}; });
            }
          }
        } else {
          // 普通文本大纲
          var lines = r.outline.split('\n').filter(function(l) { return l.trim(); });
          chOutline = lines.map(function(l, i) {
            return {text: l.trim(), current: i === 0, source: 'saved'};
          });
        }
      } else {
        // 没有保存的大纲，尝试从全书大纲中提取对应章节的事件
        chOutline = extractOutlineFromNovelActs(index);
      }
      // 恢复结构化蓝图（如果已保存）
      if (r.blueprint) {
        window._currentBlueprint = r.blueprint;
      } else if (chapters && chapters[index] && chapters[index].blueprint) {
        window._currentBlueprint = chapters[index].blueprint;
      } else {
        window._currentBlueprint = null;
      }
      // 如果blueprint为空但outline是JSON格式，用正则提取关键字段
      if (!window._currentBlueprint && r.outline) {
        var isJsonOL = (window.JsonParser && JsonParser.isJsonFormat) ? JsonParser.isJsonFormat(r.outline)
          : (r.outline.trim().startsWith('```json') || r.outline.trim().startsWith('{'));
        if (isJsonOL) {
          // 使用统一的 JSON 解析工具（任务4：去重）
          if (window.JsonParser && JsonParser.parseBlueprintFromJSON) {
            var bp = JsonParser.parseBlueprintFromJSON(r.outline);
            if (bp) {
              window._currentBlueprint = bp;
            }
          } else {
            // fallback: 内联实现（兼容未加载 utils 的情况）
            function _ef2(text, field) {
              var pat = '"' + field + '"\\s*:\\s*"([^"]*(?:\\\\.[^"]*)*)"';
              var ms = [], re = new RegExp(pat, 'g'), m;
              while ((m = re.exec(text)) !== null) ms.push(m[1].replace(/\\"/g, '"').replace(/\\n/g, ' '));
              return ms;
            }
            var bpS = _ef2(r.outline, 'scene'), bpE = _ef2(r.outline, 'event');
            var bpC = _ef2(r.outline, 'characters'), bpCf = _ef2(r.outline, 'conflict');
            var bpT = _ef2(r.outline, 'twist'), bpTr = _ef2(r.outline, 'trigger');
            var bpN = _ef2(r.outline, 'new_state'), bpH = _ef2(r.outline, 'next_hook');
            if (bpS.length > 0 || bpE.length > 0 || bpC.length > 0) {
              var devA = [];
              var mL = Math.max(bpS.length, bpE.length, bpC.length);
              for (var di = 0; di < mL; di++) {
                devA.push({ scene: bpS[di] || '', event: bpE[di] || '', characters: bpC[di] ? [bpC[di]] : [] });
              }
              window._currentBlueprint = {
                intro: {scene: bpS[0] || '', trigger: bpTr[0] || ''},
                development: devA,
                climax: {conflict: bpCf[0] || '', twist: bpT[0] || ''},
                ending: {new_state: bpN[0] || '', next_hook: bpH[0] || ''}
              };
            }
          }
        }
      }
      // 如果当前在章节大纲步骤，刷新编辑器
      if (typeof workflowState !== 'undefined' && currentWorkflowStep === STEPS.章节大纲 && typeof renderChapterOutlineEditor === 'function') {
        renderChapterOutlineEditor();
      }
      
      // 恢复该章节的检查结果
      try {
        var curScope = (document.querySelector('input[name="check-scope"]:checked') || {}).value || 'chapter';
        // 先尝试当前scope，再尝试full，再尝试chapter
        var scopes = [curScope, 'full', 'chapter'];
        var restored = false;
        for (var si = 0; si < scopes.length && !restored; si++) {
          var restoreKey = 'valResults_' + (typeof currentProjectId !== 'undefined' ? currentProjectId : 'default') + '_ch' + index + '_' + scopes[si];
          var saved = localStorage.getItem(restoreKey);
          if (saved) {
            var savedData = JSON.parse(saved);
            // Fix 4: 校验章节上下文，不匹配则跳过
            if (savedData.chapterIndex !== undefined && savedData.chapterIndex !== index) {
              continue;
            }
            var vDiv = document.getElementById('val-results');
            if (vDiv && savedData.html) {
              vDiv.innerHTML = savedData.html;
              // 不将HTML字符串赋值给lastValResult（类型不兼容），保留null
              restored = true;
              // 恢复问题列表和"一键修复"按钮
              var probsKey = 'valProblems_' + (typeof currentProjectId !== 'undefined' ? currentProjectId : 'default') + '_ch' + index + '_' + scopes[si];
              var savedProbs = localStorage.getItem(probsKey);
              if (savedProbs) {
                try {
                  window._allValProblems = JSON.parse(savedProbs);
                  // 重新绑定"一键修复"按钮事件（恢复的HTML中onclick可能失效）
                  var fixBtn = vDiv.querySelector('#fix-all-bar button');
                  if (fixBtn) {
                    fixBtn.onclick = function() { valAIFixAll(); };
                  }
                } catch(e2) { /* ignore */ }
              }
              // 恢复scope单选按钮状态
              var scopeRadio = document.querySelector('input[name="check-scope"][value="' + scopes[si] + '"]');
              if (scopeRadio) scopeRadio.checked = true;
            }
          }
        }
      } catch(e) { /* ignore */ }
    }
    // 刷新上下文面板（根据当前章节的blueprint显示本章角色、场景、写作建议）
    if (typeof loadContextPanel === 'function') loadContextPanel();
  } catch(e) { console.error('loadChapter', e); }
}

