// 清空检查结果（供 goToStep 调用，避免跨步骤/跨章节显示旧结果）
function clearValResults() {
  var vDiv = document.getElementById('val-results');
  if (vDiv) vDiv.innerHTML = '<div class="val-empty-hint" style="padding:12px;color:var(--muted);font-size:12px;text-align:center">点击上方检查按钮或AI责编按钮，结果将在这里显示并保留</div>';
  if (typeof lastValResult !== 'undefined') lastValResult = null;
  // 清除所有检查按钮的状态
  document.querySelectorAll('.check-btn').forEach(function(b) {
    b.classList.remove('has-issue', 'done', 'running');
    var origLabel = b.dataset.check;
    if (origLabel) {
      var labels = {drift:'偏差',twist:'转折',duplicate:'重复',style:'风格',conflict:'冲突',timeline:'时间线',quality:'质量',memory:'记忆',completeness:'完整性',continuity:'连贯性',consistency:'一致性',wordcount:'字数预算'};
      b.textContent = labels[origLabel] || origLabel;
    }
  });
}


// ── js/modules/val-actions.js ──
  /* ---- MANUAL FIX RUNNER ---- */
  function runManualFix(issueType, fieldId){
    const el = document.getElementById(fieldId);
    if(el){el.focus();el.classList.add('conflict-highlight');setTimeout(()=>el.classList.remove('conflict-highlight'),3000);showToast('请手动修复');}
  }

  /* ---- VALIDATION ACTION HANDLERS ---- */
  // ═══ 全局模糊匹配函数（valAIFix和valAIFixAll共用）═══
  // 在原文中模糊查找匹配位置，返回 {index, length}，未找到返回 {index:-1, length:0}
  window._fuzzyFind = function(text, target) {
    if (!target || target.length < 5) return { index: -1, length: 0 };
    // 快速路径：精确匹配
    var idx = text.indexOf(target);
    if (idx >= 0) return { index: idx, length: target.length };
    // 去掉首尾引号和标点后再试
    var cleaned = target.replace(/^["""''《]+/, '').replace(/["""''》]+$/, '').trim();
    if (cleaned.length > 10) {
      idx = text.indexOf(cleaned);
      if (idx >= 0) return { index: idx, length: cleaned.length };
    }
    // 取target的前30个字符做模糊匹配
    var prefix = cleaned.substring(0, Math.min(30, cleaned.length));
    if (prefix.length > 10) {
      idx = text.indexOf(prefix);
      if (idx >= 0) return { index: idx, length: cleaned.length };
    }
    // 去掉所有空格和换行后再匹配
    var textNoSpace = text.replace(/\s+/g, '');
    var targetNoSpace = cleaned.replace(/\s+/g, '');
    if (targetNoSpace.length > 10 && textNoSpace.indexOf(targetNoSpace) !== -1) {
      var posNoSpace = textNoSpace.indexOf(targetNoSpace);
      var realPos = 0;
      for (var i = 0; i < posNoSpace; i++) {
        while (realPos < text.length && /\s/.test(text[realPos])) { realPos++; }
        realPos++;
      }
      var endPos = realPos;
      for (var i = 0; i < targetNoSpace.length; i++) {
        while (endPos < text.length && /\s/.test(text[endPos])) { endPos++; }
        endPos++;
      }
      return { index: realPos, length: endPos - realPos };
    }
    // 取target的前20个字符(去空格)做匹配
    var prefixNoSpace = targetNoSpace.substring(0, Math.min(20, targetNoSpace.length));
    if (prefixNoSpace.length > 8 && textNoSpace.indexOf(prefixNoSpace) !== -1) {
      var pos2 = textNoSpace.indexOf(prefixNoSpace);
      var realPos2 = 0;
      for (var i = 0; i < pos2; i++) {
        while (realPos2 < text.length && /\s/.test(text[realPos2])) { realPos2++; }
        realPos2++;
      }
      return { index: realPos2, length: cleaned.length };
    }
    // 取target的中间20个字符做匹配
    if (cleaned.length > 30) {
      var mid = Math.floor(cleaned.length / 2);
      var midPart = cleaned.substring(mid - 10, mid + 10);
      idx = text.indexOf(midPart);
      if (idx >= 0) return { index: idx, length: cleaned.length };
    }
    // bigram相似度滑动窗口匹配（最后兜底）
    var result = window._bigramMatch(text, target);
    if (result.index >= 0) return result;
    return { index: -1, length: 0 };
  };

  // bigram(二元字符组) Jaccard相似度滑动窗口匹配
  window._bigramMatch = function(text, target) {
    if (!target || target.length < 10) return { index: -1, length: 0 };
    function getBigrams(str) {
      var bigrams = {};
      for (var i = 0; i < str.length - 1; i++) {
        var bg = str.substring(i, i + 2);
        bigrams[bg] = (bigrams[bg] || 0) + 1;
      }
      return bigrams;
    }
    function jaccardSimilarity(a, b) {
      var keysA = Object.keys(a);
      var keysB = Object.keys(b);
      var intersection = 0;
      var bSet = {};
      keysB.forEach(function(k) { bSet[k] = true; });
      keysA.forEach(function(k) { if (bSet[k]) intersection++; });
      var union = keysA.length + keysB.length - intersection;
      return union > 0 ? intersection / union : 0;
    }
    var targetBigrams = getBigrams(target);
    var bestScore = 0;
    var bestIdx = -1;
    var bestLen = target.length;
    var paragraphs = text.split(/\n\s*\n/);
    var charOffset = 0;
    for (var p = 0; p < paragraphs.length; p++) {
      var para = paragraphs[p];
      var paraBigrams = getBigrams(para);
      var paraScore = jaccardSimilarity(targetBigrams, paraBigrams);
      if (paraScore > 0.10) {
        var minLen = Math.floor(target.length * 0.7);
        var maxLen = Math.floor(target.length * 1.3);
        var step = Math.max(3, Math.floor(para.length / 80));
        var lenStep = Math.max(1, Math.floor(target.length * 0.05));
        for (var i = 0; i <= para.length - minLen; i += step) {
          for (var len = minLen; len <= maxLen && i + len <= para.length; len += lenStep) {
            var candidate = para.substring(i, i + len);
            var candBigrams = getBigrams(candidate);
            var score = jaccardSimilarity(targetBigrams, candBigrams);
            if (score > bestScore) {
              bestScore = score;
              bestIdx = charOffset + i;
              bestLen = len;
            }
          }
        }
      }
      charOffset += para.length + 2;
    }
    if (bestScore > 0.35) {
      return { index: bestIdx, length: bestLen };
    }
    return { index: -1, length: 0 };
  };

  // AI修复：针对后端格式检查结果（单条）
  // 章节锁定检查：用户手动"定稿"的章节禁止覆盖性AI操作（生成/续写），但允许修复性操作（修复/去AI味）
  function _isChapterLocked(chIdx) {
    if (typeof chapters === 'undefined' || !chapters || chIdx < 0 || chIdx >= chapters.length) return false;
    var ch = chapters[chIdx];
    if (!ch) return false;
    // 只有用户显式标记 locked=true 的章节才锁定
    return ch.locked === true;
  }
  // 挂载到全局，供 validate-ui.js 等其他模块使用
  window._isChapterLocked = _isChapterLocked;

  window.valAIFix = async function(btn) {
    // 锁定当前章节索引，防止异步修复过程中用户切章导致保存到错误章节
    var _fixChapterIndex = currentChapterIndex;
    // AI修复允许在锁定章节上执行（用于修复时间线对照发现的问题）
    // 但需要二次确认，防止误操作
    if (_isChapterLocked(_fixChapterIndex)) {
      if (!confirm('🔒 第' + (_fixChapterIndex+1) + '章已锁定（定稿）。\n\n确定要进行AI修复吗？\n\n修复将修改正文内容以解决对照发现的问题。')) {
        return;
      }
    }
    // 草稿模式下禁止重复修复，避免丢失成品快照
    if (window.DraftManager && DraftManager.isActive()) {
      showToast('⚠️ 请先采纳或丢弃当前草稿，再进行修复');
      return;
    }
    var row = btn.closest('div[style]') && btn.closest('div[style]').parentNode;
    if (!row) row = btn.closest('div');
    var textEl = row.querySelector('.val-text');
    if (!textEl) return;
    var problemText = textEl.innerText || textEl.textContent;
    var checkType = lastValResult ? lastValResult.check_type : 'unknown';

    btn.disabled = true;
    btn.textContent = '⏳ 修复中…';
    showToast('AI正在修复…');

    // 超时保护：120秒后自动恢复按钮
    var fixTimeout = setTimeout(function() {
      btn.disabled = false;
      btn.textContent = '🤖 AI修复';
      showToast('⚠️ 修复超时（120秒），请重试或手动修复');
    }, 120000);

    // 进度提示：每15秒更新按钮文字
    var elapsed = 0;
    var progressTimer = setInterval(function() {
      elapsed += 15;
      if (elapsed < 120) {
        btn.textContent = '⏳ 修复中…(' + elapsed + 's)';
      }
    }, 15000);

    try {
      var editorEl = document.getElementById('editor-content');
      var currentText = editorEl ? editorEl.innerText : '';
      if (!currentText || currentText.length < 50) {
        showToast('❌ 编辑器中没有正文内容');
        clearTimeout(fixTimeout);
        clearInterval(progressTimer);
        btn.disabled = false;
        btn.textContent = '🤖 AI修复';
        return;
      }

      // 局部修复策略：从 lastValResult.structured.issues 提取位置信息，
      // 调用 /api/validate/fix/chapter 进行段落级精准修复
      var issuesForFix = [];
      if (lastValResult && lastValResult.structured && lastValResult.structured.issues
          && lastValResult.structured.issues.length > 0) {
        // 有结构化 issues：逐项转换
        lastValResult.structured.issues.forEach(function(issue) {
          issuesForFix.push({
            check_type: checkType,
            description: issue.description || issue.type || '',
            location: issue.location || '',
            suggestion: issue.suggestion || '',
            severity: issue.severity || 'medium',
          });
        });
      } else {
        // 兜底：无结构化 issues，把整段问题描述作为一个无 location 的问题
        issuesForFix.push({
          check_type: checkType,
          description: problemText.substring(0, 500),
          location: '',
          suggestion: '',
          severity: 'medium',
        });
      }

      var r = await api('/api/validate/fix/chapter', {
        method: 'POST',
        body: JSON.stringify({
          chapter_index: _fixChapterIndex,
          issues: issuesForFix,
          dry_run: false
        })
      });
      clearTimeout(fixTimeout);
      clearInterval(progressTimer);
      if (r.ok) {
        var fixedCount = r.fixed || 0;
        var skippedLocate = r.skipped_locate || 0;
        var skippedFailed = r.skipped_failed || 0;

        // 重新加载章节内容（修复已在后端保存）
        var newContent = currentText;
        try {
          var loadResult = await api('/api/chapter/load?index=' + _fixChapterIndex);
          if (loadResult && loadResult.ok && loadResult.content) {
            newContent = loadResult.content;
          }
        } catch(e) { console.warn('Reload chapter failed:', e); }

        if (newContent.length < 50) {
          showToast('⚠️ 修复后内容过短，未做修改');
          btn.disabled = false;
          btn.textContent = '🤖 AI修复';
          return;
        }

        // 安全检查：字数变化超过50%则阻止
        var lengthChange = Math.abs(newContent.length - currentText.length) / currentText.length;
        if (lengthChange > 0.5) {
          showToast('⚠️ 修复后字数变化' + Math.round(lengthChange*100) + '%，已阻止保存请检查');
          btn.disabled = false;
          btn.textContent = '🤖 AI修复';
          return;
        }

        if (editorEl) {
          // 修复结果写入草稿，不直接替换成品
          if (window.DraftManager) {
            await DraftManager.enter(newContent);
            showToast('修复完成：修复' + fixedCount + '项' +
                      (skippedLocate > 0 ? '，跳过' + skippedLocate + '项无法定位' : '') +
                      '（草稿模式，请确认）');
          } else {
            editorEl.innerHTML = textToHTML(newContent);
            updateWordCount();
            if (typeof _fixChapterIndex !== 'undefined' && _fixChapterIndex >= 0) {
              try {
                await saveChapter(_fixChapterIndex, newContent);
                showToast('✅ 修复完成：修复' + fixedCount + '项 | ' + currentText.length + '→' + newContent.length + '字');
              } catch(e) {
                showToast('✅ 修复完成并写入编辑器（保存失败：' + e.message + '）');
              }
            } else {
              showToast('✅ 修复完成并写入编辑器');
            }
          }
          row.style.borderLeftColor = 'var(--success)';
          btn.style.background = 'var(--success)';
          btn.textContent = '✅ 已修复';
          // 3秒后恢复按钮文字
          setTimeout(function() {
            btn.textContent = '🤖 AI修复';
            btn.style.background = 'var(--accent)';
          }, 3000);
        }

      } else {
        showToast('❌ 修复失败：' + (r.error || 'AI未返回内容'));
      }
      btn.disabled = false;
      btn.textContent = '🤖 AI修复';
    } catch(e) {
      clearTimeout(fixTimeout);
      clearInterval(progressTimer);
      showToast('❌ ' + e.message);
      btn.disabled = false;
      btn.textContent = '🤖 AI修复';
    }
  };

  // 一键综合修复：把所有检查问题综合起来一次性修复
  window.valAIFixAll = async function() {
    // 锁定当前章节索引，防止异步修复过程中用户切章导致保存到错误章节
    var _fixAllChapterIndex = currentChapterIndex;
    // AI修复允许在锁定章节上执行（用于修复时间线对照发现的问题）
    if (_isChapterLocked(_fixAllChapterIndex)) {
      if (!confirm('🔒 第' + (_fixAllChapterIndex+1) + '章已锁定（定稿）。\n\n确定要进行AI批量修复吗？\n\n修复将修改正文内容以解决对照发现的问题。')) {
        return;
      }
    }
    // 草稿模式下禁止批量修复
    if (window.DraftManager && DraftManager.isActive()) {
      showToast('⚠️ 请先采纳或丢弃当前草稿，再进行批量修复');
      return;
    }
    var problems = window._allValProblems || [];
    
    // 兜底：如果 problems 为空，从当前 DOM 中重新提取问题列表
    if (!problems.length) {
      var vDiv = document.getElementById('val-results');
      if (vDiv) {
        var issueItems = vDiv.querySelectorAll('.check-result-item');
        issueItems.forEach(function(item) {
          var textEl = item.querySelector('.val-text');
          var checkType = item.dataset.check || '';
          if (textEl) {
            var text = textEl.innerText || textEl.textContent || '';
            // v4判断逻辑：结论优先（含问题指示检查）+全部否定前缀+清洗文本法
            var _fNeg = ['不一致','不符合','不连贯','不自然','不协调','不合理','不自洽','不匹配','不对齐'];
            var _fNegPrefixes = ['无明显','没有','不存在','未发现','未发现明显','未检测到','无'];
            var _fNoIssue = ['无矛盾','无冲突','无偏离','无重复','没有重复','不存在重复','无问题','没有问题','没有发现','未发现','未检测到','未检测到问题','无遗漏','没有遗漏','未发现明显','无明显问题','一致','符合','通过','对齐','无异常','正常','衔接正常','数据一致','未发现偏离','未发现冲突','未发现矛盾','未发现重复','未发现遗漏','ok','none'];
            var _fIssue = ['偏离','矛盾','冲突','断裂','遗漏','缺乏','缺失','生硬','突兀','混乱','错误','需改进','显著','存在重复','重复描写','重复内容','高度相似','完全相同','雷同'];
            // 第0步：结论优先 — 提取结论句，清洗后检查是否还有问题词
            var fTail = text.substring(Math.max(0, text.length - 80));
            var fTailIsNoIssue = false;
            if (fTail.includes('结论') || fTail.includes('整体评价') || fTail.includes('总结')) {
              // 找到最后一个结论关键词位置，只看结论之后的内容
              var fConclStart = Math.max(fTail.lastIndexOf('结论'), fTail.lastIndexOf('整体评价'), fTail.lastIndexOf('总结'));
              var fConclText = fTail.substring(fConclStart);
              // 生成全部否定前缀+问题词的无问题模式
              var fTailExtra = [];
              for (var fte = 0; fte < _fIssue.length; fte++) {
                for (var fnp2 = 0; fnp2 < _fNegPrefixes.length; fnp2++) { fTailExtra.push(_fNegPrefixes[fnp2] + _fIssue[fte]); }
              }
              var fTailAllNo = _fNoIssue.concat(fTailExtra);
              var fTailHasNo = fTailAllNo.some(function(p){ return fConclText.includes(p); });
              if (fTailHasNo) {
                // 清洗结论句
                var fCleanedConcl = fConclText;
                var fSortedConcl = fTailAllNo.slice().sort(function(a,b){ return b.length - a.length; });
                fSortedConcl.forEach(function(p) { fCleanedConcl = fCleanedConcl.split(p).join(''); });
                var fConclHasIssue = _fIssue.some(function(p){ return fCleanedConcl.includes(p); });
                if (!fConclHasIssue) { fTailIsNoIssue = true; }
              }
            }
            var fHasIssue = false;
            if (fTailIsNoIssue) {
              fHasIssue = false;
            } else {
              // 第0.5步：用正则移除"否定前缀+少量字符+问题词"的否定短语
              var fNegatedText = text;
              // 处理一般问题词
              for (var fnp4 = 0; fnp4 < _fNegPrefixes.length; fnp4++) {
                for (var fip4 = 0; fip4 < _fIssue.length; fip4++) {
                  try {
                    var fEscPrefix = _fNegPrefixes[fnp4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    var fEscIssue = _fIssue[fip4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    var fRe = new RegExp(fEscPrefix + '[^，。！？；]{0,6}' + fEscIssue, 'g');
                    fNegatedText = fNegatedText.replace(fRe, '');
                  } catch(e){console.warn('[Audit]', e)}
                }
              }
              // 也处理否定形式问题词（不一致、不符合等）
              for (var fnp5 = 0; fnp5 < _fNegPrefixes.length; fnp5++) {
                for (var fnip5 = 0; fnip5 < _fNeg.length; fnip5++) {
                  try {
                    var fEscP2 = _fNegPrefixes[fnp5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    var fEscI2 = _fNeg[fnip5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    var fRe2 = new RegExp(fEscP2 + '[^，。！？；]{0,6}' + fEscI2, 'g');
                    fNegatedText = fNegatedText.replace(fRe2, '');
                  } catch(e){console.warn('[Audit]', e)}
                }
              }
              // 第1步：检查否定形式的问题词（在negatedText上检查）
              var fNegHit = false;
              for (var fi = 0; fi < _fNeg.length; fi++) {
                if (fNegatedText.includes(_fNeg[fi])) { fNegHit = true; break; }
              }
              if (fNegHit) {
                fHasIssue = true;
              } else {
                var _fExtra = [];
                for (var fe = 0; fe < _fIssue.length; fe++) {
                  for (var fenp = 0; fenp < _fNegPrefixes.length; fenp++) { _fExtra.push(_fNegPrefixes[fenp] + _fIssue[fe]); }
                }
                var _fAllNo = _fNoIssue.concat(_fExtra);
                var fNoIssue = _fAllNo.some(function(p){ return fNegatedText.includes(p); });
                if (fNoIssue) {
                  var fCleaned = fNegatedText;
                  var fSorted = _fAllNo.slice().sort(function(a,b){ return b.length - a.length; });
                  fSorted.forEach(function(p) { fCleaned = fCleaned.split(p).join(''); });
                  fHasIssue = _fIssue.some(function(p){ return fCleaned.includes(p); });
                } else {
                  fHasIssue = _fIssue.some(function(p){ return fNegatedText.includes(p); });
                }
              }
            }
            if (fHasIssue) {
              problems.push({type: checkType, problem: text.substring(0, 500)});
            }
          }
        });
        // 保存到全局变量供后续使用
        window._allValProblems = problems;
      }
    }
    
    if (!problems.length) { showToast('没有需要修复的问题'); return; }
    
    var editorEl = document.getElementById('editor-content');
    if (!editorEl) { showToast('找不到编辑器'); return; }
    var currentText = editorEl.innerText || '';
    
    // 如果编辑器里没有内容，从后端加载
    if (!currentText.trim()) {
      try {
        var chIdx = typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0;
        var loaded = await api('/api/chapter/load?index=' + chIdx);
        if (loaded && loaded.ok && loaded.content) {
          currentText = loaded.content;
          // 同时把内容显示到编辑器
          if (editorEl) editorEl.innerHTML = textToHTML ? textToHTML(currentText) : currentText.replace(/\n/g, '<br>');
        }
      } catch(e) { console.error('Load chapter for fix failed:', e); }
    }
    if (!currentText.trim()) { showToast('没有正文内容，请先生成正文'); return; }
    
    // 按类型分批修复：内容类 vs 风格类
    var contentTypes = ['drift', 'timeline', 'conflict', 'consistency', 'continuity', 'completeness'];
    var styleTypes = ['style', 'duplicate', 'twist'];
    var contentProblems = problems.filter(function(p) { return contentTypes.indexOf(p.type) >= 0; });
    var styleProblems = problems.filter(function(p) { return styleTypes.indexOf(p.type) >= 0; });
    // 兜底：未分类的问题归入当前批次
    var unclassified = problems.filter(function(p) { return contentTypes.indexOf(p.type) < 0 && styleTypes.indexOf(p.type) < 0; });
    if (unclassified.length > 0) {
      if (contentProblems.length > 0) contentProblems = contentProblems.concat(unclassified);
      else styleProblems = styleProblems.concat(unclassified);
    }
    // 当前批次：优先处理内容类（更关键）
    var currentBatch = contentProblems.length > 0 ? contentProblems : styleProblems;
    var batchLabel = contentProblems.length > 0 ? '内容修复' : '风格润色';

    // 构建当前批次问题列表
    var problemList = '';
    currentBatch.forEach(function(p, i) {
      problemList += (i+1) + '. 【' + p.type + '】' + p.problem + '\n';
    });

    // 找到按钮并禁用
    var fixAllBtn = document.querySelector('#fix-all-bar button');
    if (fixAllBtn) { fixAllBtn.disabled = true; fixAllBtn.textContent = '⏳ ' + batchLabel + '中…'; }
    showToast('AI正在' + batchLabel + '（' + currentBatch.length + '项问题）…');

    // 超时保护：180秒后自动恢复按钮（多问题需要更长时间）
    var fixAllTimeout = setTimeout(function() {
      if (fixAllBtn) { fixAllBtn.disabled = false; fixAllBtn.textContent = '🤖 一键全部修复'; }
      showToast('⚠️ 综合修复超时（180秒），请重试');
    }, 180000);

    // 进度提示
    var allElapsed = 0;
    var allProgressTimer = setInterval(function() {
      allElapsed += 15;
      if (allElapsed < 180 && fixAllBtn) {
        fixAllBtn.textContent = '⏳ 综合修复中…(' + allElapsed + 's)';
      }
    }, 15000);

    try {
      // 收集当前章节大纲，供修复时参考
      var chapterOutlineText = '';
      try {
        var chIdx2 = typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0;
        if (typeof chapters !== 'undefined' && chapters && chapters[chIdx2]) {
          var ol2 = chapters[chIdx2].outline || '';
          if (ol2 && typeof ol2 === 'string' && ol2.trim().length > 5) {
            chapterOutlineText = ol2;
          } else if (ol2 && Array.isArray(ol2) && ol2.length > 0) {
            chapterOutlineText = ol2.map(function(o) { return typeof o === 'string' ? o : (o.text || ''); }).join('\n');
          }
        }
      } catch(e){console.warn('[Audit]', e)}

      // 构建结构化问题列表（转换为局部修复所需格式）
      var issuesForFix = [];
      currentBatch.forEach(function(p) {
        if (p.issues && p.issues.length > 0) {
          p.issues.forEach(function(issue) {
            issuesForFix.push({
              check_type: p.type,
              description: issue.description || issue.type || '',
              location: issue.location || '',
              suggestion: issue.suggestion || '',
              severity: issue.severity || 'medium',
            });
          });
        } else {
          issuesForFix.push({
            check_type: p.type,
            description: p.problem || '',
            location: '',
            suggestion: '',
            severity: 'medium',
          });
        }
      });

      var r = await api('/api/validate/fix/chapter', {
        method: 'POST',
        body: JSON.stringify({
          chapter_index: _fixAllChapterIndex,
          issues: issuesForFix,
          dry_run: false
        })
      });
      clearTimeout(fixAllTimeout);
      clearInterval(allProgressTimer);
      if (r.ok) {
        var fixedCount = r.fixed || 0;
        var skippedLocate = r.skipped_locate || 0;
        var skippedCross = r.skipped_cross || 0;
        var skippedFailed = r.skipped_failed || 0;
        
        // 重新加载章节内容（修复已在后端保存）
        try {
          var loadResult = await api('/api/chapter/load?index=' + _fixAllChapterIndex);
          if (loadResult && loadResult.ok && loadResult.content) {
            var newContent = loadResult.content;
            var oldWordCount = currentText.length;
            var newWordCount = newContent.length;
            var wordChange = newWordCount - oldWordCount;
            
            if (window.DraftManager) {
              await DraftManager.enter(newContent);
              showToast(batchLabel + '完成：修复' + fixedCount + '项，跳过' + skippedLocate + '项无法定位（草稿模式，请确认）');
              if (fixAllBtn) { fixAllBtn.disabled = false; fixAllBtn.textContent = '✅ ' + batchLabel + '完成'; fixAllBtn.style.background = 'var(--success)'; }
            } else {
              editorEl.innerHTML = textToHTML(newContent);
              updateWordCount();
              if (typeof chapters !== 'undefined' && chapters[_fixAllChapterIndex]) {
                chapters[_fixAllChapterIndex].content = newContent;
                chapters[_fixAllChapterIndex].word_count = newContent.length;
              }
              showToast('✅ ' + batchLabel + '完成：修复' + fixedCount + '项，跳过' + skippedLocate + '项无法定位 | ' + oldWordCount + '→' + newWordCount + '字');
              if (fixAllBtn) { fixAllBtn.disabled = false; fixAllBtn.textContent = '✅ ' + batchLabel + '完成'; fixAllBtn.style.background = 'var(--success)'; }
            }
            
            var vDivFix = document.getElementById('val-results');
            if (vDivFix) {
              var summaryBar = document.createElement('div');
              summaryBar.style.cssText = 'padding:10px 12px;margin:4px 0 8px;border-radius:6px;background:var(--accent-soft);border:1px solid var(--accent);font-size:12px';
              var summaryHtml = '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">';
              summaryHtml += '<strong class="text-accent">' + batchLabel + '摘要</strong>';
              summaryHtml += '<span>已修复' + fixedCount + '项</span>';
              if (skippedLocate > 0) summaryHtml += '<span style="color:var(--warn)">跳过' + skippedLocate + '项无法定位</span>';
              if (skippedCross > 0) summaryHtml += '<span class="text-muted">跳过' + skippedCross + '项跨章节问题</span>';
              if (skippedFailed > 0) summaryHtml += '<span class="text-danger">失败' + skippedFailed + '项</span>';
              summaryHtml += '<span style="color:' + (Math.abs(wordChange) > oldWordCount * 0.1 ? 'var(--danger)' : 'var(--muted)') + '">字数: ' + oldWordCount + '→' + newWordCount + (wordChange >= 0 ? '(+' + wordChange + ')' : '(' + wordChange + ')') + '</span>';
              if (Math.abs(wordChange) > oldWordCount * 0.1) {
                summaryHtml += '<span style="color:var(--danger);font-weight:600">⚠ 字数变化超10%</span>';
              }
              var otherBatch = contentProblems.length > 0 ? styleProblems : contentProblems;
              if (otherBatch.length > 0) {
                var nextLabel = contentProblems.length > 0 ? '风格润色' : '内容修复';
                summaryHtml += '<button id="btn-fix-next-batch" style="background:var(--warn);color:#000;border:none;border-radius:4px;padding:3px 10px;font-size:11px;cursor:pointer">🔧 ' + nextLabel + '（' + otherBatch.length + '项）</button>';
              }
              summaryHtml += '<button id="btn-recheck" style="background:var(--accent);color:#fff;border:none;border-radius:4px;padding:3px 10px;font-size:11px;cursor:pointer;margin-left:auto">🔍 重新检查</button>';
              summaryHtml += '</div>';
              summaryBar.innerHTML = summaryHtml;
              vDivFix.insertBefore(summaryBar, vDivFix.firstChild);
              
              var recheckBtn = document.getElementById('btn-recheck');
              if (recheckBtn) {
                recheckBtn.addEventListener('click', function() {
                  var runBtn = document.getElementById('btn-run-checks');
                  if (runBtn) runBtn.click();
                });
              }
          // 绑定"修复下一批"按钮
          var nextBatchBtn = document.getElementById('btn-fix-next-batch');
          if (nextBatchBtn) {
            nextBatchBtn.addEventListener('click', function() {
              window._allValProblems = otherBatch;
              window.valAIFixAll && valAIFixAll();
            });
          }

          // 自动复检：修复完成3秒后自动触发重新检查（检测→修复→复检闭环）
          // 如果修复后还有未解决的问题，显示提示
          var autoRecheckTimer = setTimeout(function() {
            // 只在无其他待处理批次时自动复检
            if (otherBatch.length === 0) {
              var runBtn = document.getElementById('btn-run-checks');
              if (runBtn) {
                // 在复检按钮旁显示自动复检提示
                var autoTag = document.createElement('span');
                autoTag.style.cssText = 'font-size:10px;color:var(--accent);opacity:0.7;margin-left:4px';
                autoTag.textContent = '🔄 自动复检中…';
                recheckBtn.parentNode.insertBefore(autoTag, recheckBtn.nextSibling);
                runBtn.click();
                // 复检完成后移除提示
                setTimeout(function() { if (autoTag.parentNode) autoTag.remove(); }, 60000);
              }
            }
          }, 3000);
          // 结束 if(vDivFix)
          }
          // 结束 if(loadResult && loadResult.ok)
          }
        } catch(e) { console.warn('Load chapter for fix failed:', e); }
      } else {
        showToast('❌ 修复失败: ' + (r.error || '未知错误'));
        if (fixAllBtn) { fixAllBtn.disabled = false; fixAllBtn.textContent = '🤖 一键全部修复'; }
      }
    } catch(e) {
      clearTimeout(fixAllTimeout);
      clearInterval(allProgressTimer);
      showToast('❌ ' + e.message);
      if (fixAllBtn) { fixAllBtn.disabled = false; fixAllBtn.textContent = '🤖 一键全部修复'; }
    }
  };
  window.valManualFix = function(btn) {
    var row = btn.closest('div[style]') && btn.closest('div[style]').parentNode;
    if (!row) row = btn.closest('div');
    var textEl = row.querySelector('.val-text');
    var problemText = textEl ? (textEl.innerText || textEl.textContent).trim() : '';
    
    // 先定位
    window.valLocate(btn);
    
    // 聚焦编辑器
    var editorEl = document.getElementById('editor-content');
    if (editorEl) {
      editorEl.focus();
      editorEl.classList.add('conflict-highlight');
      setTimeout(function() { editorEl.classList.remove('conflict-highlight'); }, 3000);
      showToast('✏️ 请手动修改，完成后保存');
    }
    
    // 按钮状态更新
    btn.textContent = '✏️ 修改中…';
    btn.style.background = 'var(--success)';
  };

  // 定位：在编辑器中高亮问题文本（支持全文模式跨章节跳转）
  window.valLocate = async function(btn) {
    var row = btn.closest('div[style]') && btn.closest('div[style]').parentNode;
    if (!row) row = btn.closest('div');
    var textEl = row.querySelector('.val-text');
    if (!textEl) return;
    var problemText = (textEl.innerText || textEl.textContent).trim();

    // 判断当前步骤：步骤4使用editor-content，步骤1-3使用detail-editor-textarea
    var currentStep = typeof workflowState !== 'undefined' ? workflowState.currentStep : 4;
    var isDetailMode = currentStep !== 4;
    var editorEl = document.getElementById(isDetailMode ? 'detail-editor-textarea' : 'editor-content');
    if (!editorEl) { showToast('编辑器未找到'); return; }

    // 提取候选关键词（与原逻辑一致）
    var candidates = [];
    var quotePatterns = [
      /"([^"]{3,80})"/g,
      /"([^"]{3,80})"/g,
      /「([^」]{3,80})」/g,
      /『([^』]{3,80})』/g,
      /\*\*([^*]{3,80})\*\*/g
    ];
    quotePatterns.forEach(function(re) {
      var m;
      while ((m = re.exec(problemText)) !== null) {
        candidates.push(m[1].trim());
      }
    });
    var descRe = /(?:写道|提到|描写|说道|指出|明确)[：:]\s*["「『]?([^"\n]{3,60})/g;
    var dm;
    while ((dm = descRe.exec(problemText)) !== null) {
      candidates.push(dm[1].trim());
    }
    var listRe = /[-•]\s*([^\n]{3,60})/g;
    var lm;
    while ((lm = listRe.exec(problemText)) !== null) {
      candidates.push(lm[1].trim());
    }
    var exampleRe = /(?:如|例如|比如)[：:]\s*["「『]?([^"\n]{3,60})/g;
    var em;
    while ((em = exampleRe.exec(problemText)) !== null) {
      candidates.push(em[1].trim());
    }
    var seen = {};
    candidates = candidates.filter(function(c) {
      var key = c.substring(0, 20);
      if (seen[key]) return false;
      seen[key] = true;
      return c.length >= 3;
    });

    // 清理候选词的标点
    var cleanCandidates = candidates.map(function(c) {
      return c.replace(/[。，；：！？、]/g, '');
    }).filter(function(c) { return c.length >= 3; });

    // 第1步：在当前章节编辑器中搜索
    var editorText = isDetailMode ? editorEl.value : editorEl.innerText;
    if (!isDetailMode) _clearHighlights(editorEl);

    var matchCount = 0;
    for (var i = 0; i < cleanCandidates.length; i++) {
      var phrase = cleanCandidates[i];
      var idx = editorText.indexOf(phrase);
      if (idx >= 0) {
        matchCount++;
        _highlightInEditor(editorEl, phrase, matchCount === 1);
      } else {
        var short = phrase.substring(0, 10);
        if (short.length >= 3) {
          idx = editorText.indexOf(short);
          if (idx >= 0) {
            matchCount++;
            _highlightInEditor(editorEl, short, matchCount === 1);
          }
        }
      }
    }
    if (matchCount > 0) {
      showToast('📍 已定位 ' + matchCount + ' 处问题位置');
      return;
    }

    // 第2步：当前章节没找到 → 优先从结果项的chapterIndex标记获取
    var targetChapterIdx = -1;
    if (row && row.dataset && row.dataset.chapterIndex !== undefined) {
      targetChapterIdx = parseInt(row.dataset.chapterIndex);
      if (isNaN(targetChapterIdx)) targetChapterIdx = -1;
    }
    
    // 如果没有标记，从问题文本提取章节号
    if (targetChapterIdx < 0) {
      var chapterNumMatch = problemText.match(/第\s*([0-9一二三四五六七八九十百]+)\s*[章节幕]/);
      if (chapterNumMatch) {
        var numStr = chapterNumMatch[1];
        var num = 0;
        if (/^[0-9]+$/.test(numStr)) {
          num = parseInt(numStr);
        } else {
          var cnMap = {'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10};
          if (numStr === '十') num = 10;
          else if (numStr.length === 2 && numStr[0] === '十') num = 10 + (cnMap[numStr[1]]||0);
          else if (numStr.length === 2 && numStr[1] === '十') num = (cnMap[numStr[0]]||0) * 10;
          else if (numStr.length === 3 && numStr[1] === '十') num = (cnMap[numStr[0]]||0) * 10 + (cnMap[numStr[2]]||0);
          else num = cnMap[numStr] || 0;
        }
        if (num > 0) targetChapterIdx = num - 1;
      }
    }

    // 第3步：如果有目标章节且不是当前章节，切换并搜索
    if (targetChapterIdx >= 0 && targetChapterIdx !== currentChapterIndex && typeof chapters !== 'undefined' && targetChapterIdx < chapters.length) {
      showToast('📍 跳转到第' + (targetChapterIdx + 1) + '章定位…');
      // 切换章节
      if (typeof loadChapterContentAPI === 'function') {
        await loadChapterContentAPI(targetChapterIdx);
        await new Promise(function(r) { setTimeout(r, 800); }); // 等待内容加载
      }
      editorEl = document.getElementById(isDetailMode ? 'detail-editor-textarea' : 'editor-content');
      if (!editorEl) return;
      editorText = isDetailMode ? editorEl.value : editorEl.innerText;
      if (!isDetailMode) _clearHighlights(editorEl);
      for (var i2 = 0; i2 < cleanCandidates.length; i2++) {
        var phrase2 = cleanCandidates[i2];
        var idx2 = editorText.indexOf(phrase2);
        if (idx2 >= 0) {
          matchCount++;
          _highlightInEditor(editorEl, phrase2, matchCount === 1);
        } else {
          var short2 = phrase2.substring(0, 10);
          if (short2.length >= 3) {
            idx2 = editorText.indexOf(short2);
            if (idx2 >= 0) {
              matchCount++;
              _highlightInEditor(editorEl, short2, matchCount === 1);
            }
          }
        }
      }
      if (matchCount > 0) {
        showToast('📍 已在第' + (targetChapterIdx + 1) + '章定位 ' + matchCount + ' 处问题');
        return;
      }
    }

    // 第4步：没有明确章节号，遍历所有章节搜索
    if (typeof chapters !== 'undefined' && chapters.length > 1 && cleanCandidates.length > 0) {
      var bestChapter = -1;
      var bestMatchPhrase = '';
      for (var ci = 0; ci < chapters.length; ci++) {
        if (ci === currentChapterIndex) continue; // 当前章节已搜过
        try {
          var chData = await api('/api/chapter/load?index=' + ci);
          if (chData && chData.content) {
            for (var ci2 = 0; ci2 < cleanCandidates.length; ci2++) {
              if (chData.content.indexOf(cleanCandidates[ci2]) >= 0) {
                bestChapter = ci;
                bestMatchPhrase = cleanCandidates[ci2];
                break;
              }
            }
          }
        } catch(e){console.warn('[Audit]', e)}
        if (bestChapter >= 0) break;
      }
      if (bestChapter >= 0) {
        showToast('📍 跳转到第' + (bestChapter + 1) + '章定位…');
        if (typeof loadChapterContentAPI === 'function') {
          await loadChapterContentAPI(bestChapter);
          await new Promise(function(r) { setTimeout(r, 800); });
        }
        editorEl = document.getElementById(isDetailMode ? 'detail-editor-textarea' : 'editor-content');
        if (editorEl) {
          if (!isDetailMode) _clearHighlights(editorEl);
          _highlightInEditor(editorEl, bestMatchPhrase, true);
          showToast('📍 已在第' + (bestChapter + 1) + '章定位到问题');
          return;
        }
      }
    }

    // 第5步：所有策略都失败，回退到关键词搜索（当前章节）
    showToast('未在当前章节中找到匹配，尝试关键词搜索…');
    var keywords = [];
    if (typeof worldSettings !== 'undefined' && worldSettings.length) {
      worldSettings.forEach(function(s) {
        if (s.key && s.key.length >= 2 && s.key.length <= 10) keywords.push(s.key);
      });
    }
    if (typeof chapters !== 'undefined' && chapters.length) {
      chapters.forEach(function(ch) {
        var title = ch.title || '';
        var m = title.match(/·([^·]+)$/);
        if (m && m[1]) keywords.push(m[1]);
      });
    }
    var cnWordRe = /[\u4e00-\u9fa5]{2,4}/g;
    var wm;
    while ((wm = cnWordRe.exec(problemText)) !== null) {
      if (keywords.indexOf(wm[0]) < 0) keywords.push(wm[0]);
    }

    editorText = isDetailMode ? editorEl.value : editorEl.innerText;
    for (var j = 0; j < keywords.length; j++) {
      var kidx = editorText.indexOf(keywords[j]);
      if (kidx >= 0) {
        matchCount++;
        _highlightInEditor(editorEl, keywords[j], matchCount === 1);
      }
    }

    if (matchCount > 0) {
      showToast('📍 已定位 ' + matchCount + ' 处关键词位置');
    } else {
      showToast('未找到匹配文本，可能问题在其他章节');
    }
  };

  // 清除高亮
  function _clearHighlights(editorEl) {
    editorEl.querySelectorAll('.locate-highlight').forEach(function(el) {
      var parent = el.parentNode;
      if (parent) {
        parent.insertBefore(document.createTextNode(el.textContent), el);
        parent.removeChild(el);
        parent.normalize();
      }
    });
  }

  // 在编辑器中高亮指定文本（scroll=true时滚动到第一个）
  function _highlightInEditor(editorEl, phrase, scroll) {
    // 如果是textarea（详情编辑器模式），使用selectionStart/End高亮
    if (editorEl.tagName === 'TEXTAREA') {
      var val = editorEl.value;
      var pos = val.indexOf(phrase);
      if (pos >= 0) {
        editorEl.focus();
        editorEl.setSelectionRange(pos, pos + phrase.length);
        // 计算滚动位置，使选中文本居中
        if (scroll) {
          var lineHeight = parseInt(getComputedStyle(editorEl).lineHeight) || 20;
          var linesBefore = val.substring(0, pos).split('\n').length - 1;
          editorEl.scrollTop = Math.max(0, linesBefore * lineHeight - editorEl.clientHeight / 2);
        }
      }
      return;
    }
    
    // contenteditable模式（步骤4写作编辑器）
    var walker = document.createTreeWalker(editorEl, NodeFilter.SHOW_TEXT, null, false);
    var node;
    while ((node = walker.nextNode()) !== null) {
      var pos = node.textContent.indexOf(phrase);
      if (pos >= 0) {
        var range = document.createRange();
        range.setStart(node, pos);
        range.setEnd(node, pos + phrase.length);

        var span = document.createElement('span');
        span.className = 'locate-highlight';
        span.style.cssText = 'background:var(--warn);color:#000;padding:1px 2px;border-radius:2px;font-weight:600';
        try {
          range.surroundContents(span);
          if (scroll) {
            span.scrollIntoView({behavior:'smooth', block:'center'});
          }
        } catch(e) {
          var sel = window.getSelection();
          sel.removeAllRanges();
          sel.addRange(range);
          if (scroll) {
            node.parentElement.scrollIntoView({behavior:'smooth', block:'center'});
          }
        }
        return;
      }
    }
  }

  // AI修复：针对旧格式多条结果
  window.valAIFixItem = async function(btn, idx) {
    if (window.DraftManager && DraftManager.isActive()) {
      showToast('⚠️ 请先采纳或丢弃当前草稿，再进行修复');
      return;
    }
    if (!lastValResult || !lastValResult.results) return;
    var item = lastValResult.results[idx];
    if (!item) return;
    var _fixChapterIndex = currentChapterIndex;

    btn.disabled = true;
    btn.textContent = '⏳';
    showToast('AI修复中…');

    try {
      var editorEl = document.getElementById('editor-content');
      var currentText = editorEl ? editorEl.innerText : '';

      // 局部修复策略：构造结构化问题，调用 /api/validate/fix/chapter
      var checkType = item.check || item.label || 'unknown';
      var problemDesc = item.msg || item.description || '';
      var location = item.location || '';
      var issuesForFix = [{
        check_type: checkType,
        description: problemDesc,
        location: location,
        suggestion: item.suggestion || '',
        severity: item.severity || 'medium',
      }];

      var r = await api('/api/validate/fix/chapter', {
        method: 'POST',
        body: JSON.stringify({
          chapter_index: _fixChapterIndex,
          issues: issuesForFix,
          dry_run: false
        })
      });

      if (r.ok && editorEl) {
        var fixedCount = r.fixed || 0;
        // 重新加载章节内容（修复已在后端保存）
        var newContent = currentText;
        try {
          var loadResult = await api('/api/chapter/load?index=' + _fixChapterIndex);
          if (loadResult && loadResult.ok && loadResult.content) {
            newContent = loadResult.content;
          }
        } catch(e) { console.warn('Reload chapter failed:', e); }

        if (newContent.length < currentText.length * 0.7) {
          showToast('⚠️ AI修复后内容大幅缩短（' + currentText.length + '→' + newContent.length + '字），已保留原文');
          btn.disabled = false;
          btn.textContent = '🤖';
          return;
        }
        // 通过DraftManager进入草稿模式，避免AutoSave直接覆盖成品
        if (window.DraftManager) {
          await DraftManager.enter(newContent);
        } else {
          editorEl.innerHTML = textToHTML(newContent);
        }
        updateWordCount();
        showToast('✅ AI已修复' + fixedCount + '项（草稿模式，请确认采纳）');
        btn.textContent = '✓';
        btn.style.background = 'var(--success)';
      } else {
        showToast('❌ 修复失败：' + (r.error || '未知错误'));
        btn.disabled = false;
        btn.textContent = '🤖';
      }
    } catch(e) {
      showToast('❌ ' + e.message);
      btn.disabled = false;
      btn.textContent = '🤖';
    }
  };

  // 手动修复：针对旧格式
  window.valManualFixItem = function(btn, idx) {
    if (!lastValResult || !lastValResult.results) return;
    var item = lastValResult.results[idx];
    if (!item) return;
    
    // 先定位
    window.valLocateItem(btn, idx);
    
    // 聚焦编辑器
    var editorEl = document.getElementById('editor-content');
    if (editorEl) {
      editorEl.focus();
      editorEl.classList.add('conflict-highlight');
      setTimeout(function() { editorEl.classList.remove('conflict-highlight'); }, 3000);
      showToast('✏️ 请手动修改');
    }
    
    btn.textContent = '✏️';
    btn.style.background = 'var(--success)';
  };

  // 定位：针对旧格式
  window.valLocateItem = function(btn, idx) {
    if (!lastValResult || !lastValResult.results) return;
    var item = lastValResult.results[idx];
    if (!item) return;
    
    var keywords = (item.msg || '').replace(/^[：:：\s]*/, '').substring(0, 30);
    var editorEl = document.getElementById('editor-content');
    if (!editorEl) return;
    
    var editorText = editorEl.innerText;
    var idx2 = editorText.indexOf(keywords);
    if (idx2 >= 0) {
      var textNode = editorEl.firstChild;
      while (textNode) {
        if (textNode.nodeType === 3 && textNode.textContent.indexOf(keywords) >= 0) {
          var charIdx = textNode.textContent.indexOf(keywords);
          var range = document.createRange();
          range.setStart(textNode, charIdx);
          range.setEnd(textNode, charIdx + keywords.length);
          var sel = window.getSelection();
          sel.removeAllRanges();
          sel.addRange(range);
          range.startContainer.parentElement.scrollIntoView({behavior:'smooth', block:'center'});
          showToast('📍 已定位');
          break;
        }
        textNode = textNode.nextSibling;
      }
    } else {
      showToast('未找到匹配文本');
    }
  };


  window.runManualFix = runManualFix;
// 页面卸载时清理所有进度定时器
window.addEventListener('beforeunload', function() {
  // val-actions.js 中的定时器会在操作完成后自动清理
  // 此处为兜底，防止页面在操作进行中关闭
});


// ── js/modules/val-render.js ──
  /* ---- VALIDATION RESULTS RENDERER ---- */
  // lastValResult 已在 state.js 中统一声明为全局变量（var lastValResult = null）
  // 此处不再重复声明，避免类型不一致

  /**
   * 解析AI返回的结构化检查结果
   * 格式：【问题】xxx【位置】xxx【建议】xxx
   * 返回：[{problem, location, suggestion}, ...]
   */
  function _parseStructuredResult(text) {
    if (!text) return [];
    var issues = [];
    // 匹配【问题】...【位置】...【建议】... 模式
    var pattern = /【问题】([\s\S]*?)(?=【位置】|【建议】|【问题】|$)/g;
    var matches = [];
    var m;
    while ((m = pattern.exec(text)) !== null) {
      matches.push({ problem: m[1].trim() });
    }
    if (matches.length === 0) return [];

    // 提取位置和建议
    var locPattern = /【位置】([\s\S]*?)(?=【问题】|【建议】|【位置】|$)/g;
    var sugPattern = /【建议】([\s\S]*?)(?=【问题】|【位置】|【建议】|$)/g;
    var locs = [];
    var sugs = [];
    while ((m = locPattern.exec(text)) !== null) locs.push(m[1].trim());
    while ((m = sugPattern.exec(text)) !== null) sugs.push(m[1].trim());

    matches.forEach(function(mt, i) {
      issues.push({
        problem: mt.problem,
        location: locs[i] || '',
        suggestion: sugs[i] || ''
      });
    });
    return issues;
  }

  function renderValResult(raw, append, checkType){
    // 保存结果
    if (raw) lastValResult = raw;
    
    // 1. 渲染到右侧面板（原有逻辑）
    const vDiv = document.getElementById('val-results');
    if(vDiv) {
      if(!append) vDiv  .textContent='';
      _renderValResultToDiv(vDiv, raw, checkType);
    }
    
    // 2. 渲染到中间详情编辑器（如果当前不是步骤4）
    var currentStep = typeof workflowState !== 'undefined' ? workflowState.currentStep : 4;
    if (currentStep !== 4) {
      var detailPanel = document.getElementById('detail-editor-panel');
      if (detailPanel) {
        // 清空详情编辑器并显示检查结果
        var emptyEl = document.getElementById('detail-editor-empty');
        if (emptyEl) emptyEl.style.display = 'none';
        var headerEl = document.getElementById('detail-editor-header');
        if (headerEl) headerEl.style.display = 'none';
        var ta = document.getElementById('detail-editor-textarea');
        if (ta) ta.style.display = 'none';
        
        // 创建或获取检查结果容器
        var checkContainer = document.getElementById('detail-check-results');
        if (!checkContainer) {
          checkContainer = document.createElement('div');
          checkContainer.id = 'detail-check-results';
          checkContainer.style.cssText = 'flex:1;overflow-y:auto;padding:16px 24px;';
          detailPanel.appendChild(checkContainer);
        }
        if (!append) checkContainer.textContent = '';
        checkContainer.style.display = 'block';
        
        // 仅在首次（无标题时）添加检查结果标题，避免append模式下重复
        if (!checkContainer.querySelector('.check-results-title')) {
          var titleDiv = document.createElement('div');
          titleDiv.className = 'check-results-title';
          titleDiv.style.cssText = 'font-size:18px;font-weight:600;color:var(--ink);margin-bottom:16px;font-family:var(--serif);border-bottom:1px solid var(--border-soft);padding-bottom:8px;';
          titleDiv.textContent = '🔍 检查结果';
          checkContainer.appendChild(titleDiv);
        }
        
        _renderValResultToDiv(checkContainer, raw, checkType);
      }
    }
  }
  
  // 辅助函数：渲染检查结果到指定容器
  function _renderValResultToDiv(vDiv, raw, checkType){
    if(!vDiv) return;
    
    // ── 完整性/连贯性检查结果特殊渲染 ──
    if (raw && raw.ok && raw.result && (checkType === 'completeness' || checkType === 'continuity')) {
      var r = raw.result;
      // 如果result是字符串（如"第一章无需连贯性检查"），直接显示文本
      if (typeof r === 'string') {
        var label = checkType === 'completeness' ? '完整性' : '连贯性';
        var safeText = String(r).replace(/</g,'&lt;').replace(/>/g,'&gt;');
        var html = '<div class="check-result-item" data-check="'+checkType+'" style="padding:10px 12px;margin:4px 0;border-radius:6px;border-left:3px solid var(--success);background:var(--bg);line-height:1.6">';
        html += '<div class="flex-center-sm">';
        html += '<strong class="text-accent">['+label+']</strong>';
        html += '<span style="color:var(--success);font-size:12px">✓ ' + safeText + '</span>';
        html += '</div></div>';
        vDiv.insertAdjacentHTML('beforeend', html);
        return;
      }
      var score = r.overall_score !== undefined ? r.overall_score : '?';
      var level = r.overall_level || '';
      var label = checkType === 'completeness' ? '完整性' : '连贯性';
      
      // 如果AI返回格式异常（没有score），显示错误信息
      if (r.error) {
        var errHtml = '<div class="check-result-item" data-check="'+checkType+'" style="padding:10px 12px;margin:4px 0;border-radius:6px;border-left:3px solid var(--warn);background:var(--bg);line-height:1.6">';
        errHtml += '<div class="flex-center-sm-mb2">';
        errHtml += '<strong class="text-accent">['+label+']</strong>';
        errHtml += '<span style="color:var(--warn);font-size:12px">⚠ ' + String(r.error).replace(/</g,'&lt;') + '</span>';
        if (r.word_count) errHtml += '<span style="font-size:11px;color:var(--muted);margin-left:auto">'+r.word_count+'字</span>';
        errHtml += '</div>';
        if (r.raw) errHtml += '<div style="font-size:11px;color:var(--muted);padding:4px 8px;background:var(--bg2);border-radius:4px">'+String(r.raw).replace(/</g,'&lt;').substring(0,300)+'</div>';
        errHtml += '</div>';
        vDiv.insertAdjacentHTML('beforeend', errHtml);
        return;
      }
      
      var scoreColor = score >= 8 ? 'var(--success)' : score >= 6 ? 'var(--warn)' : 'var(--danger)';
      var hasIssue = score < 8;
      
      var html = '<div class="check-result-item" data-check="'+checkType+'" style="padding:10px 12px;margin:4px 0;border-radius:6px;border-left:3px solid '+scoreColor+';background:var(--bg);line-height:1.6">';
      html += '<div class="flex-center-sm-mb2">';
      html += '<strong class="text-accent">['+label+']</strong>';
      html += '<span style="font-size:20px;font-weight:700;color:'+scoreColor+'">'+score+'</span>';
      html += '<span class="text-md text-muted">/10 '+level+'</span>';
      if (r.word_count) html += '<span style="font-size:11px;color:var(--muted);margin-left:auto">'+r.word_count+'字</span>';
      if (hasIssue) {
        html += '<div style="margin-left:auto">';
        html += '<button class="val-btn" onclick="valAIFix(this)" title="AI自动修复此问题" style="background:var(--accent);color:#fff;border:none;border-radius:4px;padding:2px 8px;font-size:10px;cursor:pointer;margin-left:4px">🤖 AI修复</button>';
        html += '</div>';
      }
      html += '</div>';
      
      if (r.dimensions) {
        var dimLabels = {
          structure: '结构完整度', emotion_curve: '情绪曲线', info_density: '信息密度',
          length_health: '字数健康', readability: '可读性',
          plot_flow: '情节衔接', character_consistency: '角色一致',
          scene_transition: '场景过渡', foreshadowing: '伏笔承接', pacing: '节奏衔接'
        };
        for (var dim in r.dimensions) {
          var d = r.dimensions[dim];
          var dScore = d.score !== undefined ? d.score : '?';
          var dColor = dScore >= 8 ? 'var(--success)' : dScore >= 6 ? 'var(--warn)' : 'var(--danger)';
          html += '<div style="display:flex;align-items:flex-start;gap:6px;margin:4px 0;padding:4px 8px;background:var(--bg2);border-radius:4px">';
          html += '<span style="color:'+dColor+';font-weight:600;min-width:28px">'+dScore+'</span>';
          html += '<span style="color:var(--muted);min-width:70px;font-size:11px">'+(dimLabels[dim]||dim)+'</span>';
          html += '<span style="color:var(--ink);font-size:11px;flex:1">'+esc(d.comment||'')+'</span>';
          html += '</div>';
          if (d.issues && d.issues.length) {
            d.issues.forEach(function(iss) {
              html += '<div class="text-xs-danger-indent">⚠ '+esc(iss)+'</div>';
            });
          }
          if (d.gap) html += '<div class="text-xs-danger-indent">⚠ 断裂: '+esc(d.gap)+'</div>';
          if (d.conflict) html += '<div class="text-xs-danger-indent">⚠ 矛盾: '+esc(d.conflict)+'</div>';
        }
      }
      
      if (r.summary) html += '<div style="margin-top:6px;font-size:11px;color:var(--ink);padding:4px 8px;background:var(--surface);border-radius:4px">'+esc(r.summary)+'</div>';
      if (r.suggestions && r.suggestions.length) {
        html += '<div style="margin-top:6px"><strong style="font-size:11px;color:var(--accent)">改进建议:</strong>';
        r.suggestions.forEach(function(s) { html += '<div style="font-size:11px;color:var(--muted);padding:2px 0 2px 12px">• '+esc(s)+'</div>'; });
        html += '</div>';
      }
      if (r.gap_points && r.gap_points.length) {
        html += '<div style="margin-top:6px"><strong style="font-size:11px;color:var(--danger)">断裂点:</strong>';
        r.gap_points.forEach(function(g) { html += '<div style="font-size:11px;color:var(--danger);padding:2px 0 2px 12px">⚡ '+esc(g)+'</div>'; });
        html += '</div>';
      }
      // 添加隐藏的val-text，供一键修复收集问题使用
      if (hasIssue) {
        var problemSummary = label + '评分' + score + '/10。';
        if (r.dimensions) {
          var lowDims = [];
          for (var dim in r.dimensions) {
            var dScore = r.dimensions[dim].score;
            if (dScore !== undefined && dScore < 8) {
              lowDims.push(dim + '(' + dScore + '分): ' + (r.dimensions[dim].comment || ''));
            }
          }
          if (lowDims.length) problemSummary += ' 低分维度: ' + lowDims.join('; ');
        }
        if (r.suggestions && r.suggestions.length) {
          problemSummary += ' 建议: ' + r.suggestions.join('; ');
        }
        html += '<div class="val-text" class="hidden">' + esc(problemSummary) + '</div>';
      }
      html += '</div>';
      vDiv.insertAdjacentHTML('beforeend', html);
      return;
    }
    
    // 全局一致性检查：返回results对象（多项子检查）
    if (raw && raw.ok && raw.results && checkType === 'consistency') {
      var label2 = '全局一致性';
      var _cNegPats = ['不一致','不符合','不连贯','不自然','不协调','不合理','不自洽','不匹配','不对齐'];
      var _cNegPrefixes = ['无明显','没有','不存在','未发现','未检测到','未发现明显','无'];
      var _cNoIssuePats = ['无矛盾','无冲突','无偏离','无重复','没有重复','不存在重复','无问题','没有问题','没有发现','未发现','未检测到','未发现问题','没有偏离','未检测到问题','无遗漏','没有遗漏','未发现明显','无明显问题','一致','符合','通过','对齐','无异常','正常','衔接正常','数据一致','未发现偏离','未发现冲突','未发现矛盾','未发现重复','未发现遗漏'];
      var _cIssuePats = ['偏离','矛盾','冲突','断裂','遗漏','缺乏','缺失','生硬','突兀','混乱','错误','需改进','显著','存在重复','重复描写','重复内容','高度相似','完全相同','雷同'];
      var results2 = raw.results;
      var parsedCount2 = raw.parsed_count || 0;
      var totalCount2 = raw.total || Object.keys(results2).length;
      var stageNum = raw.stage || 1;
      var subLabelsFromBackend = raw.sub_labels || {};
      
      // 检查是否有问题（v3：结论优先+否定前缀+清洗文本法）
      var issueCount = 0;
      var allIssueText = [];
      for (var k in results2) {
        if (results2[k]) {
          var text2 = results2[k];
          // 第0步：结论优先 — 提取结论句，清洗后检查是否还有问题词
          var cTail = text2.substring(Math.max(0, text2.length - 80));
          if (cTail.includes('结论') || cTail.includes('整体评价') || cTail.includes('总结')) {
            // 找到最后一个结论关键词位置，只看结论之后的内容
            var cConclStart = Math.max(cTail.lastIndexOf('结论'), cTail.lastIndexOf('整体评价'), cTail.lastIndexOf('总结'));
            var cConclText = cTail.substring(cConclStart);
            var cTailExtra = [];
            for (var cte = 0; cte < _cIssuePats.length; cte++) {
              for (var cnp2 = 0; cnp2 < _cNegPrefixes.length; cnp2++) { cTailExtra.push(_cNegPrefixes[cnp2] + _cIssuePats[cte]); }
            }
            var cTailAllNo = _cNoIssuePats.concat(cTailExtra);
            var cTailHasNo = cTailAllNo.some(function(p){ return cConclText.includes(p); });
            if (cTailHasNo) {
              // 清洗结论句
              var cCleanedConcl = cConclText;
              var cSortedConcl = cTailAllNo.slice().sort(function(a,b){ return b.length - a.length; });
              cSortedConcl.forEach(function(p) { cCleanedConcl = cCleanedConcl.split(p).join(''); });
              var cConclHasIssue = _cIssuePats.some(function(p){ return cCleanedConcl.includes(p); });
              if (!cConclHasIssue) {
                continue; // 结论中只有无问题短语，跳过
              }
            }
          }
          // 第0.5步：用正则移除"否定前缀+少量字符+问题词"的否定短语
          var negatedText = text2;
          for (var cnp4 = 0; cnp4 < _cNegPrefixes.length; cnp4++) {
            for (var cip4 = 0; cip4 < _cIssuePats.length; cip4++) {
              try {
                var cEscPrefix = _cNegPrefixes[cnp4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var cEscIssue = _cIssuePats[cip4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var cRe = new RegExp(cEscPrefix + '[^，。！？；]{0,6}' + cEscIssue, 'g');
                negatedText = negatedText.replace(cRe, '');
              } catch(e) {}
            }
          }
          for (var cnp5 = 0; cnp5 < _cNegPrefixes.length; cnp5++) {
            for (var cip5 = 0; cip5 < _cNegPats.length; cip5++) {
              try {
                var cEscP2 = _cNegPrefixes[cnp5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var cEscI2 = _cNegPats[cip5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var cRe2 = new RegExp(cEscP2 + '[^，。！？；]{0,6}' + cEscI2, 'g');
                negatedText = negatedText.replace(cRe2, '');
              } catch(e) {}
            }
          }
          // 第1步：检查否定形式的问题词（在negatedText上检查）
          var cNegHit = false;
          for (var cni = 0; cni < _cNegPats.length; cni++) {
            if (negatedText.includes(_cNegPats[cni])) { cNegHit = true; break; }
          }
          var cHasIssue = false;
          if (cNegHit) {
            cHasIssue = true;
          } else {
            // 自动补充"否定前缀+问题词"形式（用全部否定前缀）
            var _cExtra = [];
            for (var ce = 0; ce < _cIssuePats.length; ce++) {
              for (var cenp = 0; cenp < _cNegPrefixes.length; cenp++) { _cExtra.push(_cNegPrefixes[cenp] + _cIssuePats[ce]); }
            }
            var _cAllNo = _cNoIssuePats.concat(_cExtra);
            var cNoIssue = _cAllNo.some(function(p){ return negatedText.includes(p); });
            if (cNoIssue) {
              var cleaned2 = negatedText;
              var cSorted = _cAllNo.slice().sort(function(a,b){ return b.length - a.length; });
              cSorted.forEach(function(p) { cleaned2 = cleaned2.split(p).join(''); });
              cHasIssue = _cIssuePats.some(function(p){ return cleaned2.includes(p); });
            } else {
              cHasIssue = _cIssuePats.some(function(p){ return negatedText.includes(p); });
            }
          }
          if (cHasIssue) {
            issueCount++;
            allIssueText.push((subLabelsFromBackend[k]||k) + ': ' + text2);
          }
        }
      }
      var hasIssue2 = issueCount > 0;
      var borderColor = hasIssue2 ? 'var(--danger)' : 'var(--success)';
      var stageLabel = stageNum === 2 ? '阶段2：全文一致性' : '阶段1：设定层一致性';
      
      var html2 = '<div class="check-result-item" data-check="'+checkType+'" style="padding:10px 12px;margin:4px 0;border-radius:6px;border-left:3px solid '+borderColor+';background:var(--bg);line-height:1.6">';
      html2 += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;flex-wrap:wrap">';
      html2 += '<strong class="text-accent">['+label2+']</strong>';
      html2 += '<span class="text-muted-sm">'+stageLabel+'</span>';
      if (hasIssue2) {
        html2 += '<span style="color:var(--danger);font-size:12px">⚠ '+issueCount+'项不一致</span>';
        html2 += '<button class="val-btn" onclick="valAIFix(this)" title="AI修复此问题" style="background:var(--accent);color:#fff;border:none;border-radius:4px;padding:2px 8px;font-size:10px;cursor:pointer;margin-left:auto">🤖 AI修复</button>';
      } else {
        html2 += '<span style="color:var(--success);font-size:12px">✓ 全部一致</span>';
      }
      html2 += '<span class="text-muted-sm">'+parsedCount2+'/'+totalCount2+'项已解析</span>';
      html2 += '</div>';
      
      // 逐项展示
      for (var k2 in results2) {
        if (results2[k2]) {
          var subText = results2[k2];
          // 第0步：结论优先 — 提取结论句，清洗后检查是否还有问题词
          var subTail = subText.substring(Math.max(0, subText.length - 80));
          var subTailIsNoIssue = false;
          if (subTail.includes('结论') || subTail.includes('整体评价') || subTail.includes('总结')) {
            // 找到最后一个结论关键词位置，只看结论之后的内容
            var subConclStart = Math.max(subTail.lastIndexOf('结论'), subTail.lastIndexOf('整体评价'), subTail.lastIndexOf('总结'));
            var subConclText = subTail.substring(subConclStart);
            var subTailExtra = [];
            for (var ste2 = 0; ste2 < _cIssuePats.length; ste2++) {
              for (var snp2 = 0; snp2 < _cNegPrefixes.length; snp2++) { subTailExtra.push(_cNegPrefixes[snp2] + _cIssuePats[ste2]); }
            }
            var subTailAllNo = _cNoIssuePats.concat(subTailExtra);
            var subTailHasNo = subTailAllNo.some(function(p){ return subConclText.includes(p); });
            if (subTailHasNo) {
              // 清洗结论句
              var subCleanedConcl = subConclText;
              var subSortedConcl = subTailAllNo.slice().sort(function(a,b){ return b.length - a.length; });
              subSortedConcl.forEach(function(p) { subCleanedConcl = subCleanedConcl.split(p).join(''); });
              var subConclHasIssue = _cIssuePats.some(function(p){ return subCleanedConcl.includes(p); });
              if (!subConclHasIssue) { subTailIsNoIssue = true; }
            }
          }
          var subHasIssue = false;
          if (subTailIsNoIssue) {
            subHasIssue = false;
          } else {
            // 第0.5步：用正则移除"否定前缀+少量字符+问题词"的否定短语
            var negatedText = subText;
            for (var snp4 = 0; snp4 < _cNegPrefixes.length; snp4++) {
              for (var sip4 = 0; sip4 < _cIssuePats.length; sip4++) {
                try {
                  var sEscPrefix = _cNegPrefixes[snp4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                  var sEscIssue = _cIssuePats[sip4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                  var sRe = new RegExp(sEscPrefix + '[^，。！？；]{0,6}' + sEscIssue, 'g');
                  negatedText = negatedText.replace(sRe, '');
                } catch(e) {}
              }
            }
            for (var snp5 = 0; snp5 < _cNegPrefixes.length; snp5++) {
              for (var sip5 = 0; sip5 < _cNegPats.length; sip5++) {
                try {
                  var sEscP2 = _cNegPrefixes[snp5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                  var sEscI2 = _cNegPats[sip5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                  var sRe2 = new RegExp(sEscP2 + '[^，。！？；]{0,6}' + sEscI2, 'g');
                  negatedText = negatedText.replace(sRe2, '');
                } catch(e) {}
              }
            }
            // 第1步：检查否定形式的问题词（在negatedText上检查）
            var subNegHit = false;
            for (var sni = 0; sni < _cNegPats.length; sni++) {
              if (negatedText.includes(_cNegPats[sni])) { subNegHit = true; break; }
            }
            if (subNegHit) {
              subHasIssue = true;
            } else {
              var _sExtra = [];
              for (var se = 0; se < _cIssuePats.length; se++) {
                for (var senp = 0; senp < _cNegPrefixes.length; senp++) { _sExtra.push(_cNegPrefixes[senp] + _cIssuePats[se]); }
              }
              var _sAllNo = _cNoIssuePats.concat(_sExtra);
              var subNoIssue = _sAllNo.some(function(p){ return negatedText.includes(p); });
              if (subNoIssue) {
                var subCleaned = negatedText;
                var subSorted = _sAllNo.slice().sort(function(a,b){ return b.length - a.length; });
                subSorted.forEach(function(p) { subCleaned = subCleaned.split(p).join(''); });
                subHasIssue = _cIssuePats.some(function(p){ return subCleaned.includes(p); });
              } else {
                subHasIssue = _cIssuePats.some(function(p){ return negatedText.includes(p); });
              }
            }
          }
          var subColor = subHasIssue ? 'var(--danger)' : 'var(--success)';
          var subIcon = subHasIssue ? '⚠' : '✓';
          html2 += '<div style="padding:6px 8px;margin:4px 0;background:var(--surface);border-radius:4px;font-size:12px">';
          html2 += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">';
          html2 += '<span style="color:'+subColor+';font-weight:600">'+subIcon+'</span>';
          html2 += '<strong class="text-ink">'+(subLabelsFromBackend[k2]||k2)+'</strong>';
          html2 += '</div>';
          html2 += '<div style="color:var(--muted);padding-left:20px;white-space:pre-wrap">'+esc(subText)+'</div>';
          html2 += '</div>';
        }
      }
      
      // 隐藏的val-text供一键修复收集
      if (hasIssue2) {
        html2 += '<div class="val-text" class="hidden">'+esc(allIssueText.join('\n'))+'</div>';
      }
      html2 += '</div>';
      vDiv.insertAdjacentHTML('beforeend', html2);
      return;
    }
    
    // Handle backend format: {ok: true, result: "text", check_type: "drift"}
    if (raw && raw.ok && raw.result) {
      const resultText = String(raw.result).trim();
      // 使用v2判断逻辑：优先否定词+清洗文本法
      var _rNeg = ['不一致','不符合','不连贯','不自然','不协调','不合理','不自洽','不匹配','不对齐'];
      var _rNegPrefixes = ['无明显','没有','不存在','未发现','未检测到','未发现明显','无'];
      var _rNoIssue = ['无矛盾','无冲突','无偏离','无重复','没有重复','不存在重复','无问题','没有问题','没有发现','未发现','未检测到','未发现问题','没有偏离','未检测到问题','无遗漏','没有遗漏','未发现明显','无明显问题','一致','符合','通过','对齐','无异常','正常','衔接正常','数据一致','未发现偏离','未发现冲突','未发现矛盾','未发现重复','未发现遗漏','ok','none'];
      var _rIssue = ['偏离','矛盾','冲突','断裂','遗漏','缺乏','缺失','生硬','突兀','混乱','错误','需改进','显著','存在重复','重复描写','重复内容','高度相似','完全相同','雷同'];
      // 优先用issues数组判断
      var issueCount = (raw.issues && raw.issues.length) ? raw.issues.length : 0;
      var hasNoIssue;
      if (issueCount > 0) {
        hasNoIssue = false;
      } else {
        // 第0步：结论优先 — 提取结论句，清洗后检查是否还有问题词
        var rTail = resultText.substring(Math.max(0, resultText.length - 80));
        var rTailIsNoIssue = false;
        if (rTail.includes('结论') || rTail.includes('整体评价') || rTail.includes('总结')) {
          // 找到最后一个结论关键词位置，只看结论之后的内容
          var rConclStart = Math.max(rTail.lastIndexOf('结论'), rTail.lastIndexOf('整体评价'), rTail.lastIndexOf('总结'));
          var rConclText = rTail.substring(rConclStart);
          // 生成全部否定前缀+问题词的无问题模式
          var rTailExtra = [];
          for (var rte = 0; rte < _rIssue.length; rte++) {
            for (var rnp2 = 0; rnp2 < _rNegPrefixes.length; rnp2++) { rTailExtra.push(_rNegPrefixes[rnp2] + _rIssue[rte]); }
          }
          var rTailAllNo = _rNoIssue.concat(rTailExtra);
          var rTailHasNo = rTailAllNo.some(function(p){ return rConclText.includes(p); });
          if (rTailHasNo) {
            // 清洗结论句
            var rCleanedConcl = rConclText;
            var rSortedConcl = rTailAllNo.slice().sort(function(a,b){ return b.length - a.length; });
            rSortedConcl.forEach(function(p) { rCleanedConcl = rCleanedConcl.split(p).join(''); });
            var rConclHasIssue = _rIssue.some(function(p){ return rCleanedConcl.includes(p); });
            if (!rConclHasIssue) { rTailIsNoIssue = true; }
          }
        }
        if (rTailIsNoIssue) {
          hasNoIssue = true;
        } else {
          // 第0.5步：用正则移除"否定前缀+少量字符+问题词"的否定短语（如"无明显风格不一致"）
          var rNegatedText = resultText;
          // 处理一般问题词
          for (var rnp4 = 0; rnp4 < _rNegPrefixes.length; rnp4++) {
            for (var rip4 = 0; rip4 < _rIssue.length; rip4++) {
              try {
                var rEscPrefix = _rNegPrefixes[rnp4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var rEscIssue = _rIssue[rip4].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var rRe = new RegExp(rEscPrefix + '[^，。！？；]{0,6}' + rEscIssue, 'g');
                rNegatedText = rNegatedText.replace(rRe, '');
              } catch(e) {}
            }
          }
          // 也处理否定形式问题词（不一致、不符合等）
          for (var rnp5 = 0; rnp5 < _rNegPrefixes.length; rnp5++) {
            for (var rin5 = 0; rin5 < _rNeg.length; rin5++) {
              try {
                var rEscP2 = _rNegPrefixes[rnp5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var rEscI2 = _rNeg[rin5].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var rRe2 = new RegExp(rEscP2 + '[^，。！？；]{0,6}' + rEscI2, 'g');
                rNegatedText = rNegatedText.replace(rRe2, '');
              } catch(e) {}
            }
          }
          // 第1步：检查否定形式的问题词（在rNegatedText上检查）
          var rNegHit = false;
          for (var ri = 0; ri < _rNeg.length; ri++) {
            if (rNegatedText.includes(_rNeg[ri])) { rNegHit = true; break; }
          }
          if (rNegHit) {
            hasNoIssue = false;
          } else {
            // 第1.5步：自动补充"否定前缀+问题词"形式（用全部否定前缀）
            var _rExtra = [];
            for (var re = 0; re < _rIssue.length; re++) {
              for (var renp = 0; renp < _rNegPrefixes.length; renp++) { _rExtra.push(_rNegPrefixes[renp] + _rIssue[re]); }
            }
            var _rAllNo = _rNoIssue.concat(_rExtra);
            // 第2步：清洗文本法（使用rNegatedText）
            var rNoMatch = _rAllNo.some(function(p){ return rNegatedText.includes(p); });
            if (rNoMatch) {
              var rCleaned = rNegatedText;
              var rSorted = _rAllNo.slice().sort(function(a,b){ return b.length - a.length; });
              rSorted.forEach(function(p) { rCleaned = rCleaned.split(p).join(''); });
              hasNoIssue = !_rIssue.some(function(p){ return rCleaned.includes(p); });
            } else {
              // 第3步：直接检查问题词（使用rNegatedText）
              hasNoIssue = !_rIssue.some(function(p){ return rNegatedText.includes(p); });
            }
          }
        }
      }
      
      const row = document.createElement('div');
      row.className = 'check-result-item';
      if (checkType) row.dataset.check = checkType;
      // 全文模式下记录章节索引，供定位使用
      if (typeof checkScope !== 'undefined' && checkScope === 'full') {
        row.dataset.chapterIndex = (typeof checkIndex !== 'undefined') ? checkIndex : '0';
      }
      row.style.cssText = 'padding:8px 12px;margin:4px 0;border-radius:6px;font-size:12px;border-left:3px solid '+(hasNoIssue?'var(--success)':'var(--warn)')+';background:var(--bg);line-height:1.6';
      
      var titleHTML = '<strong class="text-accent">['+(raw.check_type||checkType||'检查')+']</strong> ';
      
      if (!hasNoIssue) {
        titleHTML += '<div style="float:right;margin-top:-2px">';
        titleHTML += '<button class="val-btn" onclick="valAIFix(this)" title="AI自动修复此问题" style="background:var(--accent);color:#fff;border:none;border-radius:4px;padding:2px 8px;font-size:10px;cursor:pointer;margin-left:4px">🤖 AI修复</button>';
        titleHTML += '<button class="val-btn" onclick="valManualFix(this)" title="手动修改此问题" style="background:var(--warn);color:#fff;border:none;border-radius:4px;padding:2px 8px;font-size:10px;cursor:pointer;margin-left:4px">✏️ 手动修复</button>';
        titleHTML += '<button class="val-btn" onclick="valLocate(this)" title="在编辑器中定位问题位置" style="background:var(--info);color:#fff;border:none;border-radius:4px;padding:2px 8px;font-size:10px;cursor:pointer;margin-left:4px">📍 定位</button>';
        titleHTML += '</div>';
      }
      
      // 解析结构化格式：提取【问题】【位置】【建议】
      var parsedIssues = _parseStructuredResult(resultText);
      var bodyHTML;
      if (parsedIssues.length > 0) {
        // 有结构化问题：渲染为卡片
        bodyHTML = '';
        parsedIssues.forEach(function(pi, pii) {
          bodyHTML += '<div style="padding:6px 8px;margin:4px 0;background:var(--surface);border-radius:4px;border-left:2px solid var(--warn)">';
          bodyHTML += '<div style="color:var(--fg);font-size:12px;margin-bottom:3px"><strong>问题' + (pii+1) + '</strong>：' + esc(pi.problem) + '</div>';
          if (pi.location) bodyHTML += '<div class="text-muted-sm">📍 ' + esc(pi.location) + '</div>';
          if (pi.suggestion) bodyHTML += '<div style="color:var(--info);font-size:11px">💡 ' + esc(pi.suggestion) + '</div>';
          bodyHTML += '</div>';
        });
      } else {
        // 无法解析结构化格式：降级为原始文本
        bodyHTML = resultText.replace(/\n/g,'<br>');
      }
      row.innerHTML = titleHTML + '<div class="val-text" style="margin-top:'+(hasNoIssue?'0':'18')+'px">' + bodyHTML + '</div>';
      vDiv.appendChild(row);
      return;
    }
    
    // Handle error format
    if (raw && raw.ok === false && raw.error) {
      const row = document.createElement('div');
      row.className = 'check-result-item';
      if (checkType) row.dataset.check = checkType;
      row.style.cssText = 'padding:8px 12px;margin:4px 0;border-radius:6px;font-size:12px;border-left:3px solid var(--danger);background:var(--bg);line-height:1.6';
      row.innerHTML = '<strong class="text-danger">[错误]</strong> ' + esc(raw.error);
      vDiv.appendChild(row);
      return;
    }
    
    // Handle old format
    const results = raw && raw.results ? raw.results : (Array.isArray(raw) ? raw : []);
    if(!results || results.length===0){
      vDiv.innerHTML='<div style="padding:8px;color:var(--muted);text-align:center;font-size:11px">无校验结果</div>';
      return;
    }
    results.forEach((res, idx)=>{
      const isError = res.type === 'error' || res.type === 'warning';
      const row = document.createElement('div');
      row.style.cssText = 'padding:4px 8px;margin:2px 0;border-radius:4px;font-size:11px;border-left:3px solid '+(res.type==='error'?'var(--danger)':res.type==='warning'?'var(--warn)':'var(--info)')+';background:var(--bg2)';
      
      var btns = '';
      if (isError) {
        btns = '<div style="float:right;margin-top:-2px">';
        btns += '<button class="val-btn" onclick="valAIFixItem(this,'+idx+')" title="AI自动修复" style="background:var(--accent);color:#fff;border:none;border-radius:4px;padding:1px 6px;font-size:10px;cursor:pointer;margin-left:3px">🤖 AI修复</button>';
        btns += '<button class="val-btn" onclick="valManualFixItem(this,'+idx+')" title="手动修改" style="background:var(--warn);color:#fff;border:none;border-radius:4px;padding:1px 6px;font-size:10px;cursor:pointer;margin-left:3px">✏️ 手动</button>';
        btns += '<button class="val-btn" onclick="valLocateItem(this,'+idx+')" title="定位到编辑器" style="background:var(--info);color:#fff;border:none;border-radius:4px;padding:1px 6px;font-size:10px;cursor:pointer;margin-left:3px">📍 定位</button>';
        btns += '</div>';
      }
      
      row.innerHTML = btns + '<strong>'+(res.label||res.check||'')+':</strong> <span class="val-text">'+esc(res.msg)+'</span>';
      vDiv.appendChild(row);
    });
  }

// Export to global scope
window.renderValResult = renderValResult;


// ── js/modules/check-panel.js ──

/**
 * 检查面板模块
 * 显示批量检查结果，支持段落定位和 AI 修复
 */

var CheckPanel = (function() {
  var _results = null;
  var _currentChapter = null;

  function init() {
    var timelineContainer = document.querySelector('.timeline-container');
    if (timelineContainer && !document.getElementById('check-panel-btn')) {
      var btn = document.createElement('button');
      btn.id = 'check-panel-btn';
      btn.className = 'check-panel-btn';
      btn.textContent = '检查面板';
      btn.onclick = togglePanel;
      timelineContainer.appendChild(btn);
    }
  }

  function togglePanel() {
    var panel = document.getElementById('check-panel');
    if (panel) {
      panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
    } else {
      createPanel();
    }
  }

  function createPanel() {
    var panel = document.createElement('div');
    panel.id = 'check-panel';
    panel.className = 'check-panel';
    panel.innerHTML = '<div class="check-panel-header"><h3>检查问题面板</h3><div class="check-panel-actions"><button class="fix-all-btn" onclick="CheckPanel.fixAll()" title="基于所有检查结果进行综合修复">综合修复</button><button class="close-btn" onclick="CheckPanel.close()">x</button></div></div><div class="check-panel-content" id="check-panel-content"><p class="empty-state">请先运行批量检查</p></div>';
    document.body.appendChild(panel);
  }

  function close() {
    var panel = document.getElementById('check-panel');
    if (panel) panel.style.display = 'none';
  }

  function loadResults(results) {
    _results = results;
    renderPanel();
  }

  function renderPanel() {
    var content = document.getElementById('check-panel-content');
    if (!content) return;

    if (!_results || !_results.results || _results.results.length === 0) {
      content.innerHTML = '<p class="empty-state">暂无检查结果</p>';
      return;
    }

    var html = '';
    _results.results.forEach(function(chResult) {
      var chIdx = chResult.chapter_index;
      var title = chResult.title || '第' + (chIdx + 1) + '章';
      var checks = chResult.checks || {};
      
      var hasIssues = false;
      var issuesHtml = '';
      
      Object.keys(checks).forEach(function(checkType) {
        var check = checks[checkType];
        if (!check.ok) {
          hasIssues = true;
          var paragraphs = check.paragraphs || [];
          
          issuesHtml += '<div class="check-issue-group">';
          issuesHtml += '<div class="check-issue-header">' + getCheckTypeName(checkType) + '</div>';
          issuesHtml += '<div class="check-issue-result">' + (check.content || check.result || '') + '</div>';
          
          if (paragraphs.length > 0) {
            paragraphs.forEach(function(para) {
              issuesHtml += '<div class="problem-card" id="problem-' + chIdx + '-' + para.index + '">';
              issuesHtml += '<div class="problem-card-header"><span class="problem-index">段落 ' + (para.index + 1) + '</span></div>';
              issuesHtml += '<div class="problem-issue">' + esc(para.issue || '') + '</div>';
              issuesHtml += '<div class="problem-suggestion">建议：' + esc(para.suggestion || '') + '</div>';
              issuesHtml += '<div class="problem-card-footer">';
              issuesHtml += '<button class="fix-btn" onclick="CheckPanel.aiFix(' + chIdx + ',' + para.index + ',\'' + esc(checkType).replace(/'/g, "\\'") + '\')">AI 修复</button>';
              issuesHtml += '<button class="ignore-btn" onclick="CheckPanel.ignore(' + chIdx + ',' + para.index + ')">忽略</button>';
              issuesHtml += '</div></div>';
            });
          } else {
            issuesHtml += '<div class="no-paragraph">未定位到具体段落</div>';
          }
          
          issuesHtml += '</div>';
        }
      });
      
      if (hasIssues) {
        html += '<div class="check-chapter-group">';
        html += '<div class="check-chapter-header" onclick="CheckPanel.toggleChapter(' + chIdx + ')">';
        html += '<span class="chapter-title">' + title + '</span>';
        html += '<span class="toggle-icon">v</span>';
        html += '</div>';
        html += '<div class="check-chapter-content" id="chapter-content-' + chIdx + '">';
        html += issuesHtml;
        html += '</div></div>';
      }
    });
    
    if (!html) {
      html = '<p class="empty-state">所有检查项均通过！</p>';
    }
    
    content.innerHTML = html;
  }

  function toggleChapter(chIdx) {
    var content = document.getElementById('chapter-content-' + chIdx);
    if (content) {
      content.style.display = content.style.display === 'none' ? 'block' : 'none';
    }
  }

  function getCheckTypeName(type) {
    var names = {
      'drift': '偏离检查', 'twist': '转折检查', 'duplicate': '重复检查',
      'style': '风格检查', 'timeline': '时间线检查', 'conflict': '冲突检查',
      'quality': '质量检查', 'memory': '记忆检查', 'ai-flavor': 'AI 味检查',
      'outline': '大纲质量', 'setting': '设定质量', 'character': '人物质量',
      'wordcount': '字数检查', 'completeness': '完整性检查',
      'continuity': '连贯性检查', 'consistency': '一致性检查'
    };
    return names[type] || type;
  }

  function aiFix(chIdx, paraIdx, issueType) {
    if (!_results) return;
    
    var chResult = _results.results.find(function(r) { return r.chapter_index === chIdx; });
    if (!chResult) return;
    
    var check = chResult.checks[issueType];
    if (!check || !check.paragraphs) return;
    
    var para = check.paragraphs.find(function(p) { return p.index === paraIdx; });
    if (!para) return;
    
    var card = document.getElementById('problem-' + chIdx + '-' + paraIdx);
    var btn = card ? card.querySelector('.fix-btn') : null;
    if (btn) { btn.textContent = '修复中...'; btn.disabled = true; }
    
    api('/api/validate/fix', {
      method: 'POST',
      body: JSON.stringify({
        chapter_index: chIdx, paragraph_index: paraIdx,
        issue_type: issueType, issue: para.issue || '', suggestion: para.suggestion || ''
      })
    }).then(function(res) {
      if (!res || !res.ok) {
        showToast('修复失败：' + (res && res.message || ''), 'error');
        if (btn) { btn.textContent = 'AI 修复'; btn.disabled = false; }
        return;
      }
      showFixResult(chIdx, paraIdx, res.original, res.fixed);
    }).catch(function(e) {
      showToast('修复失败：' + e.message, 'error');
      if (btn) { btn.textContent = 'AI 修复'; btn.disabled = false; }
    });
  }

  function showFixResult(chIdx, paraIdx, original, fixed) {
    var modal = document.createElement('div');
    modal.className = 'fix-result-modal';
    modal.innerHTML = '<div class="fix-result-content"><h3>修复结果对比</h3><div class="fix-result-body"><div class="fix-result-original"><h4>修改前</h4><p>' + esc(original || '') + '</p></div><div class="fix-result-fixed"><h4>修改后</h4><p>' + esc(fixed || '').substring(0, 2000) + '</p></div></div><div class="fix-result-footer"><button class="confirm-btn" onclick="CheckPanel.confirmFix(' + chIdx + ',' + paraIdx + ')">确认采纳</button><button class="cancel-btn" onclick="CheckPanel.closeFixResult()">取消</button></div></div>';
    document.body.appendChild(modal);
  }

  function confirmFix(chIdx, paraIdx) {
    closeFixResult();
    showToast('已采纳修复', 'success');
    var card = document.getElementById('problem-' + chIdx + '-' + paraIdx);
    if (card) card.classList.add('resolved');
  }

  function closeFixResult() {
    var modal = document.querySelector('.fix-result-modal');
    if (modal) modal.remove();
  }

  function ignore(chIdx, paraIdx) {
    var card = document.getElementById('problem-' + chIdx + '-' + paraIdx);
    if (card) card.classList.add('ignored');
  }

  // 综合修复：基于所有检查结果一次性修复
  function fixAll() {
    if (!_results || !_results.results || _results.results.length === 0) {
      showToast('没有检查结果可供修复');
      return;
    }
    
    // 获取当前章节内容
    var chIdx = _currentChapter !== null ? _currentChapter : 0;
    var chResult = _results.results.find(function(r) { return r.chapter_index === chIdx; });
    if (!chResult) {
      showToast('找不到章节检查结果');
      return;
    }
    
    // 获取章节内容
    var content = '';
    if (typeof chapters !== 'undefined' && chapters[chIdx]) {
      content = chapters[chIdx].content || '';
    }
    if (!content) {
      showToast('章节内容为空');
      return;
    }
    
    // 显示修复中状态
    var contentDiv = document.getElementById('check-panel-content');
    var originalHtml = contentDiv.innerHTML;
    contentDiv.innerHTML = '<div class="fix-all-loading"><div class="loading-spinner"></div><p>正在进行综合修复，请稍候...</p><p class="loading-hint">AI将综合考虑所有问题进行修复</p></div>';
    
    // 调用综合修复API
    api('/api/validate/fix-all', {
      method: 'POST',
      body: JSON.stringify({
        content: content,
        check_result: chResult.checks || {},
        chapter_index: chIdx
      })
    }).then(function(res) {
      if (!res || !res.ok) {
        contentDiv.innerHTML = originalHtml;
        showToast('综合修复失败：' + (res && res.error || '未知错误'), 'error');
        return;
      }
      
      if (res.message === '没有需要修复的问题') {
        contentDiv.innerHTML = originalHtml;
        showToast('检查结果中没有发现需要修复的问题', 'success');
        return;
      }
      
      // 显示修复结果对比
      showFixAllResult(chIdx, res.original, res.fixed, res.issues_fixed, res.issues_summary, res.changed_paragraphs);
    }).catch(function(e) {
      contentDiv.innerHTML = originalHtml;
      showToast('综合修复失败：' + e.message, 'error');
    });
  }
  
  // 显示综合修复结果
  function showFixAllResult(chIdx, original, fixed, issuesFixed, issuesSummary, changedParagraphs) {
    var modal = document.createElement('div');
    modal.className = 'fix-result-modal fix-all-modal';
    
    var summaryHtml = '';
    if (issuesSummary && issuesSummary.length > 0) {
      summaryHtml = '<div class="fix-summary"><h4>修复的问题：</h4><ul>';
      issuesSummary.forEach(function(issue) {
        summaryHtml += '<li>' + issue + '</li>';
      });
      summaryHtml += '</ul></div>';
    }
    
    modal.innerHTML = '<div class="fix-result-content fix-all-content">'
      + '<h3>综合修复结果</h3>'
      + '<p class="fix-stats">共修复 ' + (issuesFixed || 0) + ' 个问题（混合模式：仅修改问题段落）</p>'
      + (changedParagraphs && changedParagraphs.length > 0 
        ? '<p class="fix-paragraphs-info">修改了第 ' + changedParagraphs.join(', ') + ' 段</p>' 
        : '')
      + summaryHtml
      + '<div class="fix-result-body">'
      + '<div class="fix-result-original"><h4>修改前</h4><div class="fix-text">' + (original || '').substring(0, 2000) + '...</div></div>'
      + '<div class="fix-result-fixed"><h4>修改后</h4><div class="fix-text">' + (fixed || '').substring(0, 2000) + '...</div></div>'
      + '</div>'
      + '<div class="fix-result-footer">'
      + '<button class="confirm-btn" onclick="CheckPanel.confirmFixAll(' + chIdx + ')">确认采纳</button>'
      + '<button class="cancel-btn" onclick="CheckPanel.closeFixResult()">取消</button>'
      + '</div></div>';
    
    document.body.appendChild(modal);
    
    // 存储修复结果供确认时使用
    window._pendingFixAll = { chIdx: chIdx, fixed: fixed };
  }
  
  // 确认综合修复
  function confirmFixAll(chIdx) {
    closeFixResult();
    
    if (!window._pendingFixAll) {
      showToast('修复结果已丢失');
      return;
    }
    
    var fixed = window._pendingFixAll.fixed;
    
    // 更新章节内容
    if (typeof chapters !== 'undefined' && chapters[chIdx]) {
      chapters[chIdx].content = fixed;
      chapters[chIdx].word_count = fixed.length;
    }
    
    // 保存到后端
    if (typeof saveChapter === 'function') {
      saveChapter(chIdx, fixed).then(function() {
        showToast('综合修复已采纳并保存', 'success');
        // 更新编辑器显示
        var editorEl = document.getElementById('editor-content');
        if (editorEl) {
          editorEl.innerText = fixed;
        }
        if (typeof updateWordCount === 'function') updateWordCount();
      }).catch(function(e) {
        showToast('保存失败：' + e.message, 'error');
      });
    }
    
    window._pendingFixAll = null;
  }
  
  // 显示单个章节的检查结果（供工作流调用）
  function showCheckResult(checkResult, chapterIndex) {
    _currentChapter = chapterIndex;
    
    // 构造与批量检查相同的数据结构
    _results = {
      ok: true,
      results: [{
        chapter_index: chapterIndex,
        title: '第' + (chapterIndex + 1) + '章',
        checks: checkResult.checks || {}
      }]
    };
    
    // 确保面板已创建
    var panel = document.getElementById('check-panel');
    if (!panel) {
      createPanel();
      panel = document.getElementById('check-panel');  // 重新获取引用
    }
    
    // 显示面板
    if (panel) panel.style.display = 'block';
    
    // 渲染结果
    renderPanel();
  }

  // ═══ 30维全书检查结果展示 ═══
  function showProjectReview(reviewResult) {
    if (!panel) init();
    var contentDiv = document.getElementById('check-panel-content');
    if (!contentDiv) return;

    var categories = [
      {key: 'outline_quality', name: '大纲质量（10维）', icon: '📖'},
      {key: 'settings_quality', name: '设定质量（10维）', icon: '🌍'},
      {key: 'characters_quality', name: '人物质量（10维）', icon: '👤'}
    ];

    var html = '<div class="project-review-result">';
    html += '<h3 style="margin:8px 0;color:#4a90d9">📊 30维全书检查报告</h3>';

    var totalIssues = 0;
    var totalScore = 0;
    var totalDims = 0;

    categories.forEach(function(cat) {
      var data = reviewResult[cat.key];
      if (!data || !data.dimensions) return;

      var catScore = 0;
      var catDims = 0;
      html += '<div class="review-category" style="margin:10px 0;padding:10px;background:rgba(74,144,217,0.05);border-radius:8px;border-left:3px solid #4a90d9">';
      html += '<h4 style="margin:0 0 8px 0">' + cat.icon + ' ' + cat.name + '</h4>';
      html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:4px 12px;font-size:13px">';

      data.dimensions.forEach(function(dim) {
        var score = dim.score || 0;
        var statusIcon = score >= 9 ? '✅' : score >= 7 ? '✓' : score >= 5 ? '⚠️' : '❌';
        var scoreColor = score >= 9 ? '#4CAF50' : score >= 7 ? '#8BC34A' : score >= 5 ? '#FF9800' : '#f44336';
        html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0">';
        html += '<span>' + statusIcon + ' ' + esc(dim.name) + '</span>';
        html += '<span style="color:' + scoreColor + ';font-weight:bold">' + score + '分</span>';
        html += '</div>';
        catScore += score;
        catDims++;
        if (score <= 4) totalIssues++;
      });

      html += '</div>';
      var catAvg = catDims > 0 ? (catScore / catDims).toFixed(1) : 0;
      html += '<div style="text-align:right;margin-top:6px;font-size:12px;color:#888">均分: <b style="color:#4a90d9">' + catAvg + '</b>/10</div>';
      if (data.summary) {
        html += '<div style="margin-top:4px;font-size:12px;color:#666;padding:4px 8px;background:rgba(0,0,0,0.03);border-radius:4px">' + esc(data.summary) + '</div>';
      }
      html += '</div>';
      totalScore += catScore;
      totalDims += catDims;
    });

    var overallAvg = totalDims > 0 ? (totalScore / totalDims).toFixed(1) : 0;
    html = html.replace('</h3>', ' — 总均分 <b>' + overallAvg + '</b></h3>');

    if (totalIssues > 0) {
      html += '<div style="margin:10px 0;padding:8px 12px;background:rgba(255,152,0,0.1);border-radius:6px;font-size:13px">';
      html += '⚠️ 发现 <b>' + totalIssues + '</b> 个低分项（≤4分），建议在写正文前优先改进</div>';
    } else {
      html += '<div style="margin:10px 0;padding:8px 12px;background:rgba(76,175,80,0.1);border-radius:6px;font-size:13px">';
      html += '✅ 全部维度均分≥5，可以开始写正文了！</div>';
    }

    html += '</div>';
    contentDiv.innerHTML = html;
    panel.style.display = 'block';
  }

  return {
    init: init, togglePanel: togglePanel, close: close,
    loadResults: loadResults, renderPanel: renderPanel,
    toggleChapter: toggleChapter, aiFix: aiFix,
    confirmFix: confirmFix, closeFixResult: closeFixResult, ignore: ignore,
    fixAll: fixAll, showCheckResult: showCheckResult, confirmFixAll: confirmFixAll,
    showProjectReview: showProjectReview
  };
})();

document.addEventListener('DOMContentLoaded', function() { CheckPanel.init(); });


// ── js/modules/toolbox.js ──
// Extracted from app.js - 工具箱8大面板 (导出/导入/快照对比/角色对话/同步/模板/批量检查/统计)
function closeOverlay(id) {
  var el = document.getElementById(id);
  if (el) el.style.display = 'none';
}

// 通用：清除AI编辑批注（与后端 _strip_edit_annotations 规则保持一致）
// 注意：此处规则必须与 backend/routers/chapter.py 中的 _strip_edit_annotations 完全对齐
function _stripEditAnnotations(text) {
  if (!text) return text;
  // 1. Markdown标题行（#### 问题5的确认 等）——正常小说正文不会用#标题
  text = text.replace(/^#{1,6}\s+[^\n]*\n?/gm, '');
  // 2. Markdown分隔线（---）单独成行
  text = text.replace(/^---+\s*\n/gm, '');
  // 3. 行首批注：**修改建议：** / **编辑注：** 等
  text = text.replace(/^\*\*[^*]+[：:]\*\*\s*.*$/gm, '');
  // 4. 行首孤立**片段（如 **了。 或 **某词）
  text = text.replace(/^\*\*[^*\n]{0,50}\n?/gm, '');
  // 5. 【文字】格式的编辑标记行
  text = text.replace(/^【[^】\n]{2,30}】[：:]?[^\n]*\n?/gm, '');
  // 6. 方括号批注：[编辑：...] / [修改：...] / [建议：...] / [批注：...] / [评审：...] / [纠错：...] / [润色：...]
  text = text.replace(/\[[编辑修改建议批注评审纠错润色][：:].*?\]/g, '');
  // 7. 花括号批注：{编辑：...}
  text = text.replace(/\{编辑[：:].*?\}/g, '');
  // 8. 独立行以 箭头→/➜/✏️/📝/🔧 开头的修改指示
  text = text.replace(/^(?:→|➜|✏️|📝|🔧)\s*.+$/gm, '');
  // 9. 内联编辑指令："在第2章末尾，增加一句..."等（AI修复可能将指令混入正文）
  text = text.replace(/在第\d+章(?:末尾|开头|中间|前|后|中)?[，,][^。\n]*?[。]\s*/g, '');
  // 10. 清除多余空行
  text = text.replace(/\n{3,}/g, '\n\n');
  return text.trim();
}

// 工具箱下拉菜单
function toggleToolbox(e) {
  if (e) e.stopPropagation();
  var dd = document.getElementById('toolbox-dropdown');
  if (dd) dd.style.display = (dd.style.display === 'none') ? 'block' : 'none';
}
document.addEventListener('click', function(e) {
  var dd = document.getElementById('toolbox-dropdown');
  if (dd && dd.style.display === 'block' && !e.target.closest('#toolbox-dropdown') && !e.target.closest('button[onclick^="toggleToolbox"]')) {
    dd.style.display = 'none';
  }
});

// 在 APK/WebView 中打开应用内页面（避免 window.open('_blank') 被拦截）
function openToolboxPage(url) {
  var dd = document.getElementById('toolbox-dropdown');
  if (dd) dd.style.display = 'none';
  if (typeof Capacitor !== 'undefined' && Capacitor.isNative) {
    window.location.href = url;
  } else {
    window.location.href = url;
  }
}

