var _cmdSelectedIndex = 0;
var _cmdFilteredList = [];

// 初始化命令面板
function initCommandPalette() {
  var overlay = document.getElementById('cmd-palette-overlay');
  var input = document.getElementById('cmd-input');
  var list = document.getElementById('cmd-list');
  if (!overlay || !input || !list) return;

  // 输入实时过滤
  input.addEventListener('input', function() {
    _renderCommandList(input.value);
  });

  // 键盘导航
  input.addEventListener('keydown', function(e) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      _cmdSelectedIndex = Math.min(_cmdSelectedIndex + 1, _cmdFilteredList.length - 1);
      _updateCommandSelection();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      _cmdSelectedIndex = Math.max(_cmdSelectedIndex - 1, 0);
      _updateCommandSelection();
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (_cmdFilteredList[_cmdSelectedIndex]) {
        var cmd = _cmdFilteredList[_cmdSelectedIndex];
        closeCommandPalette();
        try { cmd.run(); } catch (err) { console.error('[CmdPalette]', err); }
      }
    } else if (e.key === 'Escape') {
      e.preventDefault();
      closeCommandPalette();
    }
  });

  // 点击遮罩关闭
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) closeCommandPalette();
  });
}

// 打开命令面板
function openCommandPalette() {
  var overlay = document.getElementById('cmd-palette-overlay');
  var input = document.getElementById('cmd-input');
  if (!overlay || !input) return;
  overlay.style.display = 'flex';
  input.value = '';
  _renderCommandList('');
  setTimeout(function() { input.focus(); }, 50);
}

// 关闭命令面板
function closeCommandPalette() {
  var overlay = document.getElementById('cmd-palette-overlay');
  if (overlay) overlay.style.display = 'none';
}

// 渲染命令列表（支持过滤）
function _renderCommandList(query) {
  var list = document.getElementById('cmd-list');
  var countEl = document.getElementById('cmd-count');
  if (!list) return;
  var all = _getCommandList();
  query = (query || '').trim().toLowerCase();
  if (query) {
    _cmdFilteredList = all.filter(function(c) {
      var name = (c.name || '').toLowerCase();
      var kw = (c.keywords || '').toLowerCase();
      return name.indexOf(query) >= 0 || kw.indexOf(query) >= 0;
    });
  } else {
    _cmdFilteredList = all.slice();
  }
  _cmdSelectedIndex = 0;
  if (countEl) countEl.textContent = _cmdFilteredList.length;
  if (_cmdFilteredList.length === 0) {
    list.innerHTML = '<div style="text-align:center;color:var(--muted);padding:24px;font-size:12px">无匹配命令</div>';
    return;
  }
  list.innerHTML = _cmdFilteredList.map(function(c, i) {
    var active = i === 0;
    return '<div class="cmd-item" data-idx="' + i + '" onclick="_selectCommand(' + i + ')" style="padding:9px 12px;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:8px;border-radius:var(--radius-sm);' + (active ? 'background:var(--accent-soft, rgba(199,91,57,0.15));color:var(--accent)' : 'color:var(--text)') + '">'
      + '<span style="font-size:14px">' + (c.icon || '›') + '</span>'
      + '<span>' + c.name + '</span>'
      + '</div>';
  }).join('');
}

// 更新选中项样式
function _updateCommandSelection() {
  var items = document.querySelectorAll('.cmd-item');
  items.forEach(function(el, i) {
    var active = i === _cmdSelectedIndex;
    el.style.background = active ? 'var(--accent-soft, rgba(199,91,57,0.15))' : 'transparent';
    el.style.color = active ? 'var(--accent)' : 'var(--text)';
  });
  // 滚动到可见
  var sel = items[_cmdSelectedIndex];
  if (sel && sel.scrollIntoView) {
    var container = sel.parentElement;
    var cRect = container.getBoundingClientRect();
    var sRect = sel.getBoundingClientRect();
    if (sRect.top < cRect.top || sRect.bottom > cRect.bottom) {
      sel.scrollIntoView({block: 'nearest'});
    }
  }
}

// 鼠标点击选择命令
function _selectCommand(idx) {
  _cmdSelectedIndex = idx;
  if (_cmdFilteredList[idx]) {
    var cmd = _cmdFilteredList[idx];
    closeCommandPalette();
    try { cmd.run(); } catch (err) { console.error('[CmdPalette]', err); }
  }
}

// 注册全局快捷键 Ctrl+P / Ctrl+K
document.addEventListener('keydown', function(e) {
  // Ctrl+P 或 Ctrl+K 打开命令面板（阻止浏览器默认行为）
  if ((e.ctrlKey || e.metaKey) && (e.key === 'p' || e.key === 'P' || e.key === 'k' || e.key === 'K')) {
    e.preventDefault();
    e.stopPropagation();
    var overlay = document.getElementById('cmd-palette-overlay');
    if (overlay && overlay.style.display === 'flex') {
      closeCommandPalette();
    } else {
      openCommandPalette();
    }
    return false;
  }
});

// 页面加载完成后初始化命令面板
document.addEventListener('DOMContentLoaded', function() {
  initCommandPalette();
});
// 兜底：若 DOMContentLoaded 已触发，立即初始化
if (document.readyState !== 'loading') {
  initCommandPalette();
}

// ═══════════════════════════════════════════════════════════════════════
// 6.7 事件审计链（前端面板 + auditLog 记录函数）
// ═══════════════════════════════════════════════════════════════════════

// 记录一条审计事件（调用后端 POST /api/audit-log/log）
async function auditLog(action, target, detail) {
  try {
    await api('/api/audit-log/log', {
      method: 'POST',
      body: JSON.stringify({action: action, target: target || '', detail: detail || ''})
    });
  } catch (e) {
    // 审计日志失败不应影响主流程，仅打印日志
    console.warn('[AuditLog] 记录失败:', e);
  }
}

// 打开审计日志面板
function openAuditLogPanel() {
  var dd = document.getElementById('toolbox-dropdown');
  if (dd) dd.style.display = 'none';
  if (!document.getElementById('audit-log-overlay')) {
    var overlay = document.createElement('div');
    overlay.id = 'audit-log-overlay';
    overlay.className = 'overlay-backdrop';
    overlay.style.cssText = 'display:flex;z-index:1200';
    overlay.innerHTML = ''
      + '<div style="position:relative;z-index:1201;width:92%;max-width:760px;height:85vh;background:var(--bg);border:1px solid var(--border);border-radius:var(--radius-md);box-shadow:0 12px 48px rgba(0,0,0,0.5);display:flex;flex-direction:column;overflow:hidden">'
      + '  <div class="row-between-lg">'
      + '    <div class="flex-center-sm"><span class="text-xl">📋</span><span class="title-accent-md-xl">事件审计日志</span><span style="font-size:11px;color:var(--muted);background:var(--bg);padding:2px 8px;border-radius:10px" id="audit-log-total">0</span></div>'
      + '    <div class="flex-row-xs">'
      + '      <button onclick="loadAuditLogList(50)" style="padding:4px 12px;font-size:12px;background:var(--surface);border:1px solid var(--border);border-radius:4px;cursor:pointer;color:var(--text)">刷新</button>'
      + '      <button onclick="closeOverlay(\'audit-log-overlay\')" class="btn-ghost-icon-xl-alt">✕</button>'
      + '    </div>'
      + '  </div>'
      + '  <div id="audit-log-stats" style="padding:10px 14px;border-bottom:1px solid var(--border);background:var(--bg);display:flex;flex-wrap:wrap;gap:6px"></div>'
      + '  <div id="audit-log-list" style="flex:1;overflow-y:auto;padding:10px"></div>'
      + '</div>';
    document.body.appendChild(overlay);
  } else {
    document.getElementById('audit-log-overlay').style.display = 'flex';
  }
  loadAuditLogList(50);
  loadAuditLogStats();
}

// 加载审计日志列表
async function loadAuditLogList(limit) {
  limit = limit || 50;
  var listEl = document.getElementById('audit-log-list');
  var totalEl = document.getElementById('audit-log-total');
  if (!listEl) return;
  listEl.innerHTML = '<div class="empty-state-sm-alt">⏳ 加载中...</div>';
  try {
    var r = await api('/api/audit-log/list?limit=' + limit);
    if (!r.ok) {
      listEl.innerHTML = '<div style="text-align:center;color:var(--danger);padding:30px;font-size:13px">❌ 加载失败: ' + (r.error || '').replace(/</g, '&lt;') + '</div>';
      return;
    }
    var logs = r.logs || [];
    if (totalEl) totalEl.textContent = r.total || logs.length;
    if (logs.length === 0) {
      listEl.innerHTML = '<div style="text-align:center;color:var(--muted);padding:40px;font-size:13px">📝 暂无审计记录<br><span class="text-sm">执行生成正文、保存章节、去AI味等操作后将自动记录</span></div>';
      return;
    }
    // action 类型对应的颜色和图标
    var actionStyles = {
      generate: {icon: '✨', color: 'var(--accent)'},
      save: {icon: '💾', color: 'var(--success, #10b981)'},
      deai: {icon: '🔧', color: '#e74c3c'},
      continue: {icon: '✍️', color: 'var(--warn)'},
      export: {icon: '📥', color: '#9b59b6'},
      add_chapter: {icon: '➕', color: '#3498db'},
      brainstorm: {icon: '🧠', color: 'var(--accent)'},
    };
    listEl.innerHTML = logs.map(function(item) {
      var st = actionStyles[item.action] || {icon: '•', color: 'var(--muted)'};
      return '<div style="display:flex;gap:10px;padding:10px 12px;border-bottom:1px solid var(--border-soft);font-size:12px">'
        + '<span style="font-size:14px;flex-shrink:0">' + st.icon + '</span>'
        + '<div style="flex:1;min-width:0">'
        + '  <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">'
        + '    <span style="color:' + st.color + ';font-weight:600">' + (item.action || '').replace(/</g, '&lt;') + '</span>'
        + '    <span class="text-ink">' + (item.target || '').replace(/</g, '&lt;') + '</span>'
        + '    <span style="color:var(--muted);font-size:10px;margin-left:auto;flex-shrink:0">' + (item.ts || '').replace(/</g, '&lt;') + '</span>'
        + '  </div>'
        + (item.detail ? '<div style="color:var(--muted);font-size:11px;margin-top:3px">' + item.detail.replace(/</g, '&lt;') + '</div>' : '')
        + '</div>';
    }).join('');
  } catch (e) {
    listEl.innerHTML = '<div style="text-align:center;color:var(--danger);padding:30px;font-size:13px">❌ 加载出错: ' + (e.message || '').replace(/</g, '&lt;') + '</div>';
  }
}

// 加载审计日志统计
async function loadAuditLogStats() {
  var statsEl = document.getElementById('audit-log-stats');
  if (!statsEl) return;
  try {
    var r = await api('/api/audit-log/stats');
    if (!r.ok) { statsEl.textContent = ''; return; }
    var stats = r.stats || {};
    var keys = Object.keys(stats);
    if (keys.length === 0) {
      statsEl.innerHTML = '<span class="text-sm text-muted">暂无统计数据</span>';
      return;
    }
    var actionLabels = {
      generate: '生成', save: '保存', deai: '去AI味', continue: '续写',
      export: '导出', add_chapter: '添加章节', brainstorm: '头脑风暴'
    };
    statsEl.innerHTML = keys.map(function(k) {
      var label = actionLabels[k] || k;
      return '<span style="font-size:11px;padding:3px 10px;background:var(--surface);border:1px solid var(--border);border-radius:10px;color:var(--text)">' + label + ' <span style="color:var(--accent);font-weight:600">' + stats[k] + '</span></span>';
    }).join('');
  } catch (e) {
    statsEl.textContent = '';
  }
}



// ── js/modules/operation-context.js ──
/**
 * OperationContext - 操作上下文管理器
 * 借鉴既有并发控制设计模式：
 *   1. 操作开始时锁定目标章节索引，贯穿整个异步操作链
 *   2. 所有保存操作必须使用锁定的索引，禁止读取全局 currentChapterIndex
 *   3. 操作进行中禁止切章（或提供冲突检测）
 *
 * 核心思想：消灭全局可变状态带来的竞态风险
 */

;(function(global) {
  'use strict';

  // 当前活跃的操作上下文栈（支持嵌套，但同一时间只有一个活跃写操作）
  var _activeContext = null;

  /**
   * 创建操作上下文 — 在异步操作开始时调用
   * @param {Object} opts
   * @param {number} opts.chapterIndex - 锁定的目标章节索引（不可变）
   * @param {string} opts.operation - 操作描述（如 "AI修复"、"生成正文"）
   * @param {Function} opts.onConflict - 可选：切章冲突回调
   * @returns {Object} 上下文对象 { chapterIndex, operation, isAlive, release }
   */
  function createOperationContext(opts) {
    var ctx = {
      chapterIndex: opts.chapterIndex,     // 锁定的章节索引 — 不可变
      operation: opts.operation || '未知操作',
      isAlive: true,                       // 操作是否仍在进行
      createdAt: Date.now(),
      onConflict: opts.onConflict || null
    };

    // 如果已有活跃上下文，记录警告
    if (_activeContext && _activeContext.isAlive) {
      console.warn('[OperationContext] 覆盖活跃上下文:', _activeContext.operation, '→', ctx.operation);
    }

    _activeContext = ctx;
    console.log('[OperationContext] 创建:', ctx.operation, '目标章节:', ctx.chapterIndex + 1);

    return ctx;
  }

  /**
   * 释放操作上下文 — 在异步操作完成时调用（无论成功或失败）
   */
  function releaseOperationContext(ctx) {
    if (!ctx) return;
    ctx.isAlive = false;
    if (_activeContext === ctx) {
      _activeContext = null;
      console.log('[OperationContext] 释放:', ctx.operation);
    }
  }

  /**
   * 获取当前活跃的操作上下文
   */
  function getActiveContext() {
    return _activeContext;
  }

  /**
   * 获取安全的章节索引 — 优先使用操作上下文的锁定值
   * 这是对所有异步操作的统一出口：
   *   - 如果有活跃上下文，返回锁定的索引
   *   - 否则返回 currentChapterIndex（同步操作场景）
   */
  function safeChapterIndex(fallbackIndex) {
    if (_activeContext && _activeContext.isAlive) {
      return _activeContext.chapterIndex;
    }
    return fallbackIndex !== undefined ? fallbackIndex : (typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0);
  }

  /**
   * 切章冲突检测 — 在切章操作前调用
   * 如果有活跃的异步写操作，返回 true（表示应该阻止切章或提醒用户）
   */
  function hasActiveWriteOperation() {
    return _activeContext && _activeContext.isAlive;
  }

  /**
   * 带上下文的异步操作包装器 — 简化用法
   * 自动创建/释放上下文，确保操作链中使用锁定的章节索引
   *
   * 用法：
   *   await withChapterContext(chapterIndex, 'AI修复', async function(ctx) {
   *     // 在这里进行耗时操作...
   *     // 保存时使用 ctx.chapterIndex 而非 currentChapterIndex
   *     await saveChapter(ctx.chapterIndex, content);
   *   });
   */
  async function withChapterContext(chapterIndex, operation, asyncFn) {
    var ctx = createOperationContext({ chapterIndex: chapterIndex, operation: operation });
    try {
      return await asyncFn(ctx);
    } catch (e) {
      console.error('[OperationContext] 操作异常:', operation, e);
      throw e;
    } finally {
      releaseOperationContext(ctx);
    }
  }

  // 导出
  global.OperationContext = {
    create: createOperationContext,
    release: releaseOperationContext,
    getActive: getActiveContext,
    safeIndex: safeChapterIndex,
    hasActiveWrite: hasActiveWriteOperation,
    withChapter: withChapterContext
  };

})(window);


// ── js/modules/mobile.js ──
// Extracted from app.js - 移动端优化 (滑动手势+虚拟键盘适配+底部工具栏)
// ═══════════════════════════════════════════
// 移动端优化：滑动手势 + 虚拟键盘适配 + 底部工具栏
// ═══════════════════════════════════════════

(function() {
  var isMobile = document.body.classList.contains('mobile-mode') || window.innerWidth <= 768 || /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
  if (!isMobile) return;

  // ── 1. 滑动手势 ──
  var touchStartX = 0, touchStartY = 0, touchEndX = 0, touchEndY = 0, touchStartTime = 0;
  var isSwiping = false;

  document.addEventListener('touchstart', function(e) {
    if (e.touches.length !== 1) return;
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
    touchStartTime = Date.now();
    isSwiping = false;
  }, { passive: true });

  document.addEventListener('touchmove', function(e) {
    if (e.touches.length !== 1) return;
    var dx = e.touches[0].clientX - touchStartX;
    var dy = e.touches[0].clientY - touchStartY;
    if (Math.abs(dx) > 20 && Math.abs(dx) > Math.abs(dy) * 1.5) {
      isSwiping = true;
    }
  }, { passive: true });

  document.addEventListener('touchend', function(e) {
    if (!isSwiping) return;
    touchEndX = e.changedTouches[0].clientX;
    touchEndY = e.changedTouches[0].clientY;
    var dx = touchEndX - touchStartX;
    var dy = touchEndY - touchStartY;
    var dt = Date.now() - touchStartTime;

    // 快速横向滑动（<500ms，水平位移>60px，垂直位移<80px）
    if (dt < 500 && Math.abs(dx) > 60 && Math.abs(dy) < 80) {
      var target = e.target;
      // 在输入框/textarea/AI面板中不触发
      if (target && (target.tagName === 'TEXTAREA' || target.tagName === 'INPUT' || target.closest('#ai-assistant-panel') || target.closest('.suggestion-panel'))) return;

      var leftDrawer = document.querySelector('.left-drawer');
      var rightDrawer = document.querySelector('.right-drawer');

      if (dx > 0) {
        // 右滑：打开左抽屉 或 关闭右抽屉
        if (rightDrawer && rightDrawer.classList.contains('collapsed') === false && !rightDrawer.classList.contains('hidden')) {
          rightDrawer.classList.add('collapsed');
          updateOverlay();
        } else if (leftDrawer && leftDrawer.classList.contains('collapsed')) {
          leftDrawer.classList.remove('collapsed');
          updateOverlay();
        }
      } else {
        // 左滑：关闭左抽屉 或 打开右抽屉
        if (leftDrawer && leftDrawer.classList.contains('collapsed') === false) {
          leftDrawer.classList.add('collapsed');
          updateOverlay();
        } else if (rightDrawer && rightDrawer.classList.contains('collapsed')) {
          rightDrawer.classList.remove('collapsed');
          updateOverlay();
        }
      }
    }
    isSwiping = false;
  }, { passive: true });

  // ── 2. 虚拟键盘适配 ──
  var originalHeight = window.innerHeight;
  window.addEventListener('resize', function() {
    var newHeight = window.innerHeight;
    var heightDiff = originalHeight - newHeight;
    // 键盘弹出（高度减少>150px）
    if (heightDiff > 150) {
      document.body.classList.add('keyboard-open');
      // 聚焦的元素滚动到可视区
      var focused = document.activeElement;
      if (focused && (focused.tagName === 'TEXTAREA' || focused.tagName === 'INPUT')) {
        setTimeout(function() {
          focused.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 300);
      }
    } else {
      document.body.classList.remove('keyboard-open');
    }
    originalHeight = newHeight;
  });

  // AI助手输入框虚拟键盘适配
  var aiInput = document.getElementById('assistant-input');
  if (aiInput) {
    aiInput.addEventListener('focus', function() {
      var panel = document.getElementById('ai-assistant-panel');
      if (panel) {
        panel.style.height = window.innerHeight + 'px';
        panel.style.height = '100vh';
      }
    });
    aiInput.addEventListener('blur', function() {
      setTimeout(function() {
        var panel = document.getElementById('ai-assistant-panel');
        if (panel) panel.style.height = '';
      }, 100);
    });
  }

  // ── 辅助函数：更新遮罩层 ──
  function updateOverlay() {
    var overlay = document.getElementById('drawer-overlay');
    var leftDrawer = document.querySelector('.left-drawer');
    var rightDrawer = document.querySelector('.right-drawer');
    if (!overlay) return;
    var leftOpen = leftDrawer && !leftDrawer.classList.contains('collapsed');
    var rightOpen = rightDrawer && !rightDrawer.classList.contains('collapsed');
    if (leftOpen || rightOpen) {
      overlay.classList.add('visible');
    } else {
      overlay.classList.remove('visible');
    }
  }

  // ── 3. 底部工具栏：使用桌面端原生bottombar（水平滚动），不再覆盖自定义工具栏 ──
  // 确保桌面端bottombar在移动端可见，通过CSS处理水平滚动

  // ── 4. 双指缩放禁用（避免误触放大）但保留输入框缩放 ──
  document.addEventListener('gesturestart', function(e) {
    if (!e.target || (e.target.tagName !== 'INPUT' && e.target.tagName !== 'TEXTAREA')) {
      e.preventDefault();
    }
  });

  // ── 5. 长按选词优化 ──
  document.addEventListener('touchstart', function(e) {
    // 编辑器中长按选词，不影响
    if (e.target && e.target.closest && e.target.closest('.editor-paper')) {
      return;
    }
    // 其他区域长按禁止弹出系统菜单
    if (e.target && e.target.tagName !== 'INPUT' && e.target.tagName !== 'TEXTAREA') {
      e.target.style.webkitTouchCallout = 'none';
    }
  }, { passive: true });

  // ── 6. 移动端顶部栏项目按钮优化 ──
  // 确保新建/打开项目按钮在移动端有正确的触摸区域
  var btnNew = document.getElementById('btn-new-project');
  var btnOpen = document.getElementById('btn-open-project');
  if (btnNew) {
    btnNew.addEventListener('touchstart', function() { btnNew.style.background = 'rgba(255,255,255,0.08)'; }, { passive: true });
    btnNew.addEventListener('touchend', function() { btnNew.style.background = ''; }, { passive: true });
  }
  if (btnOpen) {
    btnOpen.addEventListener('touchstart', function() { btnOpen.style.background = 'rgba(255,255,255,0.08)'; }, { passive: true });
    btnOpen.addEventListener('touchend', function() { btnOpen.style.background = ''; }, { passive: true });
  }

  console.log('[Mobile] 移动端优化已加载：滑动手势+虚拟键盘适配+底部工具栏+项目按钮');
})();


