            if (bp2.climax) bpParts.push('【转】' + (bp2.climax.conflict||'') + ' — ' + (bp2.climax.twist||''));
            if (bp2.ending) bpParts.push('【合】' + (bp2.ending.new_state||'') + ' → ' + (bp2.ending.next_hook||''));
            outlineText = bpParts.join('\n');
