// ── js/glue-settings.js ──
(function() {
  'use strict';


// ══ 结构化世界观字段 ══
var worldMeta = { narrative_style: {}, era: {}, world_rules: [] };

window.loadWorldMeta = function(data) {
  worldMeta.narrative_style = (data && data.narrative_style) || {};
  worldMeta.era = (data && data.era) || {};
  worldMeta.world_rules = (data && data.world_rules) || [];
  renderWorldMeta();
}

window.renderWorldMeta = function() {
  var ns = worldMeta.narrative_style;
  var era = worldMeta.era;
  // 填充叙事风格
  if (document.getElementById('ns-pov')) document.getElementById('ns-pov').value = ns.pov || '';
  if (document.getElementById('ns-tense')) document.getElementById('ns-tense').value = ns.tense || '';
  if (document.getElementById('ns-tone')) document.getElementById('ns-tone').value = ns.tone || '';
  if (document.getElementById('ns-pacing')) document.getElementById('ns-pacing').value = ns.pacing || '';
  if (document.getElementById('ns-description')) document.getElementById('ns-description').value = ns.description_style || '';
  // 填充时代环境
  if (document.getElementById('era-tech')) document.getElementById('era-tech').value = era.tech_level || '';
  if (document.getElementById('era-society')) document.getElementById('era-society').value = era.society || '';
  if (document.getElementById('era-geography')) document.getElementById('era-geography').value = era.geography || '';
  if (document.getElementById('era-culture')) document.getElementById('era-culture').value = era.culture || '';
  if (document.getElementById('era-social-attitude')) document.getElementById('era-social-attitude').value = era.social_attitude || '';
  // 渲染世界规则列表
  renderWorldRules();
}

window.renderWorldRules = function() {
  var list = document.getElementById('world-rules-list');
  if (!list) return;
  list.innerHTML = '';
  if (!worldMeta.world_rules || worldMeta.world_rules.length === 0) {
    list.innerHTML = '<div class="label-muted-inline-sm" >暂无世界规则，点击添加</div>';
    return;
  }
  worldMeta.world_rules.forEach(function(rule, i) {
    var row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:4px;align-items:center';
    row.innerHTML = '<input type="text" value="' + escapeHtml(rule) + '" onchange="updateWorldRule(' + i + ', this.value)" style="flex:1;padding:4px 8px;font-size:12px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--ink)">' +
      '<button onclick="removeWorldRule(' + i + ')" style="padding:4px 6px;border:1px solid #e74c3c;color:#e74c3c;background:transparent;border-radius:4px;cursor:pointer;font-size:11px">✕</button>';
    list.appendChild(row);
  });
}

window.addWorldRule = function() {
  if (!worldMeta.world_rules) worldMeta.world_rules = [];
  worldMeta.world_rules.push('新规则');
  renderWorldRules();
  saveWorldMeta();
}

window.updateWorldRule = function(i, val) {
  worldMeta.world_rules[i] = val;
  saveWorldMeta();
}

window.removeWorldRule = function(i) {
  worldMeta.world_rules.splice(i, 1);
  renderWorldRules();
  saveWorldMeta();
}

window.saveWorldMeta = async function(opts) {
  opts = opts || {};
  // 从UI收集值
  var ns = {
    pov: val('ns-pov'), tense: val('ns-tense'), tone: val('ns-tone'),
    pacing: val('ns-pacing'), description_style: val('ns-description')
  };
  var era = {
    tech_level: val('era-tech'), society: val('era-society'),
    geography: val('era-geography'), culture: val('era-culture'),
    social_attitude: val('era-social-attitude')
  };
  worldMeta.narrative_style = ns;
  worldMeta.era = era;
  // 保存到后端（只发送结构化字段，不碰 world_settings，避免时序问题覆盖设定）
  try {
    var payload = {
      narrative_style: ns,
      era: era,
      world_rules: worldMeta.world_rules
    };
    // 仅在显式传入 includeWorldSettings 时才发送 world_settings
    if (opts.includeWorldSettings === true && typeof worldSettings !== 'undefined' && Array.isArray(worldSettings)) {
      var d = {};
      worldSettings.forEach(function(s) { if (s && s.key) d[s.key] = s.val || ''; });
      payload.world_settings = d;
    }
    await api('/api/project/settings', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify(payload)
    });
  } catch(e) { console.warn('saveWorldMeta failed:', e); }
}

})();

// ── js/glue-init.js ──
(function() {
  'use strict';


window.goToStep = async function(step) {
  if (step < 1 || step > TOTAL_STEPS) return;

  // ═══ 阶段一7：步骤顺序强制校验 ═══
  // 进入写作、时间线、草稿定稿前，必须先完成连线框的布局
  // —— 不能允许跳过连线框直接写正文或定稿，这是因果链检查的核心卡口
  var _REQUIRE_WIREFRAME_BEFORE = [STEPS.写作, STEPS.时间线, STEPS.草稿定稿];
  if (_REQUIRE_WIREFRAME_BEFORE.indexOf(step) >= 0 && typeof api === 'function') {
    var _pc_ok = null;
    // 优先用缓存（最新一次拉取结果）
    if (window._workflowStepCache && typeof window._workflowStepCache.planning_cards_ready === 'boolean') {
      _pc_ok = window._workflowStepCache.planning_cards_ready;
    }
    if (_pc_ok === null) {
      try {
        var _st = await api('/api/project/workflow-step-status', {method: 'GET'});
        if (_st && _st.ok && _st.data) {
          window._workflowStepCache = _st.data;
          _pc_ok = !!_st.data.planning_cards_ready;
        }
      } catch(e) { console.warn('[goToStep] 拉取步骤状态失败，保守放行：', e); _pc_ok = true; }
    }
    if (_pc_ok === false) {
      var _whichName = STEPS._nameOf[step] || step;
      showToast('⚠️ 进入「' + _whichName + '」前必须先完成「连线框」的画布布局（至少拖入1张卡片），已为您自动跳转到连线框。', 'warning', 10000);
      // 强制拦回连线框（不能允许跳过）
      step = STEPS.连线框;
    }
  }

  // 离开当前步骤时，强制保存对应数据（避免编辑内容丢失）
  if (currentWorkflowStep !== step) {
    if (currentWorkflowStep === STEPS.世界观) {
      // 如果AI提取文本框有内容，先自动触发AI提取
      var extractInput = document.getElementById('ai-extract-input');
      if (extractInput && extractInput.value.trim()) {
        console.log('[工作流] 离开步骤1，检测到AI提取输入框有内容，自动触发提取...');
        try {
          var extractData = await api('/api/ai/analyze-content', {
            method: 'POST',
            body: JSON.stringify({ content: extractInput.value.trim() })
          });
          if (extractData && extractData.ok && extractData.settings) {
            var extracted = [];
            Object.entries(extractData.settings).forEach(function([key, val]) {
              if (val && typeof val === 'string') {
                extracted.push({key: key, val: val, group: '世界观'});
              }
            });
            if (extracted.length >= 1 && typeof worldSettings !== 'undefined') {
              var existingKeys = {};
              worldSettings.forEach(function(s) { existingKeys[s.key + '|' + s.group] = true; });
              extracted.forEach(function(item) {
                var k = item.key + '|' + item.group;
                if (!existingKeys[k]) { worldSettings.push(item); existingKeys[k] = true; }
              });
            }
            if (typeof renderSettingsEditor === 'function') renderSettingsEditor();
            showToast('AI自动提取完成，已提取 ' + extracted.length + ' 项设定');
          }
        } catch(e) { console.warn('[工作流] AI自动提取失败:', e); }
      }
      // 保存世界观设定
      if (typeof saveWorldMeta === 'function') {
        await saveWorldMeta();
      }
    }
    if (currentWorkflowStep === STEPS.章节大纲 && typeof saveChapterOutline === 'function' && typeof chOutline !== 'undefined') {
      try { await saveChapterOutline(true); } catch(e) { console.warn('save outline on leave step5:', e); }
    }
    // ═══ 章节大纲→写作时：检查当前卷大纲是否全部完成，触发30维全书检查 ═══
    if (currentWorkflowStep === STEPS.章节大纲 && step >= STEPS.写作) {
      (function() {
        // 检查当前卷的章节是否都有大纲
        var allHaveOutline = true;
        var currentVolChapters = [];
        try {
          if (typeof volumes !== 'undefined' && volumes && volumes.length > 0) {
            // 找到当前章节所在的卷
            var chNum = (typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0) + 1;
            var curVol = null;
            for (var vi = 0; vi < volumes.length; vi++) {
              var vc = volumes[vi].chapters || [];
              if (vc.indexOf(chNum) >= 0 || (vc.length && vc[0] <= chNum && chNum <= vc[vc.length-1])) {
                curVol = volumes[vi]; break;
              }
            }
            if (curVol) {
              var volChapters = curVol.chapters || [];
              for (var ci = 0; ci < volChapters.length; ci++) {
                var chIdx = volChapters[ci] - 1;
                if (chIdx >= 0 && typeof chapters !== 'undefined' && chapters[chIdx]) {
                  var hasOl = chapters[chIdx].blueprint || chapters[chIdx].outline;
                  if (!hasOl) { allHaveOutline = false; break; }
                }
              }
            } else {
              // 没有卷结构，检查所有章节
              if (typeof chapters !== 'undefined' && chapters) {
                for (var ci2 = 0; ci2 < chapters.length; ci2++) {
                  if (!chapters[ci2].blueprint && !chapters[ci2].outline) { allHaveOutline = false; break; }
                }
              }
            }
          } else {
            // 没有卷数据，检查所有章节
            if (typeof chapters !== 'undefined' && chapters) {
              for (var ci3 = 0; ci3 < chapters.length; ci3++) {
                if (!chapters[ci3].blueprint && !chapters[ci3].outline) { allHaveOutline = false; break; }
              }
            }
          }
        } catch(e) { console.warn('[工作流] 检查大纲完成状态失败:', e); }

        if (allHaveOutline && typeof chapters !== 'undefined' && chapters && chapters.length > 0) {
          console.log('[工作流] 章节大纲已全部完成，自动触发30维全书检查...');
          showToast('📊 章节大纲已完成，正在自动进行30维全书检查...');
          api('/api/validate/project-review', {
            method: 'POST',
            body: JSON.stringify({})
          }).then(function(reviewResult) {
            if (reviewResult && reviewResult.ok) {
              window._lastProjectReview = reviewResult;
              var issueCount = 0;
              var cats = ['outline_quality', 'settings_quality', 'characters_quality'];
              var catNames = {outline_quality: '大纲', settings_quality: '设定', characters_quality: '人物'};
              var parts = [];
              cats.forEach(function(cat) {
                if (reviewResult[cat] && reviewResult[cat].dimensions) {
                  var total = 0, cnt = 0;
                  reviewResult[cat].dimensions.forEach(function(dim) {
                    total += (dim.score || 0); cnt++;
                    if ((dim.score || 5) <= 4) issueCount++;
                  });
                  parts.push(catNames[cat] + ':' + (cnt > 0 ? (total/cnt).toFixed(1) : 0) + '分');
                }
              });
              if (issueCount > 0) {
                showToast('30维检查完成，发现 ' + issueCount + ' 个低分项，' + parts.join(' | '), 'warning', 8000);
              } else {
                showToast('30维检查完成！' + parts.join(' | '), 'success', 5000);
              }
              if (typeof CheckPanel !== 'undefined' && CheckPanel.showProjectReview) {
                CheckPanel.showProjectReview(reviewResult);
              }
            }
          }).catch(function(e) { console.warn('[工作流] 30维检查失败:', e); });
        }
      })();
    }
    if (currentWorkflowStep === STEPS.写作) {
      // 离开步骤6时，currentChapterIndex 可能已被其他流程提前修改（如生成下一章大纲），
      // 直接使用全局变量会导致旧章节正文串写到新章节。这里显式记录旧的索引。
      // P0: 如果 _skipAutoSaveOnLeaveStep6 标志为 true，说明 generateNextChapterOutline 已自行保存，
      // 跳过自动保存以避免把旧章节正文串写到新章节
      if (window._skipAutoSaveOnLeaveStep6) {
        console.log('[goToStep] 跳过步骤6自动保存（generateNextChapterOutline 已处理）');
      } else {
        var leavingIdx = currentChapterIndex;
        try {
          var leavingEd = document.getElementById('editor-content');
          var leavingContent = leavingEd ? (leavingEd.innerText || '') : '';
          if (leavingIdx >= 0 && chapters && chapters[leavingIdx] && leavingContent.trim()) {
            await saveChapter(leavingIdx, leavingContent);
            chapters[leavingIdx].content = leavingContent;
          }
        } catch(e) { console.warn('autoSave on leave step6 failed:', e); }
      }
    }
  }
  // ═══ E连线框UI引导：关键节点弹窗 ═══
  // 指引①：章节大纲→写作（细纲完成即将写作），建议先布局连线框
  if (currentWorkflowStep === STEPS.章节大纲 && step === STEPS.写作) {
    try { showWireframeGuide('pre-write'); } catch(e) {}
  }
  // 指引②：时间线→连线框或草稿定稿，建议进入草稿定稿
  if (currentWorkflowStep === STEPS.时间线 && (step === STEPS.连线框 || step === STEPS.草稿定稿)) {
    try { showWireframeGuide('post-timeline'); } catch(e) {}
  }

  currentWorkflowStep = step;
  window.goToStep = goToStep; // 立即暴露到全局，避免后续代码出错导致未定义
  window._goToStepReal = goToStep; // 保存真实引用，防止 fallback 循环
  // 保存当前步骤到localStorage，刷新后恢复
  try { localStorage.setItem('shuzhai_last_step', step); } catch(e) {}

  // ══════════════════════════════════════════════════════════
  // 阶段一6：修UI状态一致性——步骤圈绿色对勾必须以对应表实际有数据为准（不能乱勾/不能按顺序无脑勾）
  // 真实数据来自后端 /api/project/workflow-step-status，对应9步（见 step-constants.js）：世界观/人物/全书大纲/分卷/章节大纲/连线框/写作/时间线/草稿定稿
  // ══════════════════════════════════════════════════════════
  function _renderStepIndicatorByRealData(currentStep, realStepsObj) {
    realStepsObj = realStepsObj || {};
    var stepMap = realStepsObj.steps || {};
    document.querySelectorAll('.step-item').forEach(function(item) {
      var s = parseInt(item.dataset.step);
      item.classList.remove('active', 'completed');
      var circle = item.querySelector('.step-circle');
      // 当前步骤：高亮active
      if (s === currentStep) {
        item.classList.add('active');
        if (circle) circle.textContent = String(s);
        return;
      }
      // 其他步骤：必须 realStepsObj.steps[s] === true（对应表有实际数据）才打绿色✓
      // —— 再也不用 s < currentStep 这种"凭感觉乱勾"的逻辑了
      if (stepMap[s] === true) {
        item.classList.add('completed');
        if (circle) circle.textContent = '✓';
      } else {
        if (circle) circle.textContent = String(s);
      }
    });
  }

  // ① 同步：先用缓存（上一次拉的真实状态）立刻渲染，用户不需要等
  _renderStepIndicatorByRealData(step, window._workflowStepCache || null);

  // ② 异步：立刻拉一次后端最新真实数据，刷新缓存 + 重新渲染UI（保证对勾永远最新）
  if (typeof api === 'function') {
    try {
      api('/api/project/workflow-step-status', {method: 'GET'}).then(function(_st) {
        if (_st && _st.ok && _st.data) {
          window._workflowStepCache = _st.data;
          // 注意：第二个参数用的是当前步骤 currentWorkflowStep（已经=step），避免用户又点了另一步导致高亮不一致
          _renderStepIndicatorByRealData(currentWorkflowStep, _st.data);
          // 同时同步到 workflowState.stepStatus（按真实数据写status，供其它模块读）
          if (typeof workflowState !== 'undefined' && workflowState && workflowState.stepStatus) {
            var _status = _st.data.steps || {};
            var _keys = Object.keys(_status);
            for (var _k = 0; _k < _keys.length; _k++) {
              var _idx = parseInt(_keys[_k]);
              if (!_idx || !workflowState.stepStatus[_idx]) continue;
              workflowState.stepStatus[_idx].status = _status[_idx] ? 'completed' :
                (_idx === currentWorkflowStep ? 'in-progress' : 'locked');
            }
          }
        }
      }).catch(function(e) { console.warn('[step-indicator] 异步刷新步骤状态失败：', e); });
    } catch(e) {}
  }

  // 同步 workflowState（允许自由切换，仅记录当前步骤）
  try {
    if (typeof workflowState !== 'undefined' && workflowState) {
      workflowState.currentStep = step;
      if (workflowState.stepStatus && workflowState.stepStatus[step]) {
        workflowState.stepStatus[step].status = 'in-progress';
      }
      // 保存到后端（静默）
      try {
        api('/api/workflow', {method:'POST', body: JSON.stringify(workflowState)});
      } catch(e) {}
    }
  } catch(e) { console.warn('workflowState sync failed:', e); }

  // Switch panel content
  document.querySelectorAll('.left-tab-content').forEach(c => c.classList.remove('active'));
  const panel = document.querySelector('.left-tab-content[data-step="' + step + '"]');
  if (panel) panel.classList.add('active');

  // 右侧面板仅有"记忆"标签，无需切换

  // Trigger renders
  if (step === 1) setTimeout(function() {
    if (typeof renderSettingsEditor === 'function') renderSettingsEditor();
    // 隐藏人物详情面板，恢复详情编辑器默认状态
    var charPanel = document.getElementById('char-detail-panel');
    if (charPanel) charPanel.style.display = 'none';
    // AI提取区域始终显示（方便用户随时补充分析）
    var extractBox = document.getElementById('ai-extract-box');
    if (extractBox) {
      extractBox.style.display = 'block';
    }
    // ── 绑定三个结构化卡片点击→显示到中间详情编辑面板 ──
    function _collectStructuredWorldFields() {
      var fields = [];
      // 叙事风格5字段
      var nsLabels = {'ns-pov':'叙事视角','ns-tense':'时态','ns-tone':'基调','ns-pacing':'节奏','ns-description':'描写风格'};
      for (var nid in nsLabels) { var nel = document.getElementById(nid); if (nel) fields.push({key:nid,label:nsLabels[nid],value:nel.value||'',type:(nel.tagName==='SELECT'?'select':'text'),source:'narrative'}); }
      // 时代环境5字段
      var eraLabels = {'era-tech':'科技水平','era-society':'社会制度','era-geography':'地理特征','era-culture':'文化背景','era-social-attitude':'社会态度'};
      for (var eid in eraLabels) { var eel = document.getElementById(eid); if (eel) fields.push({key:eid,label:eraLabels[eid],value:eel.value||'',type:'text',source:'era'}); }
      // 世界规则列表项
      if (typeof worldMeta !== 'undefined' && worldMeta.world_rules && Array.isArray(worldMeta.world_rules)) {
        worldMeta.world_rules.forEach(function(r, idx) {
          fields.push({key:'rule_'+idx,label:'世界规则 '+(idx+1),value:r.content||r||'',type:'textarea',source:'rules'});
        });
      }
      return fields;
    }
    var narBox = document.getElementById('world-meta-narrative');
    if (narBox && !narBox._bindedDetailClick) {
      narBox._bindedDetailClick = true;
      narBox.style.cursor = 'pointer';
      narBox.addEventListener('click', function(e) {
        if (e.target.closest('button') || e.target.closest('select') || e.target.closest('input')) return;
        var all = _collectStructuredWorldFields();
        var nsF = all.filter(function(x){return x.source==='narrative';});
        showDetailEditor('叙事风格 · 共5项', '✍️ 叙事风格 · 结构化字段', null, {type:'setting-group',group:'叙事风格',fields:nsF});
      });
    }
    var eraBox = document.getElementById('world-meta-era');
    if (eraBox && !eraBox._bindedDetailClick) {
      eraBox._bindedDetailClick = true;
      eraBox.style.cursor = 'pointer';
      eraBox.addEventListener('click', function(e) {
        if (e.target.closest('button') || e.target.closest('input')) return;
        var all = _collectStructuredWorldFields();
        var eF = all.filter(function(x){return x.source==='era';});
        showDetailEditor('时代环境 · 共5项', '🌍 时代环境 · 结构化字段', null, {type:'setting-group',group:'时代环境',fields:eF});
      });
    }
    var ruleBox = document.getElementById('world-meta-rules');
    if (ruleBox && !ruleBox._bindedDetailClick) {
      ruleBox._bindedDetailClick = true;
      ruleBox.style.cursor = 'pointer';
      ruleBox.addEventListener('click', function(e) {
        if (e.target.closest('button') || e.target.closest('input') || e.target.closest('textarea')) return;
        var all = _collectStructuredWorldFields();
        var rF = all.filter(function(x){return x.source==='rules';});
        showDetailEditor('世界规则 · 共'+rF.length+'项', '⚖️ 世界规则 · 列表', null, {type:'setting-group',group:'世界规则',fields:rF.length?rF:[{key:'empty',label:'暂无规则',value:'点击下方「+ 添加规则」按钮添加世界规则',type:'textarea',source:'rules'}]});
      });
    }
  }, 0);
  if (step === STEPS.全书大纲) {
    // 全书大纲：渲染结构化大纲编辑器
    setTimeout(async function() {
      var nvEd = document.getElementById('novel-outline-editor');
      if (nvEd) {
        nvEd.innerHTML = ''; // 清空旧内容重新渲染
        await _renderNovelOutline();
      }
    }, 0);
  }
  if (step === STEPS.人物) {
    // 人物：加载人物列表并显示人物详情面板
    setTimeout(function() {
      if (typeof loadCharacters === 'function') loadCharacters().then(function() { if (typeof renderCharacterList === 'function') renderCharacterList(); }); else if (typeof renderCharacterList === 'function') renderCharacterList();
      // 显示人物详情面板
      var charPanel = document.getElementById('char-detail-panel');
      var emptyEl = document.getElementById('detail-editor-empty');
      var headerEl = document.getElementById('detail-editor-header');
      if (charPanel) charPanel.style.display = 'block';
      if (emptyEl) emptyEl.style.display = 'none';
      if (headerEl) headerEl.classList.add('hidden');
    }, 0);
  }
  if (step === 4) {
    // 步骤4=分卷纲要
    setTimeout(async function() {
      // 隐藏人物详情面板
      var charPanel = document.getElementById('char-detail-panel');
      if (charPanel) charPanel.style.display = 'none';
      // 隐藏详情编辑器默认元素
      var detailEmpty = document.getElementById('detail-editor-empty');
      var detailHeader = document.getElementById('detail-editor-header');
      var detailTextarea = document.getElementById('detail-editor-textarea');
      if (detailEmpty) detailEmpty.style.display = 'none';
      if (detailHeader) detailHeader.classList.add('hidden');
      if (detailTextarea) detailTextarea.classList.add('hidden');
      // 显示分卷详情面板
      var volPanel = document.getElementById('vol-detail-panel');
      if (volPanel) volPanel.style.display = 'block';
      // 确保 _novelOutlineDict 已加载（用于空状态下AI分卷按钮判断）
      if (typeof _novelOutlineDict === 'undefined' || !_novelOutlineDict || Object.keys(_novelOutlineDict).length === 0) {
        try {
          var nloData = await api('/api/project/novel-outline');
          if (nloData.ok && nloData.novel_outline) {
            _novelOutlineDict = nloData.novel_outline;
          }
        } catch(e) {}
      }
      await loadVolumesData();
      renderVolumeOutlineList();
      _currentVolumeEditIndex = -1;
      // 显示空状态提示
      var volEmpty = document.getElementById('vol-detail-empty');
      var volForm = document.getElementById('vol-detail-form');
      if (volEmpty) volEmpty.style.display = 'block';
      if (volForm) volForm.style.display = 'none';
    }, 0);
  }
  if (step === 5) {
    // 步骤5=章节大纲
    setTimeout(function() {
      // 隐藏人物详情面板
      var charPanel = document.getElementById('char-detail-panel');
      if (charPanel) charPanel.style.display = 'none';
      loadChapterOutline(currentChapterIndex);
      loadVolumesData().then(function() { loadChapterVolumeOutline(); });
      if (typeof renderChapterOutlineEditor === 'function') renderChapterOutlineEditor();
      renderChapterDropdown('chapter-dropdown-outline', currentChapterIndex, function(idx) {
        loadChapterOutline(idx);  // 内部会保存旧章节并设置currentChapterIndex
        currentChapterIndex = idx;
        loadChapterVolumeOutline();
        renderChapterOutlineEditor();
        loadForeshadows();
        if (typeof updateWritingToolbar === 'function') updateWritingToolbar();
        // 流水线联动：正文生成后触发票据更新（deferred to avoid blocking）
        try { fetch('/api/generate/extract-state', { method: 'POST', body: JSON.stringify({ content: '', chapter_idx: currentChapterIndex + 1, title: (chapters && chapters[currentChapterIndex]) ? chapters[currentChapterIndex].title : '' }) }).catch(function(){}); } catch(e2) {}
      });
      // 加载伏笔
      loadForeshadows();
    }, 0);
  }
  if (step === STEPS.写作) {
    // 写作步骤 - 显示编辑器
    setTimeout(function() { if (typeof updateWritingToolbar === 'function') updateWritingToolbar(); }, 0);
  }
  if (step === STEPS.时间线) {
    // 时间线 - 先加载时间线数据，再渲染左侧章节列表
    setTimeout(function() {
      var tlLoad = (typeof Timeline !== 'undefined' && Timeline.load) ? Timeline.load() : Promise.resolve({ok: false});
      tlLoad.then(function(tlRes) {
        if (!tlRes || !tlRes.ok) {
          console.warn('[goToStep 时间线] Timeline.load failed, left nav may be incomplete');
        }
        // 渲染章节列表到左抽屉，并从实际内容文件获取字数
        loadVolumesData().then(function() {
          // 从时间线API获取 has_content 状态，从章节API获取实际字数
          var timelineHasContent = {};
          api('/api/timeline').then(function(tlRes2) {
            if (tlRes2 && tlRes2.chapters) {
              for (var k in tlRes2.chapters) {
                timelineHasContent[k] = tlRes2.chapters[k].has_content || false;
              }
            }
          }).catch(function(){});
          var wordPromises = (chapters || []).map(function(ch, i) {
            return api('/api/chapter/load?index=' + i + '&_t=' + Date.now()).then(function(res) {
              chapters[i]._actual_words = (res && res.ok && res.content && res.content.trim()) ? (res.word_count || 0) : 0;
              chapters[i]._has_content = !!(res && res.ok && res.content && res.content.trim().length > 100);
            }).catch(function() {
              chapters[i]._actual_words = 0;
              chapters[i]._has_content = false;
            });
          });
          Promise.all(wordPromises).then(function() {
            renderVolumeNav('vol-nav-timeline', function(idx) {
              syncChapterAcrossPanels(idx);
            });
            // 默认选中当前章节
            if (typeof currentChapterIndex !== 'undefined' && currentChapterIndex >= 0) {
              syncChapterAcrossPanels(currentChapterIndex);
            }
          });
        });
      });
    }, 0);
    // 时间线步骤：隐藏右侧抽屉
    var rightDrawer = document.querySelector('.right-drawer');
    if (rightDrawer) rightDrawer.style.display = 'none';
  } else {
    // 非时间线步骤：显示右侧抽屉
    var rightDrawer = document.querySelector('.right-drawer');
    if (rightDrawer) rightDrawer.style.display = 'flex';
  }
  // 时间线模式：时间线步骤时使用编辑器区域显示全屏时间线
  var mainEl = document.querySelector('.main');
  if (mainEl) {
    if (step === STEPS.时间线) {
      mainEl.classList.add('timeline-mode');
    } else {
      mainEl.classList.remove('timeline-mode');
    }
  }
  // Toggle editor mode: writing (写作) vs detail editor (其他步骤) vs timeline (时间线)
  var editorPaper = document.getElementById('editor-paper');
  var detailPanel = document.getElementById('detail-editor-panel');
  var timelineFullEditor = document.getElementById('timeline-full-editor');
  if (editorPaper && detailPanel) {
    if (step === STEPS.写作) {
      editorPaper.style.display = 'block';
      detailPanel.classList.remove('active');
      if (timelineFullEditor) timelineFullEditor.style.display = 'none';
    } else if (step === STEPS.时间线) {
      editorPaper.style.display = 'none';
      detailPanel.classList.remove('active');
      if (timelineFullEditor) timelineFullEditor.style.display = 'flex';
    } else {
      editorPaper.style.display = 'none';
      detailPanel.classList.add('active');
      if (timelineFullEditor) timelineFullEditor.style.display = 'none';
      // Reset detail editor to empty state
      if (step !== STEPS.时间线) showDetailEditorEmpty();
    }
  }

  // Toggle writing toolbar (仅写作步骤显示)
  var wt = document.getElementById('writing-toolbar');
  if (wt) wt.style.display = (step === STEPS.写作) ? 'flex' : 'none';

  if (step === STEPS.写作) {
    setTimeout(async function() {
      // 确保章节数据已加载
      if (typeof loadChaptersFromAPI === 'function') {
        try { await loadChaptersFromAPI(); } catch(e2) { console.warn('loadChapters failed:', e2); }
      }
      if (typeof renderChapterMiniList === 'function') renderChapterMiniList();
      // 加载卷数据并渲染卷导航
      loadVolumesData().then(function() {
        renderVolumeNav('vol-nav-writing', async function(idx) {
          syncChapterAcrossPanels(idx);
          if (typeof updateWritingToolbar === 'function') updateWritingToolbar();
        });
      });
      // Auto-load current chapter content into editor
      if (typeof loadChapterContentAPI === 'function' && currentChapterIndex >= 0) {
        loadChapterContentAPI(currentChapterIndex);
      }
      // 写作步骤自动展开右侧面板（检查面板）
      var rightDrawer = document.querySelector('.right-drawer');
      if (rightDrawer && rightDrawer.classList.contains('collapsed')) {
        rightDrawer.classList.remove('collapsed');
      }
      // 检查标签已移除，无需切换
      // Bind writing toolbar buttons
      var wtGen = document.getElementById('wt-btn-gen');
      var wtSave = document.getElementById('wt-btn-save');
      if (wtGen) wtGen.onclick = function() { document.getElementById('btn-ai-gen')?.click(); };
      if (wtSave) wtSave.onclick = function() { document.getElementById('btn-save')?.click(); };
      var wtFlavor = document.getElementById('wt-btn-flavor');
      if (wtFlavor) wtFlavor.onclick = async function() {
        var el = document.getElementById('editor-content');
        if (!el || !(el.innerText || '').trim()) { showToast('没有内容可检测'); return; }
        var origText = this.textContent;
        this.disabled = true; this.textContent = '⏳ 检测中…';
        try {
          var content = el.innerText || '';
          var result = (typeof AuditJS !== 'undefined' && AuditJS.detectAiFlavor) ? AuditJS.detectAiFlavor(content) : null;
          if (result && result.score !== undefined) {
            showToast('AI味评分: ' + result.score + '/100 ' + (result.summary || ''));
          } else { showToast('检测完成'); }
        } catch(e) { console.error(e); showToast('检测出错'); }
        this.disabled = false; this.textContent = origText;
      };
      // Update toolbar info
      updateWritingToolbar();
      // 写作步骤时，如果正文为空，在编辑器下方显示大纲参考
      setTimeout(function() {
        var editorEl = document.getElementById('editor-content');
        var editorTitle = document.getElementById('editor-title');
        if (editorEl && (!editorEl.innerText || editorEl.innerText.trim().length < 10)) {
          // 正文为空，显示大纲参考
          var ch = chapters[currentChapterIndex];
          if (ch && ch.outline) {
            var outlineHtml = '<div style="padding:20px;background:var(--bg);border-radius:8px;margin:20px 0;">';
            outlineHtml += '<h3 style="color:var(--accent);margin-bottom:10px;">📋 本章大纲（参考）</h3>';
            outlineHtml += '<div style="color:var(--muted);font-size:13px;line-height:1.8;">';
            var outlineText = typeof ch.outline === 'string' ? ch.outline : ch.outline.map(function(o){return o.text||o;}).join('\n');
            outlineHtml += outlineText.replace(/\n/g, '<br>');
            outlineHtml += '</div></div>';
            editorEl.innerHTML = outlineHtml;
            if (editorTitle) editorTitle.textContent = ch.title || ('第' + (currentChapterIndex + 1) + '章');
          }
        }
      }, 500);
    }, 0);
  }
}

})();

// ── js/glue-xtra.js ──
(function() {
  'use strict';


// ══ 伏笔管理 ══
var foreshadowHooks = [];

window.loadForeshadows = function() {
  var ch = (typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0) + 1;
  api('/api/project/hooks?current_chapter=' + ch).then(function(r) {
    if (r.ok) {
      foreshadowHooks = r.hooks || [];
      var overdue = r.overdue || [];
      var active = foreshadowHooks.filter(function(h) { return h.status === 'planted' || h.status === 'active'; });
      var summary = document.getElementById('foreshadow-count');
      if (summary) {
        var txt = '共' + foreshadowHooks.length + '个';
        if (active.length) txt += ' | 待回收' + active.length;
        if (overdue.length) txt += ' | ⚠️逾期' + overdue.length;
        summary.textContent = txt;
        summary.style.color = overdue.length ? '#e74c3c' : 'var(--muted)';
      }
    }
  }).catch(function() {});
}

window.renderForeshadowList = function() {
  var list = document.getElementById('foreshadow-list');
  if (!list) return;
  list.innerHTML = '';
  if (foreshadowHooks.length === 0) {
    list.innerHTML = '<div class="empty-state-sm" >还没有伏笔<br>在下方输入伏笔内容并种植</div>';
    updateForeshadowStats();
    return;
  }
  var curCh = (typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0) + 1;
  var statusColors = {
    'planted': '#3498db', 'active': '#3498db',
    'recovered': '#27ae60', 'abandoned': '#95a5a6'
  };
  var statusLabels = {
    'planted': '待回收', 'active': '待回收',
    'recovered': '已回收', 'abandoned': '已放弃'
  };
  foreshadowHooks.forEach(function(h) {
    var expected = h.expected_recovery_chapter || 0;
    var isOverdue = (h.status === 'planted' || h.status === 'active') && expected > 0 && expected < curCh;
    var item = document.createElement('div');
    var borderColor = isOverdue ? '#e74c3c' : 'var(--border-soft)';
    var bgColor = isOverdue ? 'rgba(231,76,60,0.06)' : 'var(--surface)';
    item.style.cssText = 'padding:8px 10px;margin-bottom:6px;border:1px solid ' + borderColor + ';border-radius:6px;background:' + bgColor;
    var color = statusColors[h.status] || '#999';
    var label = statusLabels[h.status] || h.status;
    var html = '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">' +
      '<div class="flex-1" >' +
        '<div style="font-size:12px;color:var(--ink);margin-bottom:2px">' + (isOverdue ? '<span style="color:#e74c3c;font-weight:600">⚠️逾期 </span>' : '') + escapeHtml(h.content) + '</div>' +
        '<div class="text-xs text-muted" >种植:第' + h.planted_chapter + '章' +
          (expected ? ' | 预期回收:第' + expected + '章' : '') +
        '</div>' +
        (h.note ? '<div style="font-size:10px;color:var(--muted);margin-top:2px">' + escapeHtml(h.note) + '</div>' : '') +
      '</div>' +
      '<span style="font-size:9px;padding:2px 6px;border-radius:3px;background:' + color + ';color:#fff;white-space:nowrap">' + label + '</span>' +
    '</div>';
    // 操作按钮
    if (h.status === 'planted' || h.status === 'active') {
      html += '<div style="display:flex;gap:4px;margin-top:6px">' +
        '<button onclick="recoverHook(\'' + h.id + '\')" style="flex:1;padding:3px 8px;font-size:10px;border:1px solid #27ae60;color:#27ae60;background:transparent;border-radius:4px;cursor:pointer">标记已回收</button>' +
        '<button onclick="abandonHook(\'' + h.id + '\')" style="flex:1;padding:3px 8px;font-size:10px;border:1px solid #e74c3c;color:#e74c3c;background:transparent;border-radius:4px;cursor:pointer">放弃</button>' +
      '</div>';
    }
    item.innerHTML = html;
    list.appendChild(item);
  });
  updateForeshadowStats();
}

window.updateForeshadowStats = function() {
  var curCh = (typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0) + 1;
  var active = foreshadowHooks.filter(function(h) { return h.status === 'planted' || h.status === 'active'; });
  var recovered = foreshadowHooks.filter(function(h) { return h.status === 'recovered'; });
  var overdue = active.filter(function(h) { return (h.expected_recovery_chapter || 0) > 0 && (h.expected_recovery_chapter || 0) < curCh; });
  var el = function(id, v) { var e = document.getElementById(id); if (e) e.textContent = v; };
  el('fs-active', active.length);
  el('fs-recovered', recovered.length);
  el('fs-overdue', overdue.length);
}

window.plantHook = function() {
  var content = val('hook-content');
  var planted = parseInt(val('hook-planted')) || 1;
  var expected = parseInt(val('hook-expected')) || 0;
  if (!content) { alert('请输入伏笔内容'); return; }
  // 后端新增端点为 /api/project/hooks/add（HookAdd 模型）；旧路径 POST /api/project/hooks 不存在会 404
  api('/api/project/hooks/add', {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({
      content: content,
      planted_chapter: planted,
      expected_recovery_chapter: expected,
      related_characters: [],
      note: ''
    })
  }).then(function(r) {
    if (r.ok) {
      document.getElementById('hook-content').value = '';
      document.getElementById('hook-expected').value = '';
      loadForeshadows();
      renderForeshadowList();
    } else {
      alert('种植失败: ' + (r.error || ''));
    }
  });
}

window.recoverHook = function(hid) {
  var ch = (typeof currentChapterIndex !== 'undefined' ? currentChapterIndex : 0) + 1;
  api('/api/project/hooks/recover', {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({hook_id: hid, chapter: ch})
  }).then(function(r) {
    if (r.ok) { loadForeshadows(); renderForeshadowList(); }
  });
}

window.abandonHook = function(hid) {
  if (!confirm('确定放弃这个伏笔？')) return;
  api('/api/project/hooks/abandon', {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({hook_id: hid, reason: '手动放弃'})
  }).then(function(r) {
    if (r.ok) { loadForeshadows(); renderForeshadowList(); }
  });
}

// ══ 支线标记 ══
window.updatePlotLine = function(checkbox) {
  if (typeof chapters === 'undefined' || !chapters[currentChapterIndex]) return;
  if (!chapters[currentChapterIndex].blueprint) chapters[currentChapterIndex].blueprint = {};
  var lines = chapters[currentChapterIndex].blueprint.plot_line || ['主线'];
  if (!Array.isArray(lines)) lines = ['主线'];
  var line = checkbox.value;
  if (checkbox.checked) {
    if (lines.indexOf(line) < 0) lines.push(line);
  } else {
    // 不能取消最后一个
    if (lines.length <= 1) { checkbox.checked = true; return; }
    lines = lines.filter(function(l) { return l !== line; });
  }
  chapters[currentChapterIndex].blueprint.plot_line = lines;
  // 保存到后端
  saveChapterBlueprint(currentChapterIndex);
}

window.saveChapterBlueprint = function(idx) {
  if (typeof chapters === 'undefined' || !chapters[idx]) return;
  try {
    api('/api/chapter/' + idx + '/blueprint', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({blueprint: chapters[idx].blueprint || {}})
    });
  } catch(e) {}
}

// ══ 人物档案系统 ══
var characters = []; // 人物列表
var _selectedCharIdx = -1; // 当前在中间面板选中的人物索引

window.renderCharacterList = function() {
  var listEl = document.getElementById('character-list');
  if (!listEl) return;
  renderCharChapterSelect();
  renderChapterCharList();
  listEl.innerHTML = '';
  if (characters.length === 0) {
    listEl.innerHTML = '<div >还没有人物档案<br>点击上方"+ 添加"开始创建</div>';
    showCharDetail(-1);
    return;
  }
  characters.forEach(function(char, idx) {
    var card = document.createElement('div');
    card.className = 'char-card' + (idx === _selectedCharIdx ? ' char-card-active' : '');
    card.innerHTML =
      '<div class="char-card-header empty-state-sm" onclick="selectCharacter(' + idx + ')">' +
        '<span class="char-name">' + escapeHtml(char.name || '未命名') + '</span>' +
        '<span class="char-role">' + escapeHtml(char.identity || char.role || char.faction || '') + '</span>' +
      '</div>';
    listEl.appendChild(card);
  });
  // 自动选中第一个或保持之前的选中
  if (_selectedCharIdx >= 0 && _selectedCharIdx < characters.length) {
    showCharDetail(_selectedCharIdx);
  } else if (characters.length > 0) {
    selectCharacter(0);
  } else {
    showCharDetail(-1);
  }
}

window.selectCharacter = function(idx) {
  _selectedCharIdx = idx;
  // 更新左侧卡片高亮
  var cards = document.querySelectorAll('#character-list .char-card');
  cards.forEach(function(c, i) {
    c.classList.toggle('char-card-active', i === idx);
  });
  showCharDetail(idx);
}

window.showCharDetail = function(idx) {
  var panel = document.getElementById('char-detail-panel');
  var emptyEl = document.getElementById('detail-editor-empty');
  var headerEl = document.getElementById('detail-editor-header');
  if (!panel) return;
  // 只在步骤3（人物）显示人物面板
  if (typeof currentWorkflowStep === 'undefined' || currentWorkflowStep !== STEPS.人物) {
    panel.style.display = 'none';
    return;
  }
  panel.style.display = 'block';
  if (emptyEl) emptyEl.style.display = 'none';
  if (headerEl) headerEl.classList.add('hidden');

  if (idx < 0 || idx >= characters.length) {
    document.getElementById('char-detail-title').textContent = '选择人物';
    document.getElementById('char-detail-subtitle').textContent = '点击左侧人物卡片进行编辑';
    document.getElementById('char-detail-avatar').textContent = '👤';
    document.getElementById('char-detail-actions').innerHTML = '';
    document.getElementById('char-detail-form').innerHTML = '<div class="empty-state-lg" >← 请从左侧选择一个人物<br>在此处编辑详细档案</div>';
    return;
  }
  var ch = characters[idx];
  document.getElementById('char-detail-title').textContent = ch.name || '未命名';
  document.getElementById('char-detail-subtitle').textContent = ch.identity || ch.faction || '角色';
  document.getElementById('char-detail-avatar').textContent = ch.name ? ch.name.charAt(0) : '👤';
  document.getElementById('char-detail-actions').innerHTML =
    '<button onclick="aiGenCharDetail()" title="AI丰富此人物" style="padding:4px 10px;border:1px solid var(--border);background:var(--surface);color:var(--muted);border-radius:4px;font-size:11px;cursor:pointer">🤖</button>' +
    '<button onclick="deleteCharacter(' + idx + ')" title="删除人物" style="padding:4px 10px;border:1px solid rgba(212,80,80,0.3);background:rgba(212,80,80,0.05);color:var(--danger);border-radius:4px;font-size:11px;cursor:pointer">🗑</button>';

  // 渲染大表单
  var fields = [
    {key:'name', label:'姓名', type:'input', placeholder:'角色名称'},
    {key:'identity', label:'身份', type:'input', placeholder:'如：剑客/商人/程序员/皇子'},
    {key:'faction', label:'阵营', type:'select', options:['主角','配角','反派','中立']},
    {key:'importance', label:'角色定位', type:'select', options:['核心人物','次要人物']},
    {key:'personality', label:'性格', type:'input', placeholder:'如：冷静/冲动/阴沉/开朗'},
    {key:'background', label:'身世过往', type:'textarea', rows:4, placeholder:'角色的成长经历、重要事件'},
    {key:'obsession', label:'执念', type:'input', placeholder:'内心最深的渴望'},
    {key:'weakness', label:'软肋', type:'input', placeholder:'致命弱点或情感盲区'},
    {key:'goal', label:'目标', type:'textarea', rows:2, placeholder:'每行一个目标，格式：目标描述|权重(0~1)\n示例：通过内门考核|0.8'},
    {key:'bonds', label:'人物羁绊', type:'textarea', rows:3, placeholder:'与其他角色的关系和羁绊'},
    {key:'appearance', label:'外貌特征', type:'textarea', rows:2, placeholder:'容貌、体型、标志性特征'},
    {key:'speech', label:'语言风格', type:'textarea', rows:2, placeholder:'说话的语气、口头禅、措辞习惯'},
    {key:'habits', label:'行为习惯', type:'textarea', rows:2, placeholder:'日常习惯、小动作、癖好'},
    {key:'catchphrase', label:'口头禅', type:'input', placeholder:'标志性台词或口头禅'},
    {key:'cognitive_boundary', label:'认知边界', type:'textarea', rows:2, placeholder:'角色不知道的信息/领域限制\n如：不知道幕后主使是谁、不了解外界世界'},
    {key:'key_events', label:'重要经历', type:'textarea', rows:3, placeholder:'人生中的关键事件和转折点'}
  ];
  var html = '';
  fields.forEach(function(f) {
    html += '<div class="char-detail-field">';
    html += '<label>' + f.label + '</label>';
    if (f.type === 'input') {
      html += '<input type="text" data-cidx="' + idx + '" data-cfield="' + f.key + '" value="' + escapeHtml(ch[f.key]||'') + '" placeholder="' + (f.placeholder||'') + '">';
    } else if (f.type === 'textarea') {
      html += '<textarea data-cidx="' + idx + '" data-cfield="' + f.key + '" rows="' + (f.rows||3) + '" placeholder="' + (f.placeholder||'') + '">' + escapeHtml(ch[f.key]||'') + '</textarea>';
    } else if (f.type === 'select') {
      html += '<select data-cidx="' + idx + '" data-cfield="' + f.key + '">';
      (f.options||[]).forEach(function(opt) {
        html += '<option value="' + opt + '"' + (ch[f.key]===opt?' selected':'') + '>' + opt + '</option>';
      });
      html += '</select>';
    }
    html += '</div>';
  });
  document.getElementById('char-detail-form').innerHTML = html;

  // 绑定输入事件：实时保存
  panel.querySelectorAll('input,textarea,select').forEach(function(input) {
    input.addEventListener('input', function() {
      var i = parseInt(this.dataset.cidx);
      var f = this.dataset.cfield;
      if (!isNaN(i) && f) {
        characters[i][f] = this.value;
        saveCharacters();
        // 姓名或身份变化时更新左侧卡片和标题
        if (f === 'name' || f === 'identity' || f === 'faction') {
          var nameEl = document.getElementById('char-detail-title');
          var subEl = document.getElementById('char-detail-subtitle');
          var avatarEl = document.getElementById('char-detail-avatar');
          if (nameEl) nameEl.textContent = characters[i].name || '未命名';
          if (subEl) subEl.textContent = characters[i].identity || characters[i].faction || '角色';
          if (avatarEl) avatarEl.textContent = characters[i].name ? characters[i].name.charAt(0) : '👤';
          renderCharacterList(); // 重渲染左侧列表
        }
      }
    });
  });
}

// ===== 章节人物功能 =====
var charChapterIndex = 0; // 人物面板当前选中的章节

window.renderCharChapterSelect = function() {
  var sel = document.getElementById('char-chapter-select');
  if (!sel) return;
  sel.innerHTML = '';
  var chs = (typeof chapters !== 'undefined') ? chapters : [];
  chs.forEach(function(ch, i) {
    var opt = document.createElement('option');
    opt.value = i;
    opt.textContent = '第' + (i+1) + '章' + (ch.title ? ' · ' + ch.title : '');
    sel.appendChild(opt);
  });
  if (charChapterIndex < chs.length) sel.value = String(charChapterIndex);
}

window.onCharChapterChange = function(val) {
  charChapterIndex = parseInt(val) || 0;
  renderChapterCharList();
}

window.renderChapterCharList = function() {
  var listEl = document.getElementById('chapter-char-list');
  if (!listEl) return;
  listEl.innerHTML = '';
  var chs = (typeof chapters !== 'undefined') ? chapters : [];
  var ch = chs[charChapterIndex];
  if (!ch) {
    listEl.innerHTML = '<div class="label-muted-inline-sm" >无章节数据</div>';
    return;
  }
  // 从blueprint获取章节人物节点
  var nodes = (ch.blueprint && ch.blueprint.character_nodes) ? ch.blueprint.character_nodes : [];
  if (nodes.length === 0) {
    listEl.innerHTML = '<div class="label-muted-inline-sm" >本章暂无出场人物</div>';
  } else {
    nodes.forEach(function(node, i) {
      var item = document.createElement('div');
      item.style.cssText = 'display:flex;align-items:center;gap:6px;padding:4px 8px;background:var(--surface);border-radius:4px;border:1px solid var(--border-soft)';
      var charInfo = (typeof characters !== 'undefined') ? characters.find(function(c){return c.name === node.name;}) : null;
      var faction = charInfo ? charInfo.faction : '';
      item.innerHTML = '<span style="font-size:11px;font-weight:600;color:var(--ink)">' + escapeHtml(node.name||'') + '</span>' +
        (faction ? '<span style="font-size:10px;color:var(--muted);padding:1px 4px;background:var(--bg);border-radius:2px">' + escapeHtml(faction) + '</span>' : '') +
        '<span style="font-size:10px;color:var(--muted);flex:1">' + escapeHtml(node.appearance||'') + '</span>' +
        '<button onclick="removeCharFromChapter(' + i + ')" style="font-size:10px;color:#c44;border:none;background:none;cursor:pointer;padding:2px">✕</button>';
      listEl.appendChild(item);
    });
  }
  // 添加人物到章节的下拉框
  var addDiv = document.createElement('div');
  addDiv.style.cssText = 'display:flex;gap:4px;margin-top:4px';
  var sel = document.createElement('select');
  sel.id = 'char-add-to-chapter';
  sel.style.cssText = 'flex:1;font-size:10px;padding:2px 4px;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--ink)';
  sel.innerHTML = '<option value="">+ 从全书人物中添加…</option>';
  if (typeof characters !== 'undefined') {
    characters.forEach(function(c) {
      var already = nodes.some(function(n) { return n.name === c.name; });
      if (!already) {
        var opt = document.createElement('option');
        opt.value = c.name;
        opt.textContent = c.name + ' (' + (c.faction||'') + ')';
        sel.appendChild(opt);
      }
    });
  }
  var addBtn = document.createElement('button');
  addBtn.textContent = '添加';
  addBtn.style.cssText = 'font-size:10px;padding:2px 8px;border:1px solid var(--accent);border-radius:3px;background:var(--accent);color:#fff;cursor:pointer';
  addBtn.onclick = function() {
    var name = document.getElementById('char-add-to-chapter').value;
    if (!name) return;
    addCharToChapter(name);
  };
  addDiv.appendChild(sel);
  addDiv.appendChild(addBtn);
  listEl.appendChild(addDiv);
}

window.addCharToChapter = function(name) {
  var chs = (typeof chapters !== 'undefined') ? chapters : [];
  var ch = chs[charChapterIndex];
  if (!ch) return;
  if (!ch.blueprint) ch.blueprint = {};
  if (!ch.blueprint.character_nodes) ch.blueprint.character_nodes = [];
  ch.blueprint.character_nodes.push({name: name, appearance: 'main', status_change: ''});
  // 保存到后端
  if (typeof saveChapterBlueprint === 'function') saveChapterBlueprint(charChapterIndex);
  else if (typeof saveChapterOutline === 'function') saveChapterOutline();
  renderChapterCharList();
  showToast('已添加「' + name + '」到第' + (charChapterIndex+1) + '章');
}

window.removeCharFromChapter = function(idx) {
  var chs = (typeof chapters !== 'undefined') ? chapters : [];
  var ch = chs[charChapterIndex];
  if (!ch || !ch.blueprint || !ch.blueprint.character_nodes) return;
  ch.blueprint.character_nodes.splice(idx, 1);
  if (typeof saveChapterBlueprint === 'function') saveChapterBlueprint(charChapterIndex);
  else if (typeof saveChapterOutline === 'function') saveChapterOutline();
  renderChapterCharList();
  showToast('已移除');
}

window.toggleCharCard = function(idx) {
  var body = document.getElementById('char-body-' + idx);
  if (body) body.style.display = body.style.display === 'none' ? 'block' : 'none';
}

window.addCharacter = function() {
  characters.push({
    name: '新人物', identity: '', faction: '配角', personality: '',
    background: '', obsession: '', weakness: '', goal: '', goals: [], bonds: [], importance: '次要',
    cognitive_boundary: ''
  });
  renderCharacterList();
  saveCharacters();
  // 自动展开新卡片
  setTimeout(function() { toggleCharCard(characters.length - 1); }, 50);
}

window.deleteCharacter = function(idx) {
  characters.splice(idx, 1);
  renderCharacterList();
  saveCharacters();
}

window.saveCharacters = function() {
  try {
    // 将 goal textarea 解析为 goals 数组
    characters.forEach(function(ch) {
      if (typeof ch.goal === 'string' && ch.goal.trim()) {
        var lines = ch.goal.split('\n').filter(function(l) { return l.trim(); });
        ch.goals = lines.map(function(line) {
          var parts = line.split('|');
          if (parts.length >= 2) {
            var w = parseFloat(parts[parts.length - 1].trim());
            if (!isNaN(w)) {
              return {text: parts.slice(0, -1).join('|').trim(), weight: Math.max(0, Math.min(1, w))};
            }
          }
          return {text: line.trim(), weight: 1.0};
        });
      } else if (!ch.goal || !ch.goal.trim()) {
        ch.goals = [];
      }
    });
    var settings = getSettings ? getSettings() : null;
    // 存到project settings里
    api('/api/project/settings', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({characters: characters})
    });
  } catch(e) {}
}

window.loadCharacters = function() {
  return getSettings().then(function(data) {
    characters = (data && data.characters) || [];
    // 将 goals 数组反填到 goal 字段供 textarea 显示
    characters.forEach(function(ch) {
      if (ch.goals && ch.goals.length && !ch.goal) {
        ch.goal = ch.goals.map(function(g) {
          if (typeof g === 'object') return g.text + '|' + (g.weight || 1.0);
          return g + '|1.0';
        }).join('\n');
      }
    });
  }).catch(function() { characters = []; });
}
window.advanceHook = function(id){api('/api/project/hooks/advance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:id,chapter_index:(typeof currentChapterIndex!=="undefined"?currentChapterIndex:0)})}).then(function(d){if(d.ok)loadHooksPanel()});}
window.recoverHook = function(id){api('/api/project/hooks/recover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:id,chapter_index:(typeof currentChapterIndex!=="undefined"?currentChapterIndex:0)})}).then(function(d){if(d.ok)loadHooksPanel()});}
window.abandonHook = function(id){if(!confirm('确认放弃此伏笔？'))return;api('/api/project/hooks/abandon',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:id})}).then(function(d){if(d.ok)loadHooksPanel()});}

// 全书优化诊断

/* ===== Plugin Framework ===== */
var _plugins = [];
var _pluginBarVisible = false;

window.registerPlugin = function(id, name, icon, callback) {
  _plugins.push({id: id, name: name, icon: icon, callback: callback});
  if (_pluginBarVisible) renderPluginBar();
}
window.togglePluginBar = function() {
  _pluginBarVisible = !_pluginBarVisible;
  var bar = document.getElementById('plugin-bar');
  if (bar) bar.style.display = _pluginBarVisible ? 'block' : 'none';
  if (_pluginBarVisible) renderPluginBar();
}

window._fetchAndRenderGraph = async function() {
  try {
    var r = await api('/api/engine/graph');
    _graphNodes = (r && r.nodes) || [];
    _graphEdges = (r && r.edges) || [];
    if (_graphNodes.length === 0) {
      var container = document.getElementById('graph-svg-container');
      if (container) container.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--muted);font-size:14px">暂无角色关系数据<br><span style="font-size:12px">请先创建角色档案</span></div>';
      return;
    }
    _renderGraphSVG();
  } catch(e) {
    var container = document.getElementById('graph-svg-container');
    if (container) container.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--danger);font-size:14px">加载失败: ' + e.message + '</div>';
  }
}

window.addVolumeOutlineDynItem = function(containerId) {
  var container = document.getElementById(containerId);
  if (!container) return;
  var div = document.createElement('div');
  div.style.cssText = 'display:flex;gap:4px;margin-bottom:4px;align-items:center';
  div.innerHTML = '<input class="input-flex-sm" type="text" value="" >' +
    '<button class="btn-danger-md" onclick="this.parentElement.remove()"  title="删除">&times;</button>';
  container.appendChild(div);
}

window.showWireframeGuide = showWireframeGuide;
window.showWireframeBanner = showWireframeBanner;

})();